    private static bool IsBinkExclusiveActiveLocked()
    {
        if ((!_binkExclusivePresentation &&
             !_naturalBinkDescriptorlessDirectFallbackActive) ||
            _binkExclusiveFrame is null)
        {
            return false;
        }

        var now = Environment.TickCount64;
        var sessionLive =
            _binkSessionActive &&
            (_binkWallClockSessions
                ? !_binkSessionCompleted
                : now - _binkSessionLastFrameTick <= _binkSessionGraceMs);

        if (sessionLive || now <= _binkExclusiveUntilTick)
        {
            _binkExclusiveWasActive = true;
            return true;
        }

        if (_binkSessionActive && !_binkWallClockSessions)
        {
            _binkSessionActive = false;
            BinkHostPlaybackAssist.EndMovieSession(_binkSessionPath);
            _binkSessionPath = null;
        }

        _binkExclusiveFrame = null;
        _naturalBinkDescriptorlessDirectFallbackActive = false;
        if (_binkExclusiveWasActive)
        {
            _binkExclusiveWasActive = false;
            Console.Error.WriteLine(
                "[LOADER][INFO] bink2.exclusive_present_end; guest presentation restored.");
        }

        return false;
    }
    // [V61.13.9][BINK_WALLCLOCK_COMPLETE]
    private static void TryCompleteExpiredBinkWallClockSession()
    {
        if (!_binkWallClockSessions)
        {
            return;
        }

        string? completedPath = null;

        lock (_gate)
        {
            if (!_binkSessionActive ||
                _binkSessionCompleted ||
                _binkSessionEndTick <= 0 ||
                Environment.TickCount64 < _binkSessionEndTick)
            {
                return;
            }

            completedPath = _binkSessionPath;
            _binkSessionCompleted = true;
            _binkSessionActive = false;
            _binkExclusiveFrame = null;
            _naturalBinkDescriptorlessDirectFallbackActive = false;
            _binkExclusiveWasActive = false;
        }

        if (!string.IsNullOrWhiteSpace(completedPath))
        {
            BinkHostPlaybackAssist.CompleteMovieSession(
                completedPath,
                "wall-clock");

            if (_binkWallClockCloseBridge)
            {
                HostMovieBridge.NotifyGuestMovieClosed(completedPath);
                BinkHostPlaybackAssist.LogExternal(
                    "BRIDGE_CLOSE",
                    "file='" + Path.GetFileName(completedPath) +
                    "' reason=wall-clock");
            }
        }
    }
