    private sealed class GuestQueueScope : IDisposable
    {
        private readonly VulkanGuestQueueIdentity? _previous;
        private bool _disposed;

        public GuestQueueScope(VulkanGuestQueueIdentity queue)
        {
            _previous = _submittingGuestQueue;
            _submittingGuestQueue = queue;
        }

        public void Dispose()
        {
            if (_disposed)
            {
                return;
            }

            _disposed = true;
            _submittingGuestQueue = _previous;
        }
    }

    public static IDisposable EnterGuestQueue(
        string queueName,
        ulong submissionId) =>
        new GuestQueueScope(new VulkanGuestQueueIdentity(
            string.IsNullOrWhiteSpace(queueName) ? "guest.unknown" : queueName,
            submissionId));

    private static long CurrentSubmittingQueueTailLocked()
    {
        var queue = _submittingGuestQueue;
        return queue is { } identity &&
            _lastEnqueuedGuestWorkByQueue.TryGetValue(identity.Name, out var tail)
                ? tail
                : 0;
    }

    private static bool ShouldTraceGuestImageSubmissionsForDiagnostics()
    {
        return string.Equals(
            Environment.GetEnvironmentVariable("SHARPEMU_TRACE_GUEST_IMAGES"),
            "1",
            StringComparison.Ordinal);
    }

    private static bool ShouldSamplePresentedGuestImageForDiagnostics(long frame)
    {
        var mode = Environment.GetEnvironmentVariable("SHARPEMU_TRACE_GUEST_IMAGES");
        if (string.Equals(mode, "present", StringComparison.OrdinalIgnoreCase))
        {
            // A 4K Vulkan readback is deliberately synchronous and can take
            // several seconds on Linux.  The lightweight "present" mode only
            // needs one proof that the final image is non-black.
            return frame == 1;
        }

        return string.Equals(mode, "1", StringComparison.Ordinal) &&
               (frame is 1 or 30 or 120 || frame % 600 == 0);
    }

    public static void EnsureStarted(uint width, uint height)
    {
        if (width == 0 || height == 0)
        {
            return;
        }

        lock (_gate)
        {
            if (_closed || _thread is not null)
            {
                return;
            }
        }

        var hasSplash = PngSplashLoader.TryLoad(
            out var splashPixels,
            out var splashWidth,
            out var splashHeight);
        lock (_gate)
        {
            if (_closed || _thread is not null)
            {
                return;
            }

            _windowWidth = width;
            _windowHeight = height;
            _latestPresentation ??= _splashHidden
                ? new Presentation(
                    CreateBlackFrame(width, height),
                    width,
                    height,
                    1,
                    GuestDrawKind.None,
                    TranslatedDraw: null,
                    RequiredGuestWorkSequence: 0,
                    IsSplash: false)
                : hasSplash
                ? new Presentation(
                    splashPixels,
                    splashWidth,
                    splashHeight,
                    1,
                    GuestDrawKind.None,
                    TranslatedDraw: null,
                    RequiredGuestWorkSequence: 0,
                    IsSplash: true)
                : new Presentation(
                    null,
                    width,
                    height,
                    0,
                    GuestDrawKind.None,
                    TranslatedDraw: null,
                    RequiredGuestWorkSequence: 0,
                    IsSplash: false);
            StartPresenterLocked();
        }
    }

    public static bool TryConfigureVideo(HostVideoOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);
        lock (_gate)
        {
            if (_thread is not null)
            {
                return false;
            }

            _videoOptions = options.Normalize();
            return true;
        }
    }

    private static void ResetHostSessionStateLocked()
    {
        _latestPresentation = null;
        _splashHidden = false;
        _pendingGuestWorkByQueue.Clear();
        _pendingGuestQueueSchedule.Clear();
        _pendingGuestQueueCursor = 0;
        _pendingGuestWorkCount = 0;
        _pendingPayloadGuestWorkCount = 0;
        _pendingSyncGuestWorkCount = 0;
        _pendingGuestWorkBytes = 0;
        _inFlightGuestWorkBytesV74081 = 0;
        _pendingGuestImagePresentations.Clear();
        _guestImageWorkSequences.Clear();
        _guestBufferWorkRanges.Clear();
        _resourceDependencyTraceCount = 0;
        _availableGuestImages.Clear();
        _registeredDisplayBufferFormatsV183.Clear();
        _loggedDisplayBufferResidencyMissesV183.Clear();
        _cpuBackedUploadGenerations.Clear();
        _untrackedGuestImageContentProbes.Clear();
        _lastOrderedGuestFlipVersions.Clear();
        _orderedGuestFlipWorkSequences.Clear();
        _orderedGuestFlipVersionSequence = 0;
        _pendingGuestImageUploads.Clear();
        _pendingGuestImageInitialData.Clear();
        _guestImageExtents.Clear();
        _enqueuedGuestWorkSequence = 0;
        _completedGuestWorkSequence = 0;
        _completedGuestWorkOutOfOrder.Clear();
        _lastEnqueuedGuestWorkByQueue.Clear();
        _executingGuestWorkSequence = 0;
        // SHARPEMU_V31_7_22_POST_STUDIOS_FRESH_FRAME_BARRIER
        ResetPostStudiosFreshGuestBarrierLockedV31722();
    }

    public static void HideSplashScreen()
    {
        lock (_gate)
        {
            _splashHidden = true;
            if (_closed || _latestPresentation is not { IsSplash: true } latest)
            {
                return;
            }

            var sequence = latest.Sequence + 1;
            _latestPresentation = new Presentation(
                CreateBlackFrame(latest.Width, latest.Height),
                latest.Width,
                latest.Height,
                sequence,
                GuestDrawKind.None,
                TranslatedDraw: null,
                RequiredGuestWorkSequence: 0,
                IsSplash: false);
            Console.Error.WriteLine("[LOADER][INFO] Vulkan VideoOut hid splash");
        }
    }

    // SHARPEMU_BINK_HANDOFF_BLACK_V1_1
    // A hidden/killed RAD child exposes the Vulkan swapchain underneath it.
    // Submit an actual opaque black frame before removing that child so the
    // last pre-movie guest frame (Sony splash) cannot flash back on screen.
    // This is deliberately not a Bink-exclusive lease: the very next guest
    // presentation may replace it immediately.
    internal static void SubmitHostMovieHandoffBlackV11(
        uint width,
        uint height,
        string movieName)
    {
        width = Math.Clamp(width, 1u, 3840u);
        height = Math.Clamp(height, 1u, 2160u);

        lock (_gate)
        {
            if (_closed)
            {
                return;
            }

            var sequence = (_latestPresentation?.Sequence ?? 0) + 1;
            _latestPresentation = new Presentation(
                CreateBlackFrame(width, height),
                width,
                height,
                sequence,
                GuestDrawKind.None,
                TranslatedDraw: null,
                RequiredGuestWorkSequence: 0,
                IsSplash: false);

            _binkExclusiveFrame = null;
            _binkExclusiveUntilTick = 0;
            _binkExclusiveWasActive = false;
            _naturalBinkDescriptorlessDirectFallbackActive = false;

            // SHARPEMU_V31_7_22_POST_STUDIOS_FRESH_FRAME_BARRIER
            ArmPostStudiosFreshGuestBarrierLockedV31722(movieName);
        }

        Console.Error.WriteLine(
            "[BINK-HANDOFF][V1.1] black_submitted " +
            $"file='{movieName}' size={width}x{height} " +
            "lease=none next_guest_frame_may_replace=True");
    }
    private static bool IsV114PostStudiosCoverActiveLocked()
    {
        if (!_v114PostStudiosCoverActive ||
            _v114PostStudiosCoverFrame is null)
        {
            return false;
        }

        if (Environment.TickCount64 <= _v114PostStudiosCoverUntilTick)
        {
            return true;
        }

        _v114PostStudiosCoverActive = false;
        _v114PostStudiosCoverFrame = null;
        _v114PostStudiosCoverUntilTick = 0;

        Console.Error.WriteLine(
            "[BINK-TRANSITION-COVER][V1.1.4] expired " +
            "reason=timeout guest_presentation_restored=True");

        return false;
    }

    // SHARPEMU_DEMONS_POST_STUDIOS_GUEST_AUDIO_MUTE_STATE_V1_1_5
    internal static bool IsDemonSoulsPostStudiosBlackCoverActiveV115()
    {
        lock (_gate)
        {
            return IsV114PostStudiosCoverActiveLocked();
        }
    }
    internal static void BeginDemonSoulsPostStudiosBlackCoverV114(
        uint width,
        uint height,
        string sourceMovie)
    {
        width = Math.Clamp(width, 1u, 3840u);
        height = Math.Clamp(height, 1u, 2160u);

        long untilTick;
        lock (_gate)
        {
            if (_closed)
            {
                return;
            }

            var sequence = (_latestPresentation?.Sequence ?? 0) + 1;
            var cover = new Presentation(
                CreateBlackFrame(width, height),
                width,
                height,
                sequence,
                GuestDrawKind.None,
                TranslatedDraw: null,
                RequiredGuestWorkSequence: 0,
                IsSplash: false);

            _latestPresentation = cover;
            _v114PostStudiosCoverFrame = cover;
            _v114PostStudiosCoverActive = true;
            _v114PostStudiosCoverUntilTick =
                Environment.TickCount64 +
                _v114PostStudiosCoverTimeoutMs;
            untilTick = _v114PostStudiosCoverUntilTick;
        }

        Console.Error.WriteLine(
            "[BINK-TRANSITION-COVER][V1.1.4] begin " +
            $"source='{sourceMovie}' size={width}x{height} " +
            $"timeout_ms={_v114PostStudiosCoverTimeoutMs} " +
            $"until_tick={untilTick} " +
            "guest_execution_continues=True guest_flips_hidden=True");
    }

    internal static void EndDemonSoulsPostStudiosBlackCoverV114(
        string reason)
    {
        var wasActive = false;

        lock (_gate)
        {
            wasActive =
                _v114PostStudiosCoverActive &&
                _v114PostStudiosCoverFrame is not null;

            _v114PostStudiosCoverActive = false;
            _v114PostStudiosCoverFrame = null;
            _v114PostStudiosCoverUntilTick = 0;
        }

        if (wasActive)
        {
            Console.Error.WriteLine(
                "[BINK-TRANSITION-COVER][V1.1.4] end " +
                $"reason='{reason}' " +
                "attract_visible=True guest_flips_unblocked=True");
        }
    }
    public static void Submit(byte[] bgraFrame, uint width, uint height)
    {
        if (bgraFrame.Length != checked((int)(width * height * 4)))
        {
            return;
        }
        // [V61.13.11][ANTI_REWIND_RGB]
        if (_binkDirectPresentOnly &&
            !BinkHostPlaybackAssist.TryNormalizeDirectPresentationFrame(
                bgraFrame,
                width,
                height))
        {
            // Keep the previous valid frame on screen when the decoder emits a
            // frame already seen earlier in the same BK2 source phase.
            return;
        }

        lock (_gate)
        {
            if (_closed)
            {
                return;
            }

            var sequence = (_latestPresentation?.Sequence ?? 0) + 1;
            var hostFrame = new Presentation(
                bgraFrame,
                width,
                height,
                sequence,
                GuestDrawKind.None,
                TranslatedDraw: null,
                RequiredGuestWorkSequence: 0,
                IsSplash: false);
            _latestPresentation = hostFrame;

            // [V61.13.6][BINK_EXCLUSIVE_FRAME]
            if (_binkExclusivePresentation ||
                _naturalBinkDescriptorlessDirectFallbackActive)
            {
                var enteringExclusive = _binkExclusiveFrame is null;
                _binkExclusiveFrame = hostFrame;
                _binkExclusiveUntilTick =
                    Environment.TickCount64 +
                    (_binkDirectPresentOnly ? 2000 : _binkExclusiveHoldMs);
                // [V61.13.8.2][BINK_SESSION_REFRESH]
                _binkSessionLastFrameTick = Environment.TickCount64;
                if (!_binkWallClockSessions || !_binkSessionCompleted)
                {
                    _binkSessionActive = true;
                }
                // [V61.13.7][BINK_SESSION_REFRESH]
                _binkSessionLastFrameTick = Environment.TickCount64;
                if (!_binkWallClockSessions || !_binkSessionCompleted)
                {
                    _binkSessionActive = true;
                }

                if (enteringExclusive)
                {
                    Console.Error.WriteLine("[LOADER][INFO] bink2.exclusive_visual_acquired");
                }
            }
            if (_thread is not null)
            {
                return;
            }

            _windowWidth = width;
            _windowHeight = height;
            StartPresenterLocked();
        }
    }

    public static void SubmitGuestDraw(GuestDrawKind drawKind, uint width, uint height)
    {
        if (drawKind == GuestDrawKind.None || width == 0 || height == 0)
        {
            return;
        }

        lock (_gate)
        {
            if (_closed ||
                _latestPresentation is { Pixels: null } latest &&
                latest.DrawKind == drawKind &&
                latest.Width == width &&
                latest.Height == height)
            {
                return;
            }

            var sequence = (_latestPresentation?.Sequence ?? 0) + 1;
            _latestPresentation = new Presentation(
                null,
                width,
                height,
                sequence,
                drawKind,
                TranslatedDraw: null,
                RequiredGuestWorkSequence: CurrentSubmittingQueueTailLocked(),
                IsSplash: false);
            if (_thread is not null)
            {
                return;
            }

            _windowWidth = width;
            _windowHeight = height;
            StartPresenterLocked();
        }
    }

    public static void SubmitTranslatedDraw(
        byte[] pixelSpirv,
        IReadOnlyList<GuestDrawTexture> textures,
        IReadOnlyList<GuestMemoryBuffer> globalMemoryBuffers,
        uint width,
        uint height,
        uint attributeCount,
        byte[]? vertexSpirv = null,
