                ? 0
                : EnqueueGuestWorkLocked(
                    new VulkanOrderedGuestAction(
                        action,
                        debugName,
                        RequireGlobalVisibility: false,
                        RequiresGpuToCpuVisibility: requiresGpuToCpuVisibility,
                        WaitProducerMemory: waitProducerMemory,
