    }

    /// <summary>
    /// Sequence currently being executed by the single guest-work consumer.
    /// Intended only for address-filtered lifetime diagnostics emitted from a
    /// guest-work callback before <see cref="CompleteGuestWork"/> advances it.
    /// </summary>
    /// <summary>
    /// Enqueues a CPU-side PM4 side effect after prior work in the current
    /// logical queue has completed, without copying dirty GPU buffers back
    /// into guest CPU memory.
    /// </summary>
    public static long SubmitOrderedGuestActionAfterQueueCompletion(
        Action action,
        string debugName) =>
        SubmitOrderedGuestActionAfterQueueCompletion(
            action,
            debugName,
            waitProducerMemory: null,
            waitProducerAddress: 0,
            waitProducerLength: 0);

    // SHARPEMU_V74_0_56_12_QUEUE_COMPLETION_PRODUCER_METADATA
    // Keep V73.5 queue-completion ordering unchanged while exposing the exact
    // WRITE_DATA producer range to the FIFO watched-producer scheduler.
    public static long SubmitOrderedGuestActionAfterQueueCompletion(
        Action action,
        string debugName,
        object? waitProducerMemory,
        ulong waitProducerAddress,
        ulong waitProducerLength)
    {
        ArgumentNullException.ThrowIfNull(action);
