            identity.HasExtendedDescriptor);

    private static void RemoveTextureContentIndexV740783(
        in TextureContentIdentity identity)
    {
        var key = GetTextureContentKeyV740783(identity);
        if (_v740783TextureByContent.TryGetValue(key, out var mapped) &&
            mapped.Equals(identity))
        {
            _v740783TextureByContent.TryRemove(key, out _);
        }
    }

    private static void TracePreSnapshotAliasV740783(
        in TextureContentIdentity requested)
    {
        var hit = Interlocked.Increment(ref _v740783PreSnapshotAliasHitCount);
        if (hit <= 256 || (hit & (hit - 1)) == 0)
        {
            Console.Error.WriteLine(
                $"[V74.0.78.3][PRE_SNAPSHOT_SAMPLER_ALIAS] " +
                $"count={hit} addr=0x{requested.Address:X16} " +
                $"size={requested.Width}x{requested.Height} " +
                $"fmt={requested.Format}/{requested.NumberType} " +
                $"tile={requested.TileMode} source_copy=skipped");
        }
    }

    internal static bool IsTextureContentCached(in TextureContentIdentity identity)
    {
        // Exact sampler-inclusive identity: keep the accumulated implementation
        // as the single authority for sparse probes and stale invalidation.
        if (_cachedTextureIdentities.ContainsKey(identity))
        {
            return IsTextureContentCachedBaselineV740783(identity);
        }

        var key = GetTextureContentKeyV740783(identity);
        if (_v740783TextureByContent.TryGetValue(key, out var canonical))
        {
            if (!canonical.Sampler.Equals(identity.Sampler) &&
                IsTextureContentCachedBaselineV740783(canonical))
            {
                TracePreSnapshotAliasV740783(identity);
                return true;
            }

            if (!_cachedTextureIdentities.ContainsKey(canonical))
            {
                _v740783TextureByContent.TryRemove(key, out _);
            }
        }

        // Preserve any accumulated fallback/legacy alias behavior.
        return IsTextureContentCachedBaselineV740783(identity);
    }

    private static bool IsTextureContentCachedBaselineV740783(in TextureContentIdentity identity)
    {
        if (IsExactTextureContentCachedV74056331(identity))
        {
            return true;
        }

        if (!_preSnapshotSamplerAliasV74056331 ||
            identity.Address == 0 ||
            _cachedTextureIdentities.IsEmpty)
        {
            return false;
        }

        foreach (var candidate in _cachedTextureIdentities.Keys)
        {
            if (candidate.Sampler.Equals(identity.Sampler) ||
                !TextureIdentityMatchesExceptSamplerV74056331(
                    candidate,
                    identity) ||
                !IsExactTextureContentCachedV74056331(candidate))
            {
                continue;
            }

            var hit = Interlocked.Increment(
                ref _v74056331PreSnapshotSamplerAliasHitCount);
            if (hit <= 128 || (hit & (hit - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V74.0.56.33.1][PRE_SNAPSHOT_SAMPLER_ALIAS] " +
                    $"count={hit} addr=0x{identity.Address:X16} " +
                    $"size={identity.Width}x{identity.Height} " +
                    $"fmt={identity.Format}/{identity.NumberType} " +
                    $"tile={identity.TileMode} source_copy=skipped");
            }
            return true;
        }

        return false;
    }

    private static bool IsExactTextureContentCachedV74056331(in TextureContentIdentity identity)
    {
        if (!_cachedTextureIdentities.ContainsKey(identity))
        {
            return false;
        }

        if (!ShouldProbeUntrackedTextureCache() || identity.Address == 0)
        {
            return true;
        }

        if (!_untrackedTextureCacheProbes.TryGetValue(identity, out var previous))
        {
            _cachedTextureIdentities.TryRemove(identity, out _);
            _staleTextureIdentities.TryAdd(identity, 0);
            TraceUntrackedTextureCacheStale(
                identity,
                0,
                0,
                "missing-baseline");
            return false;
        }

        var memory = _guestMemory;
        if (memory is null || previous.ByteCount == 0)
        {
            return true;
        }

        var current = ComputeSparseGuestContentProbe(
            memory,
            identity.Address,
            previous.ByteCount);
        if (current == previous.Hash)
        {
            return true;
        }

        _cachedTextureIdentities.TryRemove(identity, out _);
        _untrackedTextureCacheProbes.TryRemove(identity, out _);
        _staleTextureIdentities.TryAdd(identity, 0);
        TraceUntrackedTextureCacheStale(
            identity,
            previous.Hash,
            current,
            "guest-bytes-changed");
        return false;
    }

    // SHARPEMU_V74_0_74_SAMPLER_PRECOPY_SKIP
    // SHARPEMU_V74_0_75_TEXTURE_IDENTITY_INDEX
    // V74 proved sampler-only reuse is useful, but its implementation walked
    // every cached identity on every exact-key miss. Keep the same coherence
    // semantics while resolving the sampler-agnostic candidate through an
    // O(1) normalized identity index.
    private static TextureContentIdentity NormalizeSamplerIdentityV74075(
        in TextureContentIdentity identity) =>
        identity with { Sampler = default };

    internal static bool IsTextureContentCachedIgnoringSamplerV74074(
        in TextureContentIdentity requested)
    {
        if (requested.Address == 0)
        {
            return false;
        }

        var normalized = NormalizeSamplerIdentityV74075(requested);
        if (!_samplerAgnosticTextureIndexV74075.TryGetValue(
                normalized,
                out var candidate) ||
            candidate.Sampler.Equals(requested.Sampler))
        {
            return false;
        }

        // Preserve the exact PPSA01341 stale-content validation. If this
        // candidate became stale, remove only the normalized index pointer;
        // the normal path will materialize fresh guest bytes and re-index on
        // MarkTextureContentCached().
        if (IsTextureContentCached(candidate))
        {
            Interlocked.Increment(ref _v74075SamplerIndexHitCount);
            return true;
        }

        _samplerAgnosticTextureIndexV74075.TryRemove(normalized, out _);
        Interlocked.Increment(ref _v74075SamplerIndexStaleCount);
        return false;
    }

    private static void MarkTextureContentCached(
        in TextureContentIdentity identity,
        GuestDrawTexture texture)
    {
        _cachedTextureIdentities.TryAdd(identity, 0);
        _v740783TextureByContent[GetTextureContentKeyV740783(identity)] = identity;
        _samplerAgnosticTextureIndexV74075[
            NormalizeSamplerIdentityV74075(identity)] = identity;
        _staleTextureIdentities.TryRemove(identity, out _);

        if (!ShouldProbeUntrackedTextureCache() ||
            identity.Address == 0 ||
            !TryBuildUntrackedTextureProbe(
                texture,
                GetTextureContentProbeByteCount(identity),
                out var probe))
        {
            _untrackedTextureCacheProbes.TryRemove(identity, out _);
            return;
        }

        _untrackedTextureCacheProbes[identity] = probe;
    }

    private static void UnmarkTextureContentCached(in TextureContentIdentity identity)
    {
        _cachedTextureIdentities.TryRemove(identity, out _);
        RemoveTextureContentIndexV740783(identity);

        var normalizedV74075 = NormalizeSamplerIdentityV74075(identity);
        if (_samplerAgnosticTextureIndexV74075.TryGetValue(
                normalizedV74075,
                out var indexedV74075) &&
            indexedV74075.Equals(identity))
        {
            _samplerAgnosticTextureIndexV74075.TryRemove(
                normalizedV74075,
                out _);
        }

        _untrackedTextureCacheProbes.TryRemove(identity, out _);
        _staleTextureIdentities.TryRemove(identity, out _);
    }

    private static void ClearCachedTextureIdentities()
    {
        _cachedTextureIdentities.Clear();
        _v740783TextureByContent.Clear();
        _samplerAgnosticTextureIndexV74075.Clear();
        _untrackedTextureCacheProbes.Clear();
        _staleTextureIdentities.Clear();
    }

    private static ulong GetTextureContentProbeByteCount(
        in TextureContentIdentity identity)
    {
        var rowLength = identity.TileMode == 0
            ? Math.Max(identity.Pitch, identity.Width)
            : identity.Width;
        var depth = GetGuestTextureDepth(identity.Type, identity.Depth);
        var layers = identity.Arrayed
            ? Math.Max(identity.ArrayLayers, 1u)
            : 1u;

        try
        {
            var perLayerOrVolume = GetGuestImageByteCount(
                identity.Format,
                rowLength,
                identity.Height,
                depth);
            return checked(perLayerOrVolume * layers);
        }
        catch (OverflowException)
        {
            return 0;
        }
    }

    private static bool TryBuildUntrackedTextureProbe(
        GuestDrawTexture texture,
        ulong byteCount,
        out UntrackedTextureCacheProbe probe)
    {
        probe = default;
        var v740231LargeArraySparseProbe =
            texture.ArrayedView &&
            texture.ArrayLayers > 1 &&
            byteCount > MaxTrackedGuestImageBytes &&
            byteCount <= V740231MaxLargeArraySparseProbeBytes;
        if (texture.Address == 0 ||
            byteCount == 0 ||
            (byteCount > MaxTrackedGuestImageBytes &&
             !v740231LargeArraySparseProbe))
        {
            return false;
        }

        if (texture.TileMode == 0 &&
            texture.RgbaPixels.LongLength >= (long)byteCount &&
            byteCount <= int.MaxValue)
        {
            probe = new UntrackedTextureCacheProbe(
                ComputeSparseSubmittedContentProbe(
                    texture.RgbaPixels.AsSpan(0, (int)byteCount)),
                byteCount);
            return true;
        }

        if (!texture.ArrayedView &&
            texture.TiledSource is { Length: > 0 } tiled &&
            tiled.LongLength >= (long)byteCount &&
            byteCount <= int.MaxValue)
        {
            probe = new UntrackedTextureCacheProbe(
                ComputeSparseSubmittedContentProbe(
                    tiled.AsSpan(0, (int)byteCount)),
                byteCount);
            return true;
        }

        var memory = _guestMemory;
        if (memory is null)
        {
            return false;
        }

        probe = new UntrackedTextureCacheProbe(
            ComputeSparseGuestContentProbe(
                memory,
                texture.Address,
                byteCount),
            byteCount);
        if (v740231LargeArraySparseProbe)
        {
            var baselineCount = Interlocked.Increment(
                ref _v740231LargeArrayBaselineTraceCount);
            if (baselineCount <= 32 ||
                (baselineCount & (baselineCount - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V74.0.23.1][ARRAY_BASELINE] count={baselineCount} " +
                    $"addr=0x{texture.Address:X16} size={texture.Width}x{texture.Height} " +
                    $"layers={texture.ArrayLayers} bytes={byteCount} sparse_read_bytes=512");
            }
        }
        return true;
    }

    private static ulong ComputeSparseSubmittedContentProbe(
        ReadOnlySpan<byte> content)
    {
        ulong hash = 14695981039346656037UL;
        if (content.IsEmpty)
        {
            return hash;
        }

        const int SampleBytes = 64;
        Span<int> offsets = stackalloc int[8];
        var offsetCount = content.Length <= SampleBytes
            ? 1
            : offsets.Length;
        var maximumOffset = Math.Max(content.Length - SampleBytes, 0);

        if (offsetCount == 1)
        {
            offsets[0] = 0;
        }
        else
        {
            for (var index = 0; index < offsetCount; index++)
            {
                offsets[index] =
                    maximumOffset * index / (offsetCount - 1);
            }
        }

        for (var index = 0; index < offsetCount; index++)
        {
            var offset = offsets[index];
            var length = Math.Min(SampleBytes, content.Length - offset);
            var sample = content.Slice(offset, length);
            for (var byteIndex = 0; byteIndex < sample.Length; byteIndex++)
            {
                hash ^= sample[byteIndex];
                hash *= 1099511628211UL;
            }

            hash ^= (ulong)length + (ulong)offset;
        }

        return hash ^ (ulong)content.Length;
    }

    private static void TraceUntrackedTextureCacheStale(
        in TextureContentIdentity identity,
        ulong previous,
        ulong current,
        string reason)
    {
        var count = Interlocked.Increment(
            ref _v73019TextureCacheStaleTraceCount);
        if (count > 64 && (count & (count - 1)) != 0)
        {
            return;
        }

        Console.Error.WriteLine(
            $"[V73.0.19.1][TEXTURE_CACHE_STALE] count={count} " +
            $"reason={reason} addr=0x{identity.Address:X16} " +
            $"size={identity.Width}x{identity.Height} " +
            $"fmt={identity.Format}/{identity.NumberType} " +
            $"tile={identity.TileMode} array={(identity.Arrayed ? 1 : 0)} " +
            $"old=0x{previous:X16} new=0x{current:X16}");
    }

    internal static bool IsGuestImageAvailable(
        ulong address,
        uint format,
        uint numberType)
    {
        var guestFormat = GetGuestTextureFormat(format, numberType);
        if (address == 0 || guestFormat == 0)
        {
            return false;
        }

        lock (_gate)
        {
            if (!_availableGuestImages.TryGetValue(address, out var availableFormat))
            {
                return false;
            }

            if (availableFormat == guestFormat)
            {
                return true;
            }

            return TryDecodeRenderTargetFormat(
                    (availableFormat >> 8) & 0x1FFu,
                    availableFormat & 0xFFu,
                    out var resident) &&
                TryDecodeRenderTargetFormat(format, numberType, out var requested) &&
                Presenter.IsCompatibleViewFormat(resident.Format, requested.Format);
        }
    }

    // Display buffers registered through sceVideoOutRegisterBuffers remain
    // valid flip targets even before AGC has rendered into them.
    internal static void RegisterKnownDisplayBuffer(ulong address, uint guestFormat)
    {
        if (address == 0 || guestFormat == 0)
        {
            return;
        }

        lock (_gate)
        {
            // V1.8.3: registered scanout target != resident Vulkan image.
            _registeredDisplayBufferFormatsV183[address] = guestFormat;
        }
    }
    // SHARPEMU_REGISTERED_DISPLAY_BUFFER_QUERY_V1_8_31
    internal static bool IsRegisteredDisplayBufferV1831(ulong address)
    {
        if (address == 0)
        {
            return false;
        }

        lock (_gate)
        {
            return _registeredDisplayBufferFormatsV183.ContainsKey(address);
        }
    }

    internal static bool IsGpuGuestImageAvailable(
        ulong address,
        uint format,
        uint numberType) =>
        IsGuestImageAvailable(address, format, numberType);

    /// <summary>
    /// Returns whether a storage image already exists on the presenter or an
    /// earlier queued dispatch owns its one-time guest-memory initialization.
    /// This is intentionally separate from <see cref="IsGuestImageAvailable"/>:
    /// a pending image may skip a duplicate upload but is not yet safe for a
    /// flip/presentation lookup.
    /// </summary>
    internal static bool IsGuestImageUploadKnown(
        ulong address,
        uint format,
        uint numberType)
    {
        var guestFormat = GetGuestTextureFormat(format, numberType);
        if (address == 0 || guestFormat == 0)
        {
            return false;
        }

        ulong probeByteCount = 0;
        lock (_gate)
        {
            var known =
                _availableGuestImages.TryGetValue(address, out var availableFormat) &&
                    availableFormat == guestFormat ||
                _pendingGuestImageUploads.ContainsKey((address, guestFormat));
            if (!known)
            {
                return false;
            }

            // CPU-backed images (video frames, streamed atlases) go stale when
            // the guest CPU rewrites the memory after the recorded upload; a
            // changed write-tracker generation forces a fresh texel copy so
            // the refresh path can re-upload. GPU-rendered images have no
            // generation entry and keep the plain availability answer.
            if (_cpuBackedUploadGenerations.TryGetValue(address, out var uploadedGeneration) &&
                SharpEmu.HLE.GuestImageWriteTracker.TryGetWriteGeneration(
                    address,
                    out var currentGeneration) &&
                currentGeneration != uploadedGeneration)
            {
                return false;
            }

            if (SharpEmu.HLE.GuestImageWriteTracker.Enabled)
            {
                return true;
            }

            if (_guestImageExtents.TryGetValue(address, out var extent))
            {
                probeByteCount = extent.ByteCount;
            }
        }

        // Tracker off: availability never goes generation-stale. A sparse
        // guest-memory probe lets static upload-known textures keep skipping
        // (Dead Cells menus) while CPU-rewritten planes (GTA Bink) fall through
        // to a full texel copy when the probe changes.
        return IsUntrackedGuestImageContentUnchanged(address, probeByteCount);
    }

    private static bool IsUntrackedGuestImageContentUnchanged(ulong address, ulong byteCount)
    {
        var memory = _guestMemory;
        if (memory is null || byteCount == 0)
        {
            // No probe possible Ã¢â‚¬â€ preserve the historical skip so UI stays
            // cheap; video planes normally have extents registered.
            return true;
        }

        var probe = ComputeSparseGuestContentProbe(memory, address, byteCount);
        lock (_gate)
        {
            if (!_untrackedGuestImageContentProbes.TryGetValue(address, out var previous))
            {
                _untrackedGuestImageContentProbes[address] = probe;
                return true;
            }

            if (previous == probe)
            {
                return true;
            }

            _untrackedGuestImageContentProbes[address] = probe;
            return false;
        }
    }

    private static bool TryReadGuestTextureBacking(
        SharpEmu.HLE.ICpuMemory memory,
        ulong address,
        Span<byte> destination) =>
        memory.TryRead(address, destination) ||
        SharpEmu.Libs.Kernel.KernelMemoryCompatExports.TryReadTrackedLibcHeap(
            address,
            destination) ||
        SharpEmu.Libs.Kernel.KernelMemoryCompatExports.TryReadTrackedLibcHeapGpuAlias(
            address,
            destination);

    private static ulong ComputeSparseGuestContentProbe(
        SharpEmu.HLE.ICpuMemory memory,
        ulong address,
        ulong byteCount)
    {
        Span<byte> sample = stackalloc byte[64];
        ulong hash = 14695981039346656037UL;

        // V61.20.0_TEXTURE_SPARSE_PROBE
        // With GuestImageWriteTracker disabled, three samples (start/middle/end)
        // can miss CPU updates in streamed atlases and UI planes. Eight evenly
        // distributed 64-byte probes still cost only 512 bytes of guest reads
        // while substantially reducing false "unchanged" cache hits.
        Span<ulong> offsets = stackalloc ulong[8];
        var offsetCount = byteCount <= 64
            ? 1
            : offsets.Length;
        var maximumOffset = byteCount > 64
            ? byteCount - 64
            : 0UL;

        if (offsetCount == 1)
        {
            offsets[0] = 0;
        }
        else
        {
            for (var o = 0; o < offsetCount; o++)
            {
                offsets[o] =
                    maximumOffset * (ulong)o / (ulong)(offsetCount - 1);
            }
        }

        for (var o = 0; o < offsetCount; o++)
        {
            var offset = offsets[o];
            if (offset >= byteCount)
            {
                continue;
            }

            var length = (int)Math.Min(64UL, byteCount - offset);
            if (!TryReadGuestTextureBacking(
                    memory,
                    address + offset,
                    sample[..length]))
            {
                hash ^= 0x9E3779B97F4A7C15UL + offset;
                continue;
            }

            for (var i = 0; i < length; i++)
            {
                hash ^= sample[i];
                hash *= 1099511628211UL;
            }

            hash ^= (ulong)length + offset;
        }

        return hash ^ byteCount;
    }

    public static bool TrySubmitGuestImageBlit(
        ulong sourceAddress,
        uint sourceWidth,
        uint sourceHeight,
        uint sourceFormat,
        uint sourceNumberType,
        ulong destinationAddress,
        uint destinationWidth,
        uint destinationHeight,
        uint destinationFormat,
        uint destinationNumberType)
    {
        if (sourceAddress == 0 ||
            destinationAddress == 0 ||
            sourceWidth == 0 ||
            sourceHeight == 0 ||
            destinationWidth == 0 ||
            destinationHeight == 0 ||
            !TryGetCopyFragmentShader(out var fragmentSpirv))
        {
            return false;
        }

        lock (_gate)
        {
            if (_closed ||
                !_availableGuestImages.ContainsKey(sourceAddress) ||
                GetGuestTextureFormat(destinationFormat, 0) == 0)
            {
                return false;
            }
        }

        SubmitOffscreenTranslatedDraw(
            fragmentSpirv,
            [
                new GuestDrawTexture(
                    sourceAddress,
                    sourceWidth,
                    sourceHeight,
                    sourceFormat,
                    sourceNumberType,
                    [],
                    IsFallback: false,
                    IsStorage: false),
            ],
            [],
            attributeCount: 1,
            new GuestRenderTarget(
                destinationAddress,
                destinationWidth,
                destinationHeight,
                destinationFormat,
                destinationNumberType));
        return true;
    }

    private static bool TryGetCopyFragmentShader(out byte[] spirv)
    {
        lock (_gate)
        {
            if (_copyFragmentSpirv is not null)
            {
                spirv = _copyFragmentSpirv;
                return true;
            }
        }

        spirv = SpirvFixedShaders.CreateCopyFragment();

        lock (_gate)
        {
            _copyFragmentSpirv ??= spirv;
            spirv = _copyFragmentSpirv;
        }

        return true;
    }

    private static uint GetGuestTextureFormat(uint format, uint numberType) =>
        IsKnownGuestTextureFormat(format)
            ? 0x8000_0000u | ((format & 0x1FFu) << 8) | (numberType & 0xFFu)
            : 0;

    internal static bool TryDecodeRenderTargetFormat(
        uint dataFormat,
        uint numberType,
        out VulkanRenderTargetFormat result) =>
        TryDecodeRenderTargetFormat(
            dataFormat,
            numberType,
            componentSwap: 0,
            out result);

    internal static bool TryDecodeRenderTargetFormat(
        uint dataFormat,
        uint numberType,
        uint componentSwap,
        out VulkanRenderTargetFormat result)
    {
        var format = (dataFormat, numberType) switch
        {
            // Early G-buffer / scene targets (R16 + RG32). GTA V Enhanced hits
            // these as color targets; texture decode already knew them.
            (2, 0) => Format.R16Unorm,
            (2, 1) => Format.R16SNorm,
            (2, 2) => Format.R16Uscaled,
            (2, 3) => Format.R16Sscaled,
            (2, 4) => Format.R16Uint,
            (2, 5) => Format.R16Sint,
            (2, 7) => Format.R16Sfloat,
            (4, 4) => Format.R32Uint,
            (4, 5) => Format.R32Sint,
            (4, 7) => Format.R32Sfloat,
            (5, 4) => Format.R16G16Uint,
            (5, 5) => Format.R16G16Sint,
            (5, 7) => Format.R16G16Sfloat,
            (6, 7) or (7, 7) => Format.B10G11R11UfloatPack32,
            // CB_COLOR_INFO.COMP_SWAP is independent from FORMAT. For
            // COLOR_2_10_10_10, STD exposes the low 10-bit component as R
            // (A2B10G10R10 in Vulkan); ALT reverses R/B.
            (9, _) when componentSwap == 0 => Format.A2B10G10R10UnormPack32,
            (9, _) when componentSwap == 1 => Format.A2R10G10B10UnormPack32,
            // Other swap modes need explicit shader/view swizzle handling.
            (9, _) => Format.Undefined,
            (10, 4) => Format.R8G8B8A8Uint,
            (10, 5) => Format.R8G8B8A8Sint,
            (10, 9) => Format.R8G8B8A8Srgb,
            (10, _) => Format.R8G8B8A8Unorm,
            (11, 4) => Format.R32G32Uint,
            (11, 5) => Format.R32G32Sint,
            (11, 7) => Format.R32G32Sfloat,
            (12, 4) => Format.R16G16B16A16Uint,
            (12, 5) => Format.R16G16B16A16Sint,
            (12, 7) => Format.R16G16B16A16Sfloat,
            (13, 7) or (14, 7) => Format.R32G32B32A32Sfloat,
            (20, 0) => Format.R32Uint,
            (29, 0) or (4, 0) => Format.R32Sfloat,
            (1, 0) or (36, 0) => Format.R8Unorm,
            (49, 0) => Format.R8Uint,
            (3, 0) => Format.R8G8Unorm,
            (5, 0) => Format.R16G16Unorm,
            (7, 0) => Format.B10G11R11UfloatPack32,
            (12, 0) => Format.R16G16B16A16Unorm,
            (13, 0) or (14, 0) => Format.R32G32B32A32Sfloat,
            (22, 0) or (71, 0) => Format.R16G16B16A16Sfloat,
            (56, 0) or (62, 0) or (64, 0) => Format.R8G8B8A8Unorm,
            (75, 0) => Format.R32G32Sfloat,
            _ => Format.Undefined,
        };

        if (format == Format.Undefined)
        {
            result = default;
            return false;
        }

        var outputKind = format switch
        {
            Format.R8Uint or Format.R16Uint or Format.R32Uint or Format.R16G16Uint or
                Format.R32G32Uint or Format.R8G8B8A8Uint or Format.R16G16B16A16Uint =>
                Gen5PixelOutputKind.Uint,
            Format.R16Sint or Format.R32Sint or Format.R16G16Sint or Format.R32G32Sint or
                Format.R8G8B8A8Sint or Format.R16G16B16A16Sint => Gen5PixelOutputKind.Sint,
            _ => Gen5PixelOutputKind.Float,
        };
        result = new VulkanRenderTargetFormat(format, outputKind);
        return true;
    }

    private static bool IsKnownGuestTextureFormat(uint format) =>
        format is >= 1 and <= 19 or 34 or >= 169 and <= 182;

    private static byte[] CreateBlackFrame(uint width, uint height)
    {
        if (width == 0 || height == 0 || width > 8192 || height > 8192)
        {
            width = 1;
            height = 1;
        }

        var pixels = GC.AllocateUninitializedArray<byte>(checked((int)(width * height * 4)));
        pixels.AsSpan().Clear();
        for (var offset = 3; offset < pixels.Length; offset += 4)
        {
            pixels[offset] = 0xFF;
        }

        return pixels;
    }

    private static void StartPresenterLocked()
    {
        if (HostMainThread.IsAvailable)
        {
            // AppKit windowing traps when touched off the process
            // main thread on macOS, so hand the whole window loop to the
            // main-thread pump the CLI parked for us. _thread only marks the
            // presenter as running; Run() clears it on exit either way.
            _thread = Thread.CurrentThread;
            HostMainThread.SetShutdownRequestHandler(RequestClose);
            HostMainThread.Post(Run);
            return;
        }

        _thread = new Thread(Run)
        {
            IsBackground = true,
            Name = "SharpEmu Vulkan VideoOut",
        };
        _thread.Start();
    }

    /// <summary>
    /// Asks a running presenter to close its window; used at emulator
    /// shutdown so a main-thread-hosted window loop returns to the pump.
    /// </summary>
    public static void RequestClose()
    {
        Volatile.Write(ref _presenterCloseRequested, true);
    }

    private static void Run()
    {
        uint width;
        uint height;
        lock (_gate)
        {
            width = _windowWidth == 0 ? _latestPresentation?.Width ?? 1280 : _windowWidth;
            height = _windowHeight == 0 ? _latestPresentation?.Height ?? 720 : _windowHeight;
        }

        try
        {
            using var presenter = new Presenter(width, height);
            presenter.Run();
        }
        catch (Exception exception)
        {
            Console.Error.WriteLine($"[LOADER][ERROR] Vulkan VideoOut presenter failed: {exception}");
        }
        finally
        {
            lock (_gate)
            {
                _closed = true;
                _thread = null;
                System.Threading.Monitor.PulseAll(_gate);
            }
        }
    }

    private static bool TryTakePresentation(long presentedSequence, out Presentation presentation)
    {
        lock (_gate)
        {
            // V1.1.4: while the post-Studios cover is active, do not consume
            // guest flips. They remain queued/bounded and guest GPU work keeps
            // executing, but the stale Sony transition card cannot resurface.
            if (IsV114PostStudiosCoverActiveLocked() &&
                _v114PostStudiosCoverFrame is { } transitionCover)
            {
                if (transitionCover.Sequence != presentedSequence)
                {
                    presentation = transitionCover;
                    return true;
                }

                presentation = default;
                return false;
            }
            // SHARPEMU_V31_7_22_POST_STUDIOS_FRESH_FRAME_BARRIER
            ApplyPostStudiosFreshGuestBarrierLockedV31722(presentedSequence);

            // [V61.13.6][BINK_EXCLUSIVE_TAKE]
            if (IsBinkExclusiveActiveLocked() &&
                _binkExclusiveFrame is { } movieFrame)
            {
                if (movieFrame.Sequence != presentedSequence)
                {
                    presentation = movieFrame;
                    return true;
                }

                // Keep the already-presented host frame visible. Do not consume
                // a guest flip between movie frames; the next decoded movie
                // frame will refresh _binkExclusiveFrame.
                presentation = default;
                return false;
            }
            // Guest flips are retained in submission order. The renderer is
            // deliberately allowed to lag a frame or two behind the guest
            // while it drains expensive work, so use the first completed flip
            // rather than repeatedly asking only for the newest one.
            while (_pendingGuestImagePresentations.Count > 0 &&
                   _pendingGuestImagePresentations.Peek().Sequence <= presentedSequence)
            {
                _pendingGuestImagePresentations.Dequeue();
            }

            if (_pendingGuestImagePresentations.Count > 0)
            {
                var pending = _pendingGuestImagePresentations.Peek();
                if (IsGuestWorkCompletedLocked(pending.RequiredGuestWorkSequence))
                {
                    presentation = _pendingGuestImagePresentations.Dequeue();
                    return true;
                }

                presentation = default;
                return false;
            }

            if (_latestPresentation is not { } latest ||
                latest.Sequence == presentedSequence ||
                !IsGuestWorkCompletedLocked(latest.RequiredGuestWorkSequence))
            {
                if (_latestPresentation is { } rej &&
                    rej.GuestImageAddress != 0 &&
					rej.Sequence != presentedSequence &&
                    _tracedGuestImagePresentRejections.Add(rej.Sequence))
                {
                    var reason = rej.Sequence == presentedSequence
                        ? "already-presented(seq==presented)"
                        : !IsGuestWorkCompletedLocked(rej.RequiredGuestWorkSequence)
                            ? $"work-not-done(req={rej.RequiredGuestWorkSequence}>" +
                              $"contiguous_done={_completedGuestWorkSequence})"
                            : "unknown";
                    Console.Error.WriteLine(
                        $"[LOADER][WARN] vk.guest_present_rejected addr=0x{rej.GuestImageAddress:X16} " +
                        $"seq={rej.Sequence} presentedSeq={presentedSequence} reason={reason}");
                }

                presentation = default;
                return false;
            }

            presentation = latest;
            return true;
        }
    }

    private static readonly HashSet<long> _tracedGuestImagePresentRejections = new();

	private static bool HasPendingGuestPresentation(long presentedSequence)
	{
		lock (_gate)
		{
            if (IsV114PostStudiosCoverActiveLocked() &&
                _v114PostStudiosCoverFrame is { } transitionCover)
            {
                return transitionCover.Sequence > presentedSequence;
            }
			return _pendingGuestImagePresentations.Count > 0 ||
				_latestPresentation is { } latest && latest.Sequence > presentedSequence;
		}
	}

    private static bool HasReadyPresentationV74034(long presentedSequence)
    {
        lock (_gate)
        {
            if (IsV114PostStudiosCoverActiveLocked() &&
                _v114PostStudiosCoverFrame is { } transitionCover)
            {
                return transitionCover.Sequence != presentedSequence;
            }
            if (IsBinkExclusiveActiveLocked() &&
                _binkExclusiveFrame is { } movieFrame)
            {
                return movieFrame.Sequence != presentedSequence;
            }

            foreach (var pending in _pendingGuestImagePresentations)
            {
                if (pending.Sequence <= presentedSequence)
                {
                    continue;
                }

                return IsGuestWorkCompletedLocked(
                    pending.RequiredGuestWorkSequence);
            }

            return _latestPresentation is { } latest &&
                latest.Sequence != presentedSequence &&
                IsGuestWorkCompletedLocked(latest.RequiredGuestWorkSequence);
        }
    }

    private static long EnqueueGuestWorkLocked(object work)
    {
        var payloadBytes = GetGuestWorkPayloadBytes(work);
        var isPayloadWork = IsPayloadBearingGuestWork(work);
        var backpressureLogged = false;

        // V73.0.15: V73.0.14 waited for GpuWaitRegistry.Count != 0, but the
        // measured backpressure occurs one packet-generation earlier. Detect
        // that precursor by queue composition: at least 8 sync actions and sync
        // work is the majority of pending work. This was 19/26 in PPSA01341.
        var hasOutstandingGpuWaits =
            SharpEmu.Libs.Agc.GpuWaitRegistry.Count != 0;
        var hasSyncPressure =
            _pendingSyncGuestWorkCount >= 8 &&
            _pendingSyncGuestWorkCount * 2 >= _pendingGuestWorkCount;
        var parserEscapeActive =
            isPayloadWork && (hasOutstandingGpuWaits || hasSyncPressure);
        // [V74.0.47][WAITER_PARSER_HEADROOM]
        // Do not inflate ordinary sync-pressure buffering. The larger budget is
        // available only after a real waiter exists, so a producer queue can
        // continue parsing far enough to enqueue its FIFO-ordered completion.
        var pendingByteBudget =
            hasOutstandingGpuWaits
                ? Math.Max(
                    Math.Max(
                        _maxPendingGuestWorkBytes,
                        _maxPendingGuestWorkEmergencyBytes),
                    _maxPendingGuestWorkWaiterBytes)
                : hasSyncPressure
                    ? Math.Max(
                        _maxPendingGuestWorkBytes,
                        _maxPendingGuestWorkEmergencyBytes)
                    : _maxPendingGuestWorkBytes;

        if (parserEscapeActive &&
            _pendingGuestWorkBytes < pendingByteBudget &&
            payloadBytes > _maxPendingGuestWorkBytes -
                Math.Min(_pendingGuestWorkBytes, _maxPendingGuestWorkBytes))
        {
            var escapeCount = Interlocked.Increment(ref _v73015ParserEscapeTraceCount);
            if (escapeCount <= 16 || (escapeCount & (escapeCount - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V73.0.15][PARSER_ESCAPE] count={escapeCount} " +
                    $"reason={(hasOutstandingGpuWaits ? "waiter" : "sync-pressure")} " +
                    $"queued={_pendingGuestWorkCount} " +
                    $"payload={_pendingPayloadGuestWorkCount} " +
                    $"sync={_pendingSyncGuestWorkCount} " +
                    $"retained_mb={_pendingGuestWorkBytes / (1024 * 1024)} " +
                    $"incoming_mb={payloadBytes / (1024 * 1024)} " +
                    $"soft_mb={_maxPendingGuestWorkBytes / (1024 * 1024)} " +
                    $"hard_mb={pendingByteBudget / (1024 * 1024)} " +
                    $"waiter_budget_mb={_maxPendingGuestWorkWaiterBytes / (1024 * 1024)} " +
                    $"waiters={SharpEmu.Libs.Agc.GpuWaitRegistry.Count}");
            }
        }
        // Work executed by the render-thread consumer can enqueue an ordered
        // same-queue completion marker. Blocking that consumer on the normal
        // producer backpressure limit deadlocks a full queue: no other thread
        // can drain an item to make room for the marker. The consumer has
        // already removed the current item, and each immediate follow-up is
        // bounded by that item, so admitting it cannot cause unbounded growth.
        //
        // Item cap applies to payload-bearing compute/draw/image writes. Zero-
        // payload ordered sync / flip markers use a higher sync ceiling so
        // ACQUIRE/label traffic cannot hard-block behind the 512 draw cap.
        // Byte budget remains the RAM safety valve for fat dispatches
        // (SHARPEMU_PENDING_GUEST_WORK_MB).
        // [V61.13.17][CINEMATIC_BACKPRESSURE]
        // Do not drop or reorder guest work. During the two host-decoded boot
        // movies, back-pressure payload-bearing graphics/compute work while
        // still allowing ordered sync/flip markers. This prevents the game's
        // HighGraphics/resource startup from retaining multi-GB texture
        // snapshots and saturating the GPU behind an exclusive movie.
        // [V74.0.47][BACKPRESSURE_WAIT_TIMING]
        var backpressureStartV74047 = Stopwatch.GetTimestamp();
        while (!_enqueueAsImmediateQueueFollowup &&
               !_closed &&
               _thread is not null &&
               ((isPayloadWork &&
                 SharpEmu.Libs.Media.BinkHostPlaybackAssist.ShouldThrottleGuestGpu) ||
                (isPayloadWork &&
                 _pendingPayloadGuestWorkCount >= _maxPendingGuestWorkItems) ||
                (!isPayloadWork &&
                 _pendingSyncGuestWorkCount >= _maxPendingGuestSyncItems) ||
                // Always admit one item when no payload is outstanding, even
                // when that single item exceeds the configured budget.
                (_pendingGuestWorkBytes != 0 &&
                 payloadBytes > pendingByteBudget -
                     Math.Min(_pendingGuestWorkBytes, pendingByteBudget))))
        {
            if (!backpressureLogged)
            {
                backpressureLogged = true;
                var traceCount = Interlocked.Increment(
                    ref _guestQueueBackpressureTraceCount);
                if (traceCount <= 16 || (traceCount & (traceCount - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.guest_queue_backpressure " +
                        $"count={traceCount} " +
                        $"queued={_pendingGuestWorkCount} " +
                        $"payload={_pendingPayloadGuestWorkCount}/{_maxPendingGuestWorkItems} " +
                        $"sync={_pendingSyncGuestWorkCount}/{_maxPendingGuestSyncItems} " +
                        $"logical_queues={_pendingGuestWorkByQueue.Count} " +
                        $"retained_mb={_pendingGuestWorkBytes / (1024 * 1024)} " +
                        $"incoming_mb={payloadBytes / (1024 * 1024)} " +
                        $"budget_mb={pendingByteBudget / (1024 * 1024)} " +
                        $"soft_budget_mb={_maxPendingGuestWorkBytes / (1024 * 1024)} " +
                        $"escape={(parserEscapeActive ? 1 : 0)} " +
                        $"work={work.GetType().Name}" +
                        GetGuestWorkPayloadBreakdown(work) +
                        FormatGuestQueueBacklogLocked());
                }

                // Sustained full-queue backpressure is the North Yankton soft-lock
                // signature: ordered actions pile up and producers block for seconds.
                var atItemCap = isPayloadWork
                    ? _pendingPayloadGuestWorkCount >= _maxPendingGuestWorkItems
                    : _pendingSyncGuestWorkCount >= _maxPendingGuestSyncItems;
                if (atItemCap &&
                    _pendingGuestWorkCount != _guestQueueStarvationLastQueued)
                {
                    _guestQueueStarvationLastQueued = _pendingGuestWorkCount;
                    var starvationCount = Interlocked.Increment(
                        ref _guestQueueStarvationTraceCount);
                    if (starvationCount <= 8 || (starvationCount & (starvationCount - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[LOADER][WARN] vk.guest_queue_starvation " +
                            $"count={starvationCount} " +
                            $"queued={_pendingGuestWorkCount} " +
                            $"payload={_pendingPayloadGuestWorkCount}/{_maxPendingGuestWorkItems} " +
                            $"sync={_pendingSyncGuestWorkCount}/{_maxPendingGuestSyncItems} " +
                            $"work={work.GetType().Name}" +
                            FormatGuestQueueBacklogLocked());
                    }
                }
            }

            var cinematicThrottle =
                isPayloadWork &&
                SharpEmu.Libs.Media.BinkHostPlaybackAssist.ShouldThrottleGuestGpu;
            System.Threading.Monitor.Wait(
                _gate,
                cinematicThrottle ? 2 : System.Threading.Timeout.Infinite);
        }

        if (backpressureLogged)
        {
            var blockedMsV74047 =
                (Stopwatch.GetTimestamp() - backpressureStartV74047) *
                1000.0 / Stopwatch.Frequency;
            if (blockedMsV74047 >= 1.0)
            {
                var traceV74047 = Interlocked.Increment(
                    ref _v74047BackpressureWaitTraceCount);
                if (traceV74047 <= 128 ||
                    (traceV74047 & (traceV74047 - 1)) == 0)
                {
                    var blockedQueueV74047 =
                        _submittingGuestQueue ?? VulkanGuestQueueIdentity.Default;
                    Console.Error.WriteLine(
                        $"[V74.0.47][BACKPRESSURE_WAIT] " +
                        $"count={traceV74047} ms={blockedMsV74047:F3} " +
                        $"queue={blockedQueueV74047.Name} " +
                        $"submission={blockedQueueV74047.SubmissionId} " +
                        $"waiters={SharpEmu.Libs.Agc.GpuWaitRegistry.Count} " +
                        $"payload_mb={payloadBytes / (1024 * 1024)} " +
                        $"retained_mb={_pendingGuestWorkBytes / (1024 * 1024)} " +
                        $"budget_mb={pendingByteBudget / (1024 * 1024)} " +
                        $"work={work.GetType().Name}");
                }
            }
        }

        if (_closed)
        {
            return 0;
        }

        var queue = _submittingGuestQueue ?? VulkanGuestQueueIdentity.Default;
        var sequence = ++_enqueuedGuestWorkSequence;
        _lastEnqueuedGuestWorkByQueue[queue.Name] = sequence;
        var requiredSequence = GetGuestWorkDependencyLocked(work);
        if (work is VulkanGlobalOrderedGuestAction)
        {
            requiredSequence = Math.Max(requiredSequence, sequence - 1);
        }

        // The guest's flip packet is a frame boundary. Logical graphics and
        // asynchronous-compute queues are scheduled independently above, but a
        // flip must not capture a partially composed frame merely because its
        // own queue head is ready. Make it a global barrier over all work
        // submitted before the flip. This removes the timing dependency where
        // SHARPEMU_LOG_AGC=1 happened to slow producers enough to center the
        // final composition correctly.
        if (work is VulkanOrderedGuestFlip)
        {
            requiredSequence = Math.Max(requiredSequence, sequence - 1);
        }
        if (!_pendingGuestWorkByQueue.TryGetValue(queue.Name, out var pendingQueue))
        {
            pendingQueue = new LinkedList<PendingGuestWork>();
            _pendingGuestWorkByQueue.Add(queue.Name, pendingQueue);
            _pendingGuestQueueSchedule.Add(queue.Name);
        }

        var pending = new PendingGuestWork(
            work,
            payloadBytes,
            sequence,
            requiredSequence,
            System.Diagnostics.Stopwatch.GetTimestamp(),
            queue);
        if (_traceGuestWorkCompletion)
        {
            Console.Error.WriteLine(
                $"[LOADER][TRACE] vk.guest_work_enqueue sequence={sequence} " +
                $"required={requiredSequence} queue={queue.Name} " +
                $"immediate={_enqueueAsImmediateQueueFollowup} " +
                $"work={work.GetType().Name}");
        }
        if (_enqueueAsImmediateQueueFollowup &&
            _immediateFollowupTail is { List: not null } tail &&
            ReferenceEquals(tail.List, pendingQueue))
        {
            _immediateFollowupTail = pendingQueue.AddAfter(tail, pending);
        }
        else if (_enqueueAsImmediateQueueFollowup)
        {
            _immediateFollowupTail = pendingQueue.AddFirst(pending);
        }
        else
        {
        pendingQueue.AddLast(pending);
        }
        RecordGuestImageWritersLocked(work, sequence);
        _pendingGuestWorkCount++;
        if (isPayloadWork)
        {
            _pendingPayloadGuestWorkCount++;
        }
        else
        {
            _pendingSyncGuestWorkCount++;
        }

        _pendingGuestWorkBytes = SaturatingAdd(_pendingGuestWorkBytes, payloadBytes);
        // Wake any thread waiting for guest work completion or queue space.
        System.Threading.Monitor.PulseAll(_gate);
        return sequence;
    }

    private static bool IsPayloadBearingGuestWork(object work) => work is
        VulkanComputeGuestDispatch or
        VulkanOffscreenGuestDraw or
        VulkanGuestImageWrite or
        VulkanOffscreenColorClear;

    private static bool IsPrioritySyncGuestWork(object work) => work is
        VulkanGlobalOrderedGuestAction or
        VulkanOrderedGuestAction or
        VulkanOrderedGuestFlip or
        VulkanOrderedGuestFlipWait;

    private static string FormatGuestQueueBacklogLocked()
    {
        var typeCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        var orderedNameCounts = new Dictionary<string, int>(StringComparer.Ordinal);
        foreach (var queue in _pendingGuestWorkByQueue.Values)
        {
            for (var node = queue.First; node is not null; node = node.Next)
            {
                var work = node.Value.Work;
                var typeName = work.GetType().Name;
                typeCounts[typeName] = typeCounts.GetValueOrDefault(typeName) + 1;
                if (work is VulkanOrderedGuestAction ordered)
                {
                    var prefix = GetOrderedActionDebugPrefix(ordered.DebugName);
                    orderedNameCounts[prefix] = orderedNameCounts.GetValueOrDefault(prefix) + 1;
                }
            }
        }

        static string TopEntries(Dictionary<string, int> counts, int limit)
        {
            if (counts.Count == 0)
            {
                return "-";
            }

            return string.Join(
                ',',
                counts
                    .OrderByDescending(static entry => entry.Value)
                    .Take(limit)
                    .Select(static entry => $"{entry.Key}:{entry.Value}"));
        }

        return $" types=[{TopEntries(typeCounts, 6)}]" +
               $" ordered=[{TopEntries(orderedNameCounts, 8)}]";
    }

    private static string GetOrderedActionDebugPrefix(string debugName)
    {
        if (string.IsNullOrEmpty(debugName))
        {
            return "(empty)";
        }

        var span = debugName.AsSpan();
        var cut = span.IndexOfAny(' ', '=');
        if (cut <= 0)
        {
            cut = Math.Min(span.Length, 48);
        }

        return debugName[..cut];
    }

    private static long GetGuestWorkDependencyLocked(object work)
    {
        static IEnumerable<ulong> TextureAddresses(
            IReadOnlyList<GuestDrawTexture> textures) =>
            textures
                .Where(static texture => texture.Address != 0)
                .Select(static texture => texture.Address);

        static IEnumerable<ulong> DepthAddresses(GuestDepthTarget? depth)
        {
            if (depth is null)
            {
                yield break;
            }

            if (depth.Address != 0)
            {
                yield return depth.Address;
            }
            if (depth.ReadAddress != 0 && depth.ReadAddress != depth.Address)
            {
                yield return depth.ReadAddress;
            }
            if (depth.WriteAddress != 0 &&
                depth.WriteAddress != depth.Address &&
                depth.WriteAddress != depth.ReadAddress)
            {
                yield return depth.WriteAddress;
            }
        }

        IReadOnlyList<GuestDrawTexture> textures = work switch
        {
            VulkanOffscreenGuestDraw draw => draw.Draw.Textures,
            VulkanComputeGuestDispatch compute => compute.Textures,
            _ => Array.Empty<GuestDrawTexture>(),
        };
        IReadOnlyList<GuestMemoryBuffer> globalBuffers = work switch
        {
            VulkanOffscreenGuestDraw draw => draw.Draw.GlobalMemoryBuffers,
            VulkanComputeGuestDispatch compute => compute.GlobalMemoryBuffers,
            _ => Array.Empty<GuestMemoryBuffer>(),
        };
        IEnumerable<ulong> imageAddresses = work switch
        {
            VulkanOffscreenGuestDraw draw =>
                TextureAddresses(draw.Draw.Textures)
                    .Concat(draw.Targets
                        .Where(static target => target.Address != 0)
                        .Select(static target => target.Address))
                    .Concat(DepthAddresses(draw.DepthTarget)),
            VulkanComputeGuestDispatch compute => TextureAddresses(compute.Textures),
            VulkanOffscreenColorClear clear => clear.Targets
                .Where(static target => target.Address != 0)
                .Select(static target => target.Address),
            _ => Array.Empty<ulong>(),
        };

        // Resource hazards are a host-side correctness dependency in addition
        // to explicit guest WAIT_REG_MEM synchronization. Logical PS5 queues are
        // multiplexed onto one Vulkan queue; without this edge, round-robin
        // scheduling can execute a consumer before the work item that creates or
        // writes its sampled/storage/color/depth resource has even completed.
        var required = 0L;
        var imageDependency = 0L;
        var bufferDependency = 0L;
        foreach (var address in imageAddresses.Distinct())
        {
            if (_guestImageWorkSequences.TryGetValue(address, out var writerSequence))
            {
                imageDependency = Math.Max(imageDependency, writerSequence);
                required = Math.Max(required, writerSequence);
            }
        }

        // V23: overlapping guest-image ranges carry producer dependencies.
        // PS5 images alias unified guest memory; a consumer may use a different
        // base address inside a previously produced image allocation.
        foreach (var texture in textures)
        {
            if (texture.Address == 0)
            {
                continue;
            }
            var rowLength = texture.TileMode == 0
                ? Math.Max(texture.Pitch, texture.Width)
                : texture.Width;
            var textureBytes = GetGuestImageByteCount(
                texture.Format,
                rowLength,
                texture.Height,
                GetGuestTextureDepth(texture.Type, texture.Depth));
            if (textureBytes == 0 || ulong.MaxValue - texture.Address < textureBytes)
            {
                continue;
            }
            var textureEnd = texture.Address + textureBytes;
            foreach (var image in _guestImageExtents)
            {
                if (image.Key == texture.Address ||
                    image.Value.ByteCount == 0 ||
                    ulong.MaxValue - image.Key < image.Value.ByteCount ||
                    !_guestImageWorkSequences.TryGetValue(image.Key, out var writerSequence))
                {
                    continue;
                }
                var imageEnd = image.Key + image.Value.ByteCount;
                if (texture.Address < imageEnd && image.Key < textureEnd)
                {
                    imageDependency = Math.Max(imageDependency, writerSequence);
                    required = Math.Max(required, writerSequence);
                }
            }
        }
        // Preserve the pre-existing initial-storage-upload edge. It is format
        // scoped because two compatible views of one guest VA can coexist.
        foreach (var texture in textures)
        {
            if (!texture.IsStorage ||
                texture.Address == 0 ||
                texture.RgbaPixels.Length != 0)
            {
                continue;
            }

            var format = GetGuestTextureFormat(texture.Format, texture.NumberType);
            if (_pendingGuestImageUploads.TryGetValue(
                    (texture.Address, format),
                    out var pendingUpload))
            {
                imageDependency = Math.Max(imageDependency, pendingUpload.OwnerSequence);
                required = Math.Max(required, pendingUpload.OwnerSequence);
            }
        }

        PruneCompletedGuestBufferWriterRangesLocked();

        // KytyPS5 297971c equivalent: an image writer must consume any older
        // buffer ownership covering the exact bytes it is about to replace.
        // This adds the one required producer edge before ownership is
        // transferred below, instead of making every later image consumer wait
        // on a stale buffer-range writer indefinitely.
        foreach (var imageRange in EnumerateGuestImageWriteRanges(work))
        {
            foreach (var writer in _guestBufferWorkRanges)
            {
                if (imageRange.Start < writer.End && writer.Start < imageRange.End)
                {
                    bufferDependency = Math.Max(bufferDependency, writer.Sequence);
                    required = Math.Max(required, writer.Sequence);
                }
            }
        }

        foreach (var buffer in globalBuffers)
        {
            if (!TryGetGuestBufferRange(buffer, out var bufferStart, out var bufferEnd))
            {
                continue;
            }

            foreach (var writer in _guestBufferWorkRanges)
            {
                if (bufferStart < writer.End && writer.Start < bufferEnd)
                {
                    bufferDependency = Math.Max(bufferDependency, writer.Sequence);
                    required = Math.Max(required, writer.Sequence);
                }
            }
        }

        // V21: image metadata is a guest-memory resource dependency, not inert descriptor decoration.
        // AGC already decodes the metadata VA from the extended RDNA2 SRD. If a prior
        // compute/global-buffer write owns the range containing that VA, sampling the
        // image must wait for that producer just like an ordinary global-buffer read.
        foreach (var texture in textures)
        {
            var metadataAddress = texture.MetadataAddress;
            if (metadataAddress == 0)
            {
                continue;
            }

            foreach (var writer in _guestBufferWorkRanges)
            {
                if (writer.Start <= metadataAddress && metadataAddress < writer.End)
                {
                    bufferDependency = Math.Max(bufferDependency, writer.Sequence);
                    required = Math.Max(required, writer.Sequence);
                }
            }
        }
        if (_traceResourceDependencies &&
            required > 0 &&
            Interlocked.Increment(ref _resourceDependencyTraceCount) <= 512)
        {
            Console.Error.WriteLine(
                $"[LOADER][TRACE] vk.resource_dependency " +
                $"work={work.GetType().Name} required={required} " +
                $"image={imageDependency} buffer={bufferDependency} " +
                $"textures={textures.Count} globals={globalBuffers.Count}");
        }

        return required;
    }

    private static void RecordGuestImageWritersLocked(object work, long sequence)
    {
        static IEnumerable<ulong> StorageAddresses(
            IReadOnlyList<GuestDrawTexture> textures) =>
            textures
                .Where(static texture => texture.IsStorage && texture.Address != 0)
                .Select(static texture => texture.Address);

        static IEnumerable<ulong> DepthWriteAddresses(VulkanOffscreenGuestDraw draw)
        {
            var depth = draw.DepthTarget;
            if (depth is null ||
                (!draw.Draw.RenderState.Depth.WriteEnable &&
                 !draw.Draw.RenderState.Depth.ClearEnable))
            {
                yield break;
            }

            if (depth.Address != 0)
            {
                yield return depth.Address;
            }
            if (depth.ReadAddress != 0 && depth.ReadAddress != depth.Address)
            {
                yield return depth.ReadAddress;
            }
            if (depth.WriteAddress != 0 &&
                depth.WriteAddress != depth.Address &&
                depth.WriteAddress != depth.ReadAddress)
            {
                yield return depth.WriteAddress;
            }
        }

        IEnumerable<ulong> addresses = work switch
        {
            VulkanOffscreenGuestDraw draw =>
                draw.Targets
                    .Where(static target => target.Address != 0)
                    .Select(static target => target.Address)
                    .Concat(StorageAddresses(draw.Draw.Textures))
                    .Concat(DepthWriteAddresses(draw)),
            VulkanOffscreenColorClear clear =>
                clear.Targets
                    .Where(static target => target.Address != 0)
                    .Select(static target => target.Address),
            VulkanComputeGuestDispatch compute => StorageAddresses(compute.Textures),
            VulkanGuestImageWrite imageWrite when imageWrite.Address != 0 =>
                new[] { imageWrite.Address },
            _ => Array.Empty<ulong>(),
        };
        foreach (var address in addresses.Distinct())
        {
            _guestImageWorkSequences[address] = sequence;
        }

        // The image write now owns only the byte ranges it actually replaces.
        // Subtract those bytes from older buffer-writer intervals while keeping
        // unaffected left/right fragments and their original sequence.
        DiscardSupersededGuestBufferWriterRangesLocked(work, sequence);
        RecordGuestBufferWritersLocked(work, sequence);
    }

    private static IEnumerable<(ulong Start, ulong End)> EnumerateGuestImageWriteRanges(
        object work)
    {
        static bool TryRange(
            ulong address,
            ulong byteCount,
            out (ulong Start, ulong End) range)
        {
            if (address == 0 || byteCount == 0 ||
                address > ulong.MaxValue - byteCount)
            {
                range = default;
                return false;
            }

            range = (address, address + byteCount);
            return true;
        }

        static IEnumerable<(ulong Start, ulong End)> TextureRanges(
            IReadOnlyList<GuestDrawTexture> textures)
        {
            foreach (var texture in textures)
            {
                if (!texture.IsStorage || texture.Address == 0)
                {
                    continue;
                }

                var rowLength = texture.TileMode == 0
                    ? Math.Max(texture.Pitch, texture.Width)
                    : texture.Width;
                var byteCount = GetGuestImageByteCount(
                    texture.Format,
                    rowLength,
                    texture.Height,
                    GetGuestTextureDepth(texture.Type, texture.Depth));
                if (TryRange(texture.Address, byteCount, out var range))
                {
                    yield return range;
                }
            }
        }

        switch (work)
        {
            case VulkanOffscreenGuestDraw draw:
                foreach (var target in draw.Targets)
                {
                    var byteCount = GetGuestImageByteCount(
                        target.Format,
                        target.Width,
                        target.Height);
                    if (TryRange(target.Address, byteCount, out var range))
                    {
                        yield return range;
                    }
                }
                foreach (var range in TextureRanges(draw.Draw.Textures))
                {
                    yield return range;
                }
                break;

            case VulkanOffscreenColorClear clear:
                foreach (var target in clear.Targets)
                {
                    var byteCount = GetGuestImageByteCount(
                        target.Format,
                        target.Width,
                        target.Height);
                    if (TryRange(target.Address, byteCount, out var range))
                    {
                        yield return range;
                    }
                }
                break;

            case VulkanComputeGuestDispatch compute:
                foreach (var range in TextureRanges(compute.Textures))
                {
                    yield return range;
                }
                break;
        }
    }

    private static void DiscardSupersededGuestBufferWriterRangesLocked(
        object work,
        long sequence)
    {
        PruneCompletedGuestBufferWriterRangesLocked();
        foreach (var imageRange in EnumerateGuestImageWriteRanges(work))
        {
            for (var index = _guestBufferWorkRanges.Count - 1; index >= 0; index--)
            {
                var existing = _guestBufferWorkRanges[index];
                if (existing.Sequence >= sequence ||
                    imageRange.Start >= existing.End ||
                    existing.Start >= imageRange.End)
                {
                    continue;
                }

                _guestBufferWorkRanges.RemoveAt(index);
                if (existing.Start < imageRange.Start)
                {
                    _guestBufferWorkRanges.Add(new GuestBufferWorkRange(
                        existing.Start,
                        Math.Min(existing.End, imageRange.Start),
                        existing.Sequence));
                }
                if (imageRange.End < existing.End)
                {
                    _guestBufferWorkRanges.Add(new GuestBufferWorkRange(
                        Math.Max(existing.Start, imageRange.End),
                        existing.End,
                        existing.Sequence));
                }

                if (_traceResourceDependencies &&
                    Interlocked.Increment(ref _bufferImageOwnershipTraceCount) <= 256)
                {
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.buffer_image_ownership_transfer " +
                        $"sequence={sequence} image=0x{imageRange.Start:X16}-0x{imageRange.End:X16} " +
                        $"old=0x{existing.Start:X16}-0x{existing.End:X16}@{existing.Sequence}");
                }
            }
        }
    }

    private static void RecordGuestBufferWritersLocked(object work, long sequence)
    {
        IReadOnlyList<GuestMemoryBuffer> buffers;
        var conservativelyWritable = false;
        switch (work)
        {
            case VulkanOffscreenGuestDraw draw:
                buffers = draw.Draw.GlobalMemoryBuffers;
                break;
            case VulkanComputeGuestDispatch compute:
                buffers = compute.GlobalMemoryBuffers;
                conservativelyWritable = compute.WritesGlobalMemory;
                break;
            default:
                return;
        }

        PruneCompletedGuestBufferWriterRangesLocked();
        foreach (var buffer in buffers)
        {
            if ((!conservativelyWritable && !buffer.Writable) ||
                !TryGetGuestBufferRange(buffer, out var bufferStart, out var bufferEnd))
            {
                continue;
            }

            // Replace older exact/contained ranges from the same VA region. Keep
            // partially overlapping ranges because descriptors can legally alias
            // one large guest allocation at different offsets.
            for (var index = _guestBufferWorkRanges.Count - 1; index >= 0; index--)
            {
                var existing = _guestBufferWorkRanges[index];
                if (bufferStart <= existing.Start && existing.End <= bufferEnd)
                {
                    _guestBufferWorkRanges.RemoveAt(index);
                }
            }

            _guestBufferWorkRanges.Add(
                new GuestBufferWorkRange(bufferStart, bufferEnd, sequence));
        }

        if (_guestBufferWorkRanges.Count > MaxGuestBufferWorkRanges)
        {
            _guestBufferWorkRanges.Sort(static (left, right) =>
                left.Sequence.CompareTo(right.Sequence));
            _guestBufferWorkRanges.RemoveRange(
                0,
                _guestBufferWorkRanges.Count - MaxGuestBufferWorkRanges);
        }
    }

    private static bool TryGetGuestBufferRange(
        GuestMemoryBuffer buffer,
        out ulong start,
        out ulong end)
    {
        start = buffer.BaseAddress;
        var length = (ulong)Math.Max(buffer.Length, sizeof(uint));
        if (start == 0 || start > ulong.MaxValue - length)
        {
            end = 0;
            return false;
        }

        end = start + length;
        return true;
    }

    private static void PruneCompletedGuestBufferWriterRangesLocked()
    {
        for (var index = _guestBufferWorkRanges.Count - 1; index >= 0; index--)
        {
            if (IsGuestWorkCompletedLocked(_guestBufferWorkRanges[index].Sequence))
            {
                _guestBufferWorkRanges.RemoveAt(index);
            }
        }
    }

    private static bool TryTakeGuestWork(
        out PendingGuestWork work,
        HashSet<string>? excludedQueues = null,
        bool preferSyncWork = false)
    {
        lock (_gate)
        {
            // [V74.0.46][FIFO_WATCHED_PRODUCER_ASSIST]
            // Drain the real producer queue in FIFO order instead of moving the
            // producer packet itself ahead of earlier commands.
            if (_fifoWatchedProducerAssistV74046 &&
                TryTakeFifoWatchedProducerQueueHeadLocked(
                    out work,
                    excludedQueues))
            {
                return true;
            }

            // SHARPEMU_V74_0_29_2_WATCHED_WRITE_CONTROL_LANE
            // V74.0.29.1 proved that all long-lived watched WRITE_DATA actions
            // in the captured run had RequiredSequence=0, yet several remained
            // behind payload work for >4 seconds. A literal CPU-resident
            // WRITE_DATA can therefore progress as a control packet while the
            // host keeps expensive draw/compute translation queued.
            if (_watchedWriteControlLaneV740292 &&
                TryTakeWatchedWriteControlLaneLocked(
                    out work,
                    excludedQueues))
            {
                return true;
            }

            // V74.0.28 is intentionally narrower than V73.0.14:
            // only a ready queue HEAD that produces an address currently
            // watched by WAIT_REG_MEM may win cross-queue selection.
            if (TryTakeWatchedProducerGuestWorkLocked(
                    out work,
                    excludedQueues))
            {
                return true;
            }

            if (preferSyncWork &&
                TryTakePreferredSyncGuestWorkLocked(out work, excludedQueues))
            {
                return true;
            }

            var queuesToProbe = _pendingGuestQueueSchedule.Count;
            while (_pendingGuestQueueSchedule.Count > 0 && queuesToProbe > 0)
            {
                if (_pendingGuestQueueCursor >= _pendingGuestQueueSchedule.Count)
                {
                    _pendingGuestQueueCursor = 0;
                }

                var queueName = _pendingGuestQueueSchedule[_pendingGuestQueueCursor];
                if (excludedQueues?.Contains(queueName) == true)
                {
                    _pendingGuestQueueCursor =
                        (_pendingGuestQueueCursor + 1) % _pendingGuestQueueSchedule.Count;
                    queuesToProbe--;
                    continue;
                }

                if (!_pendingGuestWorkByQueue.TryGetValue(queueName, out var queue) ||
                    queue.First is not { } first)
                {
                    _pendingGuestWorkByQueue.Remove(queueName);
                    _pendingGuestQueueSchedule.RemoveAt(_pendingGuestQueueCursor);
                    queuesToProbe = Math.Min(
                        queuesToProbe,
                        _pendingGuestQueueSchedule.Count);
                    continue;
                }

                work = first.Value;
                if (!IsGuestWorkCompletedLocked(work.RequiredSequence))
                {
                    _pendingGuestQueueCursor =
                        (_pendingGuestQueueCursor + 1) % _pendingGuestQueueSchedule.Count;
                    queuesToProbe--;
                    continue;
                }

                var keepQueueForBurst = false;
                if (_queueSubmissionBurstV74043 > 1 &&
                    first.Next is { } next &&
                    next.Value.Queue.SubmissionId == work.Queue.SubmissionId &&
                    IsGuestWorkCompletedLocked(next.Value.RequiredSequence) &&
                    work.Work is not VulkanOrderedGuestFlip &&
                    work.Work is not VulkanOrderedGuestFlipWait &&
                    next.Value.Work is not VulkanOrderedGuestFlip &&
                    next.Value.Work is not VulkanOrderedGuestFlipWait)
                {
                    if (!string.Equals(
                            _v74043BurstQueueName,
                            queueName,
                            StringComparison.Ordinal) ||
                        _v74043BurstSubmissionId != work.Queue.SubmissionId ||
                        _v74043BurstRemaining <= 0)
                    {
                        _v74043BurstQueueName = queueName;
                        _v74043BurstSubmissionId = work.Queue.SubmissionId;
                        _v74043BurstRemaining = _queueSubmissionBurstV74043 - 1;
                    }
                    else
                    {
                        _v74043BurstRemaining--;
                    }

                    keepQueueForBurst = _v74043BurstRemaining > 0;
                    if (keepQueueForBurst)
                    {
                        var burstCount = Interlocked.Increment(
                            ref _v74043QueueBurstTraceCount);
                        if (burstCount <= 64 ||
                            (burstCount & (burstCount - 1)) == 0)
                        {
                            Console.Error.WriteLine(
                                $"[V74.0.43][QUEUE_SUBMISSION_BURST] " +
                                $"count={burstCount} queue={queueName} " +
                                $"submission={work.Queue.SubmissionId} " +
                                $"remaining={_v74043BurstRemaining} " +
                                $"sequence={work.Sequence} " +
                                $"next_sequence={next.Value.Sequence}");
                        }
                    }
                }

                RemoveTakenGuestWorkLocked(
                    queueName,
                    queue,
                    advanceScheduleCursor: !keepQueueForBurst);
                if (!keepQueueForBurst)
                {
                    _v74043BurstQueueName = null;
                    _v74043BurstSubmissionId = 0;
                    _v74043BurstRemaining = 0;
                }

                return true;
            }

            work = default;
            return false;
        }
    }

    private static bool TryTakeFifoWatchedProducerQueueHeadLocked(
        out PendingGuestWork work,
        HashSet<string>? excludedQueues)
    {
        // [V74.0.47][FIFO_PRODUCER_SCAN_DEPTH]
        var maxScanDepth = _fifoWatchedProducerScanDepthV74047;

        if (SharpEmu.Libs.Agc.GpuWaitRegistry.Count == 0)
        {
            work = default;
            return false;
        }

        for (var scheduleIndex = 0;
             scheduleIndex < _pendingGuestQueueSchedule.Count;
             scheduleIndex++)
        {
            var queueName = _pendingGuestQueueSchedule[scheduleIndex];
            if (excludedQueues?.Contains(queueName) == true ||
                !_pendingGuestWorkByQueue.TryGetValue(queueName, out var queue) ||
                queue.First is not { } head ||
                !IsGuestWorkCompletedLocked(head.Value.RequiredSequence))
            {
                continue;
            }

            var distance = 0;
            for (var node = head;
                 node is not null && distance < maxScanDepth;
                 node = node.Next, distance++)
            {
                var candidate = node.Value;
                if (candidate.Work is not VulkanOrderedGuestAction
                    {
                        WaitProducerMemory: { } producerMemory,
                        WaitProducerAddress: not 0,
                        WaitProducerLength: not 0,
                    } ordered ||
                    candidate.RequiredSequence != 0 ||
                    !ordered.DebugName.StartsWith(
                        "write_data dst=",
                        StringComparison.Ordinal))
                {
                    continue;
                }

                var waiterCount = GpuWaitRegistry.SnapshotInRange(
                    producerMemory,
                    ordered.WaitProducerAddress,
                    ordered.WaitProducerLength).Count;
                if (waiterCount == 0)
                {
                    continue;
                }

                // Queue-head producers are already handled by V74.0.28. V46 is
                // specifically the safe FIFO alternative to bypassing payload.
                if (distance == 0)
                {
                    break;
                }

                work = head.Value;
                RemoveTakenGuestWorkLocked(
                    queueName,
                    queue,
                    advanceScheduleCursor: false);

                // Keep the cursor on this producer queue. The next scheduling
                // pass re-evaluates the live waiter before taking another head,
                // so the preference ends immediately when the wait is satisfied.
                var assistCount = Interlocked.Increment(
                    ref _v74046FifoWatchedProducerAssistTraceCount);
                if (assistCount <= 128 ||
                    (assistCount & (assistCount - 1)) == 0)
                {
                    var producerQueuedMs =
                        (Stopwatch.GetTimestamp() - candidate.EnqueuedTicks) *
                        1000.0 / Stopwatch.Frequency;
                    Console.Error.WriteLine(
                        $"[V74.0.46][FIFO_WATCHED_PRODUCER_ASSIST] " +
                        $"count={assistCount} queue={queueName} " +
                        $"submission={head.Value.Queue.SubmissionId} " +
                        $"head_sequence={head.Value.Sequence} " +
                        $"producer_sequence={candidate.Sequence} " +
                        $"distance={distance} scan_depth={maxScanDepth} " +
                        $"waiters={waiterCount} " +
                        $"producer_queued_ms={producerQueuedMs:F3} " +
                        $"addr=0x{ordered.WaitProducerAddress:X16} " +
                        $"bytes={ordered.WaitProducerLength}");
                }

                return true;
            }
        }

        work = default;
        return false;
    }

    private static bool TryTakeWatchedWriteControlLaneLocked(
        out PendingGuestWork work,
        HashSet<string>? excludedQueues)
    {
        const int MaxScanDepth = 256;

        for (var scheduleIndex = 0;
             scheduleIndex < _pendingGuestQueueSchedule.Count;
             scheduleIndex++)
        {
            var queueName = _pendingGuestQueueSchedule[scheduleIndex];
            if (excludedQueues?.Contains(queueName) == true ||
                !_pendingGuestWorkByQueue.TryGetValue(queueName, out var queue) ||
                queue.First is not { } head)
            {
                continue;
            }

            var skippedPayload = 0;
            var scanned = 0;
            for (var node = head;
                 node is not null && scanned < MaxScanDepth;
                 node = node.Next, scanned++)
            {
                var candidate = node.Value;

                if (candidate.Work is VulkanOrderedGuestAction
                    {
                        WaitProducerMemory: { } producerMemory,
                        WaitProducerAddress: not 0,
                        WaitProducerLength: not 0,
                    } ordered)
                {
                    if (candidate.RequiredSequence != 0 ||
                        !ordered.DebugName.StartsWith(
                            "write_data dst=",
                            StringComparison.Ordinal) ||
                        GpuWaitRegistry.SnapshotInRange(
                            producerMemory,
                            ordered.WaitProducerAddress,
                            ordered.WaitProducerLength).Count == 0)
                    {
                        break;
                    }

                    // A producer already at queue head needs no lane; leave it
                    // to the normal watched-producer selector. More importantly,
                    // never bypass a head that was not proven payload-bearing.
                    if (skippedPayload == 0)
                    {
                        break;
                    }

                    work = candidate;
                    queue.Remove(node);
                    _pendingGuestWorkCount--;
                    _pendingSyncGuestWorkCount =
                        Math.Max(0, _pendingSyncGuestWorkCount - 1);

                    if (_pendingGuestQueueSchedule.Count > 0)
                    {
                        _pendingGuestQueueCursor =
                            (Math.Min(
                                scheduleIndex,
                                _pendingGuestQueueSchedule.Count - 1) + 1) %
                            _pendingGuestQueueSchedule.Count;
                    }
                    else
                    {
                        _pendingGuestQueueCursor = 0;
                    }

                    var laneCount = Interlocked.Increment(
                        ref _v740292WatchedWriteControlLaneTraceCount);
                    if (laneCount <= 128 ||
                        (laneCount & (laneCount - 1)) == 0)
                    {
                        var queuedMilliseconds =
                            (Stopwatch.GetTimestamp() - candidate.EnqueuedTicks) *
                            1000.0 / Stopwatch.Frequency;
                        Console.Error.WriteLine(
                            $"[V74.0.29.2][WATCHED_WRITE_CONTROL_LANE] " +
                            $"count={laneCount} queue={candidate.Queue.Name} " +
                            $"submission={candidate.Queue.SubmissionId} " +
                            $"sequence={candidate.Sequence} " +
                            $"head_sequence={head.Value.Sequence} " +
                            $"skipped_payload={skippedPayload} " +
                            $"required={candidate.RequiredSequence} " +
                            $"queued_ms={queuedMilliseconds:F3} " +
                            $"addr=0x{ordered.WaitProducerAddress:X16} " +
                            $"bytes={ordered.WaitProducerLength} " +
                            $"name='{ordered.DebugName}'");
                    }

                    return true;
                }

                // Only draw/compute/image payload may be overtaken. Every
                // ordered action, flip, wait and synchronization marker is a
                // hard same-queue barrier.
                if (!IsPayloadBearingGuestWork(candidate.Work))
                {
                    break;
                }

                skippedPayload++;
            }
        }

        work = default;
        return false;
    }
    private static bool TryTakeWatchedProducerGuestWorkLocked(
        out PendingGuestWork work,
        HashSet<string>? excludedQueues)
    {
        for (var index = 0; index < _pendingGuestQueueSchedule.Count; index++)
        {
            var queueName = _pendingGuestQueueSchedule[index];
            if (excludedQueues?.Contains(queueName) == true ||
                !_pendingGuestWorkByQueue.TryGetValue(queueName, out var queue) ||
                queue.First is not { } first)
            {
                continue;
            }

            var candidate = first.Value;
            if (candidate.Work is not VulkanOrderedGuestAction
                {
                    WaitProducerMemory: { } producerMemory,
                    WaitProducerAddress: not 0,
                    WaitProducerLength: not 0,
                } ordered ||
                !IsGuestWorkCompletedLocked(candidate.RequiredSequence))
            {
                continue;
            }

            // Query the live registry at scheduling time. The producer is often
            // enqueued before another logical queue reaches WAIT_REG_MEM.
            if (GpuWaitRegistry.SnapshotInRange(
                    producerMemory,
                    ordered.WaitProducerAddress,
                    ordered.WaitProducerLength).Count == 0)
            {
                continue;
            }

            // This removes only queue.First. No earlier same-queue item can be
            // skipped, and RequiredSequence was checked above.
            work = candidate;
            RemoveTakenGuestWorkLocked(
                queueName,
                queue,
                advanceScheduleCursor: false);

            if (_pendingGuestQueueSchedule.Count > 0)
            {
                _pendingGuestQueueCursor =
                    (Math.Min(index, _pendingGuestQueueSchedule.Count - 1) + 1) %
                    _pendingGuestQueueSchedule.Count;
            }
            else
            {
                _pendingGuestQueueCursor = 0;
            }

            var priorityCount = Interlocked.Increment(
                ref _v74028WatchedProducerPriorityTraceCount);
            if (priorityCount <= 64 ||
                (priorityCount & (priorityCount - 1)) == 0)
            {
                var queuedMilliseconds =
                    (Stopwatch.GetTimestamp() - candidate.EnqueuedTicks) *
                    1000.0 / Stopwatch.Frequency;
                Console.Error.WriteLine(
                    $"[V74.0.28][WATCHED_WRITE_PRIORITY] count={priorityCount} " +
                    $"queue={candidate.Queue.Name} " +
                    $"submission={candidate.Queue.SubmissionId} " +
                    $"sequence={candidate.Sequence} " +
                    $"required={candidate.RequiredSequence} " +
                    $"queued_ms={queuedMilliseconds:F3} " +
                    $"addr=0x{ordered.WaitProducerAddress:X16} " +
                    $"bytes={ordered.WaitProducerLength} " +
                    $"name='{ordered.DebugName}'");
            }

            return true;
        }

        work = default;
        return false;
    }

    private static bool TryTakePreferredSyncGuestWorkLocked(
        out PendingGuestWork work,
        HashSet<string>? excludedQueues)
    {
        // When the backlog is elevated, prefer draining ordered sync / flip
        // markers ahead of heavy compute/draw heads on other logical queues.
        // Within a queue, FIFO still holds Ã¢â‚¬â€ we only choose among ready heads.
        for (var index = 0; index < _pendingGuestQueueSchedule.Count; index++)
        {
            var queueName = _pendingGuestQueueSchedule[index];
            if (excludedQueues?.Contains(queueName) == true)
            {
                continue;
            }

            if (!_pendingGuestWorkByQueue.TryGetValue(queueName, out var queue) ||
                queue.First is not { } first)
            {
                continue;
            }

            work = first.Value;
            if (!IsPrioritySyncGuestWork(work.Work) ||
                !IsGuestWorkCompletedLocked(work.RequiredSequence))
            {
                continue;
            }

            RemoveTakenGuestWorkLocked(queueName, queue, advanceScheduleCursor: false);
            if (_pendingGuestQueueSchedule.Count > 0)
            {
                _pendingGuestQueueCursor =
                    (Math.Min(index, _pendingGuestQueueSchedule.Count - 1) + 1) %
                    _pendingGuestQueueSchedule.Count;
            }
            else
            {
                _pendingGuestQueueCursor = 0;
            }

            return true;
        }

        work = default;
        return false;
    }

    private static void RemoveTakenGuestWorkLocked(
        string queueName,
        LinkedList<PendingGuestWork> queue,
        bool advanceScheduleCursor)
    {
        var work = queue.First!.Value;
        queue.RemoveFirst();
        _pendingGuestWorkCount--;
        if (IsPayloadBearingGuestWork(work.Work))
        {
            _pendingPayloadGuestWorkCount = Math.Max(0, _pendingPayloadGuestWorkCount - 1);
        }
        else
        {
            _pendingSyncGuestWorkCount = Math.Max(0, _pendingSyncGuestWorkCount - 1);
        }

        // SHARPEMU_V74_0_81_QUEUE_TO_INFLIGHT
        if (_separateInFlightGuestWorkBytesV74081 && work.PayloadBytes != 0)
        {
            _pendingGuestWorkBytes = work.PayloadBytes >= _pendingGuestWorkBytes
                ? 0
                : _pendingGuestWorkBytes - work.PayloadBytes;
            _inFlightGuestWorkBytesV74081 =
                SaturatingAdd(_inFlightGuestWorkBytesV74081, work.PayloadBytes);

            if (work.PayloadBytes >= 32UL * 1024UL * 1024UL)
            {
                var traceV74081 = Interlocked.Increment(
                    ref _v74081QueueToInFlightTraceCount);
                if (traceV74081 <= 64 || (traceV74081 & (traceV74081 - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        $"[V74.0.81][QUEUE_TO_INFLIGHT] count={traceV74081} " +
                        $"payload_mb={work.PayloadBytes / (1024 * 1024)} " +
                        $"queued_mb={_pendingGuestWorkBytes / (1024 * 1024)} " +
                        $"inflight_mb={_inFlightGuestWorkBytesV74081 / (1024 * 1024)} " +
                        $"work={work.Work.GetType().Name} queue={work.Queue.Name} " +
                        $"submission={work.Queue.SubmissionId}");
                }
            }
        }
        var scheduleIndex = _pendingGuestQueueSchedule.IndexOf(queueName);
        if (queue.Count == 0)
        {
            _pendingGuestWorkByQueue.Remove(queueName);
            if (scheduleIndex >= 0)
            {
                _pendingGuestQueueSchedule.RemoveAt(scheduleIndex);
                if (_pendingGuestQueueCursor > scheduleIndex)
                {
                    _pendingGuestQueueCursor--;
                }
                else if (_pendingGuestQueueCursor >= _pendingGuestQueueSchedule.Count)
                {
                    _pendingGuestQueueCursor = 0;
                }
            }
        }
        else if (advanceScheduleCursor && scheduleIndex >= 0)
        {
            _pendingGuestQueueCursor =
                (scheduleIndex + 1) % _pendingGuestQueueSchedule.Count;
        }
    }

    private static bool RequeueGuestWorkFront(in PendingGuestWork work)
    {
        lock (_gate)
        {
            if (_closed)
            {
                return false;
            }

            if (!_pendingGuestWorkByQueue.TryGetValue(work.Queue.Name, out var queue))
            {
                queue = new LinkedList<PendingGuestWork>();
                _pendingGuestWorkByQueue.Add(work.Queue.Name, queue);
                _pendingGuestQueueSchedule.Add(work.Queue.Name);
            }

            // TryTakeGuestWork removes only the item count. Payload ownership
            // remains live until CompleteGuestWork, so requeueing must not add
            // the retained-byte total a second time.
            queue.AddFirst(work);
            _pendingGuestWorkCount++;
            if (IsPayloadBearingGuestWork(work.Work))
            {
                _pendingPayloadGuestWorkCount++;
            }
            else
            {
                _pendingSyncGuestWorkCount++;
            }

            // SHARPEMU_V74_0_81_INFLIGHT_TO_QUEUE_ON_REQUEUE
            if (_separateInFlightGuestWorkBytesV74081 && work.PayloadBytes != 0)
            {
                _inFlightGuestWorkBytesV74081 =
                    work.PayloadBytes >= _inFlightGuestWorkBytesV74081
                        ? 0
                        : _inFlightGuestWorkBytesV74081 - work.PayloadBytes;
                _pendingGuestWorkBytes =
                    SaturatingAdd(_pendingGuestWorkBytes, work.PayloadBytes);
            }
            System.Threading.Monitor.PulseAll(_gate);
            return true;
        }
    }

    private static bool WaitForFollowupGuestWork(int timeoutMilliseconds)
    {
        lock (_gate)
        {
            if (_pendingGuestWorkCount > 0)
            {
                return true;
            }

            if (_closed)
            {
                return false;
            }

            System.Threading.Monitor.Wait(_gate, timeoutMilliseconds);
            return _pendingGuestWorkCount > 0;
        }
    }

    private static void CompleteGuestWork(in PendingGuestWork pending)
    {
        SharpEmu.HLE.GuestImageWriteTracker.FlushPendingDiagnostics();
        lock (_gate)
        {
            if (_traceGuestWorkCompletion)
            {
                Console.Error.WriteLine(
                    $"[LOADER][TRACE] vk.guest_work_complete_enter " +
                    $"sequence={pending.Sequence} work={pending.Work.GetType().Name} " +
                    $"contiguous_completed={_completedGuestWorkSequence} " +
                    $"out_of_order={_completedGuestWorkOutOfOrder.Count}");
            }
            if (_separateInFlightGuestWorkBytesV74081)
            {
                _inFlightGuestWorkBytesV74081 =
                    pending.PayloadBytes >= _inFlightGuestWorkBytesV74081
                        ? 0
                        : _inFlightGuestWorkBytesV74081 - pending.PayloadBytes;
            }
            else
            {
                _pendingGuestWorkBytes = pending.PayloadBytes >= _pendingGuestWorkBytes
                    ? 0
                    : _pendingGuestWorkBytes - pending.PayloadBytes;
            }
            ReleasePendingGuestImageUploadsLocked(pending.Work);
            if (pending.Sequence == _completedGuestWorkSequence + 1)
            {
                _completedGuestWorkSequence = pending.Sequence;
                while (_completedGuestWorkOutOfOrder.Remove(
                           _completedGuestWorkSequence + 1))
                {
                    _completedGuestWorkSequence++;
                }
            }
            else if (pending.Sequence > _completedGuestWorkSequence)
            {
                // Debug.Assert calls are compiled out of Release builds, so
                // never put the state mutation inside its argument. Doing so
                // discarded every out-of-order completion in normal runs and
                // left the first immediate follow-up as a permanent sequence
                // hole, blocking all later CPU-visible GPU waits.
                var added = _completedGuestWorkOutOfOrder.Add(pending.Sequence);
                System.Diagnostics.Debug.Assert(
                    added,
                    "A guest work sequence must complete exactly once.");
            }
            System.Threading.Monitor.PulseAll(_gate);
            if (_traceGuestWorkCompletion)
            {
                Console.Error.WriteLine(
                    $"[LOADER][TRACE] vk.guest_work_complete_exit " +
                    $"sequence={pending.Sequence} contiguous_completed={_completedGuestWorkSequence} " +
                    $"out_of_order={_completedGuestWorkOutOfOrder.Count}");
            }
        }
    }

    private static ulong GetGuestWorkPayloadBytes(object work) => work switch
    {
        VulkanComputeGuestDispatch compute => SaturatingAdd(
            GetTexturePayloadBytes(compute.Textures),
            GetGlobalBufferPayloadBytes(compute.GlobalMemoryBuffers)),
        VulkanOffscreenGuestDraw offscreen => GetDrawPayloadBytes(offscreen.Draw),
        VulkanGuestImageWrite { Pixels: { } pixels } => (ulong)pixels.LongLength,
        _ => 0,
    };

    private static string GetGuestWorkPayloadBreakdown(object work)
    {
        static ulong SumTextures(IReadOnlyList<GuestDrawTexture> textures) =>
            GetTexturePayloadBytes(textures) / (1024 * 1024);
        static ulong SumBridgeTiled(IReadOnlyList<GuestDrawTexture> textures) =>
            GetLargeArrayBridgeTiledPayloadBytesV74065(textures) / (1024 * 1024);
        static ulong SumGlobals(IReadOnlyList<GuestMemoryBuffer> buffers) =>
            GetGlobalBufferPayloadBytes(buffers) / (1024 * 1024);

        return work switch
        {
            VulkanOffscreenGuestDraw offscreen =>
                $" textures_mb={SumTextures(offscreen.Draw.Textures)}" +
                $" bridge_tiled_mb={SumBridgeTiled(offscreen.Draw.Textures)}" +
                $" globals_mb={SumGlobals(offscreen.Draw.GlobalMemoryBuffers)}" +
                $" vertex_mb={offscreen.Draw.VertexBuffers.Aggregate(0UL, static (sum, buffer) => SaturatingAdd(sum, (ulong)buffer.Data.LongLength)) / (1024 * 1024)}" +
                $" index_mb={(ulong)(offscreen.Draw.IndexBuffer?.Data.LongLength ?? 0) / (1024 * 1024)}" +
                $" vertex_lengths=[{string.Join(',', offscreen.Draw.VertexBuffers.Select(static buffer => $"{buffer.Length}/{buffer.Data.LongLength}:s{buffer.Stride}:o{buffer.OffsetBytes}"))}]" +
                $" global_lengths=[{string.Join(',', offscreen.Draw.GlobalMemoryBuffers.Select(static buffer => buffer.Length))}]",
            VulkanComputeGuestDispatch compute =>
                $" textures_mb={SumTextures(compute.Textures)}" +
                $" bridge_tiled_mb={SumBridgeTiled(compute.Textures)}" +
                $" globals_mb={SumGlobals(compute.GlobalMemoryBuffers)}" +
                $" global_lengths=[{string.Join(',', compute.GlobalMemoryBuffers.Select(static buffer => buffer.Length))}]",
            _ => string.Empty,
        };
    }

    private static ulong GetDrawPayloadBytes(VulkanTranslatedGuestDraw draw)
    {
        var bytes = GetTexturePayloadBytes(draw.Textures);
        bytes = SaturatingAdd(bytes, GetGlobalBufferPayloadBytes(draw.GlobalMemoryBuffers));
        var uniqueVertexData = new HashSet<byte[]>(
            System.Collections.Generic.ReferenceEqualityComparer.Instance);
        foreach (var vertex in draw.VertexBuffers)
        {
            if (uniqueVertexData.Add(vertex.Data))
            {
                bytes = SaturatingAdd(bytes, (ulong)vertex.Data.LongLength);
            }
        }

        if (draw.IndexBuffer is { } index)
        {
            bytes = SaturatingAdd(bytes, (ulong)index.Data.LongLength);
        }

        return bytes;
    }

    private static bool IsLargeArrayBridgeTiledPayloadV74065(
        GuestDrawTexture texture,
        byte[] tiledSource) =>
        !_queueAccountLargeArrayTiledV74065 &&
        texture.ArrayLayers > 1 &&
        tiledSource.LongLength >= V74065LargeArrayBridgeThresholdBytes;

    private static ulong GetLargeArrayBridgeTiledPayloadBytesV74065(
        IReadOnlyList<GuestDrawTexture> textures)
    {
        if (_queueAccountLargeArrayTiledV74065)
        {
            return 0;
        }

        var bytes = 0UL;
        var uniqueArrays = new HashSet<byte[]>(
            System.Collections.Generic.ReferenceEqualityComparer.Instance);

        foreach (var texture in textures)
        {
            if (texture.TiledSource is { Length: > 0 } tiledSource &&
                IsLargeArrayBridgeTiledPayloadV74065(texture, tiledSource) &&
                uniqueArrays.Add(tiledSource))
            {
                bytes = SaturatingAdd(
                    bytes,
                    (ulong)tiledSource.LongLength);
            }
        }

        return bytes;
    }

    private static ulong GetTexturePayloadBytes(
        IReadOnlyList<GuestDrawTexture> textures)
    {
        // [V74.0.44][TILED_PAYLOAD_BACKPRESSURE]
        // Keep counting ordinary TiledSource payloads: that correction prevents
        // many independent 15 MiB snapshots from bypassing the RAM safety
        // valve. V74.0.65 exempts only a large array-view TiledSource already
        // retained by the bounded V74.0.64 AGC bridge cache. Blocking a producer
        // on that shared 320 MiB reference cannot release the allocation and was
        // measured adding hundreds of ms of backpressure per draw.
        var bytes = 0UL;
        var uniqueArrays = new HashSet<byte[]>(
            System.Collections.Generic.ReferenceEqualityComparer.Instance);

        foreach (var texture in textures)
        {
            if (texture.RgbaPixels.Length != 0 &&
                uniqueArrays.Add(texture.RgbaPixels))
            {
                bytes = SaturatingAdd(
                    bytes,
                    (ulong)texture.RgbaPixels.LongLength);
            }

            if (texture.TiledSource is { Length: > 0 } tiledSource &&
                uniqueArrays.Add(tiledSource) &&
                !IsLargeArrayBridgeTiledPayloadV74065(texture, tiledSource))
            {
                bytes = SaturatingAdd(
                    bytes,
                    (ulong)tiledSource.LongLength);
            }
        }

        return bytes;
    }

    private static ulong GetGlobalBufferPayloadBytes(
        IReadOnlyList<GuestMemoryBuffer> buffers)
    {
        var bytes = 0UL;
        foreach (var buffer in buffers)
        {
            bytes = SaturatingAdd(bytes, (ulong)buffer.Data.LongLength);
        }

        return bytes;
    }

    private static ulong SaturatingAdd(ulong left, ulong right) =>
        ulong.MaxValue - left < right ? ulong.MaxValue : left + right;

    private static void ReleasePendingGuestImageUploadsLocked(object work)
    {
        if (work is not VulkanComputeGuestDispatch compute)
        {
            return;
        }

        foreach (var key in GetStorageImageUploadKeys(compute.Textures))
        {
            if (!_pendingGuestImageUploads.TryGetValue(key, out var pendingUpload))
            {
                continue;
            }

            if (pendingUpload.Count <= 1)
            {
                _pendingGuestImageUploads.Remove(key);
            }
            else
            {
                _pendingGuestImageUploads[key] = pendingUpload with
                {
                    Count = pendingUpload.Count - 1,
                };
            }
        }
    }

    private static HashSet<(ulong Address, uint Format)> GetStorageImageUploadKeys(
        IReadOnlyList<GuestDrawTexture> textures)
    {
        var keys = new HashSet<(ulong Address, uint Format)>();
        foreach (var texture in textures)
        {
            if (!texture.IsStorage || texture.Address == 0)
            {
                continue;
            }

            var format = GetGuestTextureFormat(texture.Format, texture.NumberType);
            if (format != 0)
            {
                keys.Add((texture.Address, format));
            }
        }

        return keys;
    }

    internal static bool ShouldAttachGuestDepth(
        GuestDepthTarget? target,
        GuestDepthState state) =>
        target is not null &&
        (state.TestEnable || state.WriteEnable || state.ClearEnable);

    internal static bool RequiresRealFormatConversion(Format from, Format to)
    {
        static bool Is10Bit(Format f) =>
            f is Format.A2R10G10B10UnormPack32 or Format.A2B10G10R10UnormPack32;
        return (from == Format.R8G8B8A8Unorm && Is10Bit(to)) ||
               (Is10Bit(from) && to == Format.R8G8B8A8Unorm);
    }

    private readonly record struct Presentation(
        byte[]? Pixels,
        uint Width,
        uint Height,
        long Sequence,
        GuestDrawKind DrawKind,
        VulkanTranslatedGuestDraw? TranslatedDraw,
        long RequiredGuestWorkSequence,
        bool IsSplash,
        ulong GuestImageAddress = 0,
        long GuestImageVersion = 0,
        bool IsHdr = false);

