                SubmitGuestCommandBuffer(
                    _batchCommandBuffer,
                    _batchResources.ToArray(),
                    _batchTraceImages.ToArray(),
                    _batchRetireBuffers.Count > 0 ? _batchRetireBuffers.ToArray() : [],
                    retireDetile: _batchRetireDetile.Count > 0
                        ? _batchRetireDetile.ToArray()
                        : []);

