                        Interlocked.Increment(
                            ref _v7405620BatchSubmitCount);
                    var submittedWorkV7405620 =
                        Interlocked.Add(
                            ref _v7405620BatchSubmittedWork,
                            batchWorkV7405620);

                    if (submitCountV7405620 <= 128 ||
                        (submitCountV7405620 &
                         (submitCountV7405620 - 1)) == 0)
