        private void CollectAbandonedGuestSubmissions()
        {
            var pending = _abandonedGuestSubmissions.Count;
            for (var i = 0; i < pending; i++)
            {
                if (!_abandonedGuestSubmissions.TryDequeue(out var submission))
                {
                    break;
                }

                var status = _vk.GetFenceStatus(_device, submission.Fence);
                if (status == Result.NotReady && !_deviceLost)
                {
                    _abandonedGuestSubmissions.Enqueue(submission);
                    continue;
                }

                if (status == Result.ErrorDeviceLost)
                {
                    _deviceLost = true;
                }
                else if (status != Result.NotReady && status != Result.Success)
                {
                    Check(status, $"vkGetFenceStatus(abandoned: {submission.DebugName})");
                }

                RetireGuestSubmission(submission);
            }
        }

        private void RetireGuestSubmission(PendingGuestSubmission submission)
        {
            // [V74.0.49][GPU_SUBMISSION_LATENCY]
            // This is host-observed fence-retirement age. It is an upper bound
            // on GPU execution/queue latency because a fence may have signalled
            // shortly before the next host poll, but it directly identifies
            // which real submission occupied the in-flight window for seconds.
            if (_traceGpuSubmissionLatencyV74049 &&
                submission.SubmittedTimestampV74049 != 0)
            {
                var retireAgeMsV74049 =
                    (Stopwatch.GetTimestamp() -
                     submission.SubmittedTimestampV74049) *
                    1000.0 / Stopwatch.Frequency;
                if (retireAgeMsV74049 >=
                    _gpuSubmissionLatencyThresholdMsV74049)
                {
                    var traceV74049 = Interlocked.Increment(
                        ref _v74049GpuSubmissionLatencyTraceCount);
                    if (traceV74049 <= 256 ||
                        (traceV74049 & (traceV74049 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.49][GPU_SUBMISSION_LATENCY] " +
                            $"count={traceV74049} age_ms={retireAgeMsV74049:F3} " +
                            $"timeline={submission.Timeline} " +
                            $"queue={submission.Queue.Name} " +
                            $"submission={submission.Queue.SubmissionId} " +
                            $"work_sequence={submission.WorkSequence} " +
                            $"pending_before_submit={submission.PendingBeforeSubmitV74049} " +
                            $"pending_before_retire={_pendingGuestSubmissions.Count} " +
                            $"work='{submission.DebugName}'");
                    }
                }
            }

            // [V74.0.50][GPU_RETIREMENT_PHASES]
            // The caller has already observed this real Vulkan fence as signalled.
            // Attribute synchronous host retirement cost separately.
            var retireStartV74050 = _traceGpuRetirementPhasesV74050
                ? Stopwatch.GetTimestamp()
                : 0L;

            var traceImageCountV74050 = submission.TraceImages.Count;
            var resourceCountV74050 = submission.Resources.Count;
            var textureCountV74050 = 0;
            var globalCountV74050 = 0;
            var vertexCountV74050 = 0;
            if (_traceGpuRetirementPhasesV74050)
            {
                foreach (var r in submission.Resources)
                {
                    textureCountV74050 += r.Textures.Length;
                    globalCountV74050 += r.GlobalMemoryBuffers.Length;
                    vertexCountV74050 += r.VertexBuffers.Length;
                }
            }

            var traceStartV74050 = Stopwatch.GetTimestamp();
            if (!_deviceLost)
            {
                foreach (var image in submission.TraceImages)
                {
                    TraceGuestImageContents(image);
                }
            }
            var traceEndV74050 = Stopwatch.GetTimestamp();

            foreach (var transients in submission.RetireDetile)
            {
                _detilePass?.Retire(transients);
            }
            var detileEndV74050 = Stopwatch.GetTimestamp();

            foreach (var resources in submission.Resources)
            {
                DestroyTranslatedDrawResources(resources);
            }
            var resourcesEndV74050 = Stopwatch.GetTimestamp();

            foreach (var (buffer, memory) in submission.RetireBuffers)
            {
                _vk.DestroyBuffer(_device, buffer, null);
                _vk.FreeMemory(_device, memory, null);
            }
            var buffersEndV74050 = Stopwatch.GetTimestamp();

            ReleaseGuestCommandBuffer(submission.CommandBuffer);
            ReleaseGuestFence(submission.Fence, needsReset: true);
            var releaseEndV74050 = Stopwatch.GetTimestamp();

            if (submission.Timeline > _completedTimeline)
            {
                _completedTimeline = submission.Timeline;
            }

            if (_traceGpuRetirementPhasesV74050 && retireStartV74050 != 0)
            {
                var tickToMsV74050 = 1000.0 / Stopwatch.Frequency;
                var traceMsV74050 = (traceEndV74050 - traceStartV74050) * tickToMsV74050;
                var detileMsV74050 = (detileEndV74050 - traceEndV74050) * tickToMsV74050;
                var resourcesMsV74050 = (resourcesEndV74050 - detileEndV74050) * tickToMsV74050;
                var buffersMsV74050 = (buffersEndV74050 - resourcesEndV74050) * tickToMsV74050;
                var releaseMsV74050 = (releaseEndV74050 - buffersEndV74050) * tickToMsV74050;
                var totalMsV74050 = (releaseEndV74050 - retireStartV74050) * tickToMsV74050;

                if (totalMsV74050 >= _gpuRetirementPhaseThresholdMsV74050)
                {
                    var traceCountV74050 = Interlocked.Increment(ref _v74050GpuRetirementTraceCount);
                    if (traceCountV74050 <= 512 ||
                        (traceCountV74050 & (traceCountV74050 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.50][GPU_RETIREMENT_PHASES] " +
                            $"count={traceCountV74050} total_ms={totalMsV74050:F3} " +
                            $"trace_ms={traceMsV74050:F3} detile_ms={detileMsV74050:F3} " +
                            $"resources_ms={resourcesMsV74050:F3} buffers_ms={buffersMsV74050:F3} " +
                            $"release_ms={releaseMsV74050:F3} timeline={submission.Timeline} " +
                            $"queue={submission.Queue.Name} submission={submission.Queue.SubmissionId} " +
                            $"trace_images={traceImageCountV74050} resources={resourceCountV74050} " +
                            $"textures={textureCountV74050} globals={globalCountV74050} vertices={vertexCountV74050} " +
                            $"retire_buffers={submission.RetireBuffers.Count} retire_detile={submission.RetireDetile.Count} " +
                            $"work='{submission.DebugName}'");
                    }
                }
            }
        }

        private void WaitForAllGuestSubmissionsForCpuVisibility()
        {
            FlushBatchedGuestCommands();
            while (_pendingGuestSubmissions.Count != 0)
            {
                var before = _pendingGuestSubmissions.Count;
                CollectCompletedGuestSubmissions(waitForOldest: true);
                if (_deviceLost)
                {
                    return;
                }
                if (_pendingGuestSubmissions.Count == before &&
                    _pendingGuestSubmissions.TryPeek(out var oldest))
                {
                    Console.Error.WriteLine(
                        $"[LOADER][WARN] vk.cpu_visibility_timeout " +
                        $"submission='{oldest.DebugName}' pending={before}; " +
                        "continuing without an infinite host wait.");
                    return;
                }
            }
        }

        private void WaitForGuestSubmissionCompletion(
            ulong targetTimeline,
            string reason)
        {
            if (targetTimeline == 0 || targetTimeline <= _completedTimeline)
            {
                return;
            }

            PendingGuestSubmission? target = null;
            foreach (var submission in _pendingGuestSubmissions)
            {
                if (submission.Timeline == targetTimeline)
                {
                    target = submission;
                    break;
                }
            }

            if (target is null)
            {
                throw new InvalidOperationException(
                    $"Guest submission timeline {targetTimeline} disappeared before " +
                    $"{reason} (completed={_completedTimeline}).");
            }

            var fence = target.Fence;
            var waitStartV74049 = _traceGpuSubmissionLatencyV74049
                ? Stopwatch.GetTimestamp()
                : 0L;
            var ageBeforeWaitMsV74049 =
                _traceGpuSubmissionLatencyV74049 &&
                target.SubmittedTimestampV74049 != 0
                    ? (Stopwatch.GetTimestamp() -
                       target.SubmittedTimestampV74049) *
                      1000.0 / Stopwatch.Frequency
                    : 0.0;
            var pendingBeforeWaitV74049 = _pendingGuestSubmissions.Count;

            var waitResult = _vk.WaitForFences(
                _device,
                1,
                &fence,
                true,
                ulong.MaxValue);

            if (_traceGpuSubmissionLatencyV74049 &&
                waitStartV74049 != 0)
            {
                var waitMsV74049 =
                    (Stopwatch.GetTimestamp() - waitStartV74049) *
                    1000.0 / Stopwatch.Frequency;
                if (waitMsV74049 >= 1.0 ||
                    ageBeforeWaitMsV74049 >=
                    _gpuSubmissionLatencyThresholdMsV74049)
                {
                    var traceV74049 = Interlocked.Increment(
                        ref _v74049GpuVisibilityWaitTraceCount);
                    if (traceV74049 <= 256 ||
                        (traceV74049 & (traceV74049 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.49][GPU_VISIBILITY_WAIT] " +
                            $"count={traceV74049} wait_ms={waitMsV74049:F3} " +
                            $"age_before_ms={ageBeforeWaitMsV74049:F3} " +
                            $"timeline={target.Timeline} " +
                            $"completed={_completedTimeline} " +
                            $"pending={pendingBeforeWaitV74049} " +
                            $"queue={target.Queue.Name} " +
                            $"submission={target.Queue.SubmissionId} " +
                            $"work_sequence={target.WorkSequence} " +
                            $"reason='{reason}' " +
                            $"work='{target.DebugName}'");
                    }
                }
            }

            if (waitResult == Result.ErrorDeviceLost)
            {
                _deviceLost = true;
                return;
            }

            Check(
                waitResult,
                $"vkWaitForFences({reason}, timeline={targetTimeline})");
            CollectCompletedGuestSubmissions(waitForOldest: false);
        }

        private bool TryMakeActiveGuestQueueSubmissionsCpuVisible()
        {
            FlushBatchedGuestCommands();
            if (!_lastSubmittedTimelineByGuestQueue.TryGetValue(
                    _activeGuestQueue.Name,
                    out var targetTimeline) ||
                targetTimeline <= _completedTimeline)
            {
                _v74042VisibilityBlockedUntilTimeline.Remove(
                    _activeGuestQueue.Name);
                return true;
            }

            PendingGuestSubmission? target = null;
            foreach (var submission in _pendingGuestSubmissions)
            {
                if (submission.Timeline == targetTimeline)
                {
                    target = submission;
                    break;
                }
            }

            if (target is null)
            {
                throw new InvalidOperationException(
                    $"Guest queue '{_activeGuestQueue.Name}' lost pending timeline " +
                    $"{targetTimeline} (completed={_completedTimeline}).");
            }

            var fence = target.Fence;
            var status = _vk.GetFenceStatus(_device, fence);
            if (status == Result.NotReady)
            {
                if (_nonBlockingOrderedVisibilityV740293)
                {
                    var deferredCount = Interlocked.Increment(
                        ref _v740293OrderedVisibilityDeferredCount);
                    if (deferredCount <= 128 ||
                        (deferredCount & (deferredCount - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.29.3][ORDERED_VISIBILITY_DEFER] " +
                            $"count={deferredCount} queue={_activeGuestQueue.Name} " +
                            $"submission={_activeGuestQueue.SubmissionId} " +
                            $"target_timeline={targetTimeline} " +
                            $"completed_timeline={_completedTimeline} " +
                            $"pending_gpu={_pendingGuestSubmissions.Count} " +
                            $"work='{target.DebugName}'");
                    }

                    // Exact semantics: do not execute the ordered side effect.
                    // Requeue it at the front and let sibling logical queues or
                    // the present path run while Vulkan finishes naturally.
                    // V74.0.42 additionally persists the queue block across
                    // RenderCore ticks until this exact Vulkan timeline retires.
                    // V41.1 otherwise retried the same not-ready head hundreds
                    // of thousands of times, burning CPU without guest progress.
                    _v74042VisibilityBlockedUntilTimeline[
                        _activeGuestQueue.Name] = targetTimeline;
                    var blockCount = Interlocked.Increment(
                        ref _v74042VisibilityQueueBlockTraceCount);
                    if (blockCount <= 64 ||
                        (blockCount & (blockCount - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.42][QUEUE_TIMELINE_BLOCK] " +
                            $"count={blockCount} queue={_activeGuestQueue.Name} " +
                            $"target_timeline={targetTimeline} " +
                            $"completed_timeline={_completedTimeline}");
                    }

                    return false;
                }

                // Legacy bounded probe retained as an A/B fallback.
                if (OperatingSystem.IsMacOS())
                {
                    return false;
                }

                const ulong orderedVisibilityProbeNs = 2_000_000UL; // 2ms
                var waitResult = _vk.WaitForFences(
                    _device,
                    1,
                    &fence,
                    true,
                    orderedVisibilityProbeNs);
                if (waitResult == Result.Timeout)
                {
                    return false;
                }

                if (waitResult == Result.ErrorDeviceLost)
                {
                    _deviceLost = true;
                    return true;
                }

                Check(
                    waitResult,
                    $"vkWaitForFences(queue visibility: {_activeGuestQueue.Name})");
                var waitTrace = Interlocked.Increment(ref _orderedActionFenceWaitTraceCount);
                if (waitTrace <= 8 || (waitTrace & (waitTrace - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.ordered_action_fence_wait " +
                        $"count={waitTrace} queue={_activeGuestQueue.Name} " +
                        $"submission='{target.DebugName}'");
                }

                CollectCompletedGuestSubmissions(waitForOldest: false);
                if (_traceVulkanShaderEnabled)
                {
                    TraceVulkanShader(
                        $"vk.queue_visibility queue={_activeGuestQueue.Name} " +
                        $"submission={_activeGuestQueue.SubmissionId} " +
                        $"target_timeline={targetTimeline} " +
                        $"completed_timeline={_completedTimeline} waited=1");
                }

                return true;
            }

            if (status == Result.ErrorDeviceLost)
            {
                _deviceLost = true;
                return true;
            }

            Check(status, $"vkGetFenceStatus(queue visibility: {_activeGuestQueue.Name})");
            _v74042VisibilityBlockedUntilTimeline.Remove(
                _activeGuestQueue.Name);
            CollectCompletedGuestSubmissions(waitForOldest: false);
            if (_traceVulkanShaderEnabled)
            {
                TraceVulkanShader(
                    $"vk.queue_visibility queue={_activeGuestQueue.Name} " +
                    $"submission={_activeGuestQueue.SubmissionId} " +
                    $"target_timeline={targetTimeline} completed_timeline={_completedTimeline}");
            }

            return true;
        }

        // [V74.0.51][NONBLOCKING_GLOBAL_REFRESH]
        private bool TryPrepareWritableGlobalRefreshV74051(
            IReadOnlyList<GuestMemoryBuffer> buffers)
        {
            if (!_nonblockingGlobalRefreshV74051 || buffers.Count == 0)
            {
                return true;
            }

            // Retire anything which is already signalled before deciding that a
            // mapped allocation is genuinely still busy.
            CollectCompletedGuestSubmissions(waitForOldest: false);

            ulong targetTimelineV74051 = 0;
            ulong blockedBaseV74051 = 0;
            int blockedBytesV74051 = 0;
            string blockedWorkV74051 = string.Empty;

            foreach (var guestBuffer in buffers)
            {
                if (guestBuffer.BaseAddress == 0 ||
                    !guestBuffer.Writable ||
                    guestBuffer.Length < 0)
                {
                    continue;
                }

                var sizeV74051 =
                    (ulong)Math.Max(guestBuffer.Length, sizeof(uint));
                if (guestBuffer.BaseAddress >
                    ulong.MaxValue - sizeV74051)
                {
                    continue;
                }

                var endV74051 = guestBuffer.BaseAddress + sizeV74051;
                GuestBufferAllocation? allocationV74051 = null;
                foreach (var candidateV74051 in _guestBufferAllocations)
                {
                    if (candidateV74051.BaseAddress >
                            guestBuffer.BaseAddress ||
                        candidateV74051.BaseAddress +
                            candidateV74051.Size < endV74051)
                    {
                        continue;
                    }

                    allocationV74051 = candidateV74051;
                    break;
                }

                if (allocationV74051 is null ||
                    allocationV74051.LastUseTimeline <=
                        _completedTimeline)
                {
                    continue;
                }

                var guestOffsetV74051 =
                    guestBuffer.BaseAddress -
                    allocationV74051.BaseAddress;
                if (guestOffsetV74051 > int.MaxValue ||
                    guestOffsetV74051 +
                        (ulong)guestBuffer.Length >
                    (ulong)allocationV74051.Shadow.Length)
                {
                    continue;
                }

                var sourceV74051 =
                    guestBuffer.Data.AsSpan(
                        0,
                        guestBuffer.Length);
                var shadowV74051 =
                    allocationV74051.Shadow.AsSpan(
                        checked((int)guestOffsetV74051),
                        guestBuffer.Length);

                var needsRefreshV74051 =
                    !sourceV74051.SequenceEqual(shadowV74051);

                if (!needsRefreshV74051 &&
                    _guestMemory is not null &&
                    guestBuffer.Length > 0)
                {
                    var liveV74051 =
                        GuestDataPool.Shared.Rent(
                            guestBuffer.Length);
                    try
                    {
                        var liveSpanV74051 =
                            liveV74051.AsSpan(
                                0,
                                guestBuffer.Length);
                        if (_guestMemory.TryRead(
                                guestBuffer.BaseAddress,
                                liveSpanV74051) &&
                            !liveSpanV74051.SequenceEqual(
                                shadowV74051))
                        {
                            needsRefreshV74051 = true;
                        }
                    }
                    finally
                    {
                        GuestDataPool.Shared.Return(
                            liveV74051);
                    }
                }

                if (!needsRefreshV74051)
                {
                    continue;
                }

                // SHARPEMU_V74_0_56_20_OPEN_BATCH_REFRESH_FLUSH
                // Removing RenderCore's unconditional per-payload flush must
                // not allow the host to rewrite a persistently mapped writable
                // allocation while an earlier command in the OPEN batch still
                // references it. Flush only this proven conflict. The normal
                // LastUseTimeline path below then defers until that exact fence
                // retires. Unchanged/read-only payloads keep batching.
                if (_preservePayloadBatchV7405620 &&
                    allocationV74051 is not null &&
                    IsGuestBufferAllocationReferencedByOpenBatch(
                        allocationV74051))
                {
                    FlushBatchedGuestCommands();
                    CollectCompletedGuestSubmissions(
                        waitForOldest: false);

                    var refreshFlushCountV7405620 =
                        Interlocked.Increment(
                            ref _v7405620OpenBatchRefreshFlushCount);
                    if (refreshFlushCountV7405620 <= 64 ||
                        (refreshFlushCountV7405620 &
                         (refreshFlushCountV7405620 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.56.20][OPEN_BATCH_REFRESH_FLUSH] " +
                            $"count={refreshFlushCountV7405620} " +
                            $"queue={_activeGuestQueue.Name} " +
                            $"base=0x{guestBuffer.BaseAddress:X16} " +
                            $"bytes={guestBuffer.Length} " +
                            $"timeline={allocationV74051.LastUseTimeline}");
                    }
                }

                // Only defer for a real still-pending submission. If the
                // timeline is no longer represented in the pending queue,
                // preserve the existing fallback semantics.
                PendingGuestSubmission? pendingTargetV74051 = null;
                foreach (var pendingV74051 in
                         _pendingGuestSubmissions)
                {
                    if (pendingV74051.Timeline ==
                        allocationV74051.LastUseTimeline)
                    {
                        pendingTargetV74051 = pendingV74051;
                        break;
                    }
                }

                if (pendingTargetV74051 is null)
                {
                    continue;
                }

                if (allocationV74051.LastUseTimeline >
                    targetTimelineV74051)
                {
                    targetTimelineV74051 =
                        allocationV74051.LastUseTimeline;
                    blockedBaseV74051 =
                        guestBuffer.BaseAddress;
                    blockedBytesV74051 =
                        guestBuffer.Length;
                    blockedWorkV74051 =
                        pendingTargetV74051.DebugName;
                }
            }

            if (targetTimelineV74051 == 0)
            {
                return true;
            }

            _v74042VisibilityBlockedUntilTimeline[
                _activeGuestQueue.Name] =
                targetTimelineV74051;

            var traceV74051 = Interlocked.Increment(
                ref _v74051GlobalRefreshDeferTraceCount);
            if (traceV74051 <= 256 ||
                (traceV74051 &
                 (traceV74051 - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V74.0.51][GLOBAL_BUFFER_REFRESH_DEFER] " +
                    $"count={traceV74051} " +
                    $"queue={_activeGuestQueue.Name} " +
                    $"submission={_activeGuestQueue.SubmissionId} " +
                    $"target_timeline={targetTimelineV74051} " +
                    $"completed={_completedTimeline} " +
                    $"pending_gpu={_pendingGuestSubmissions.Count} " +
                    $"base=0x{blockedBaseV74051:X16} " +
                    $"bytes={blockedBytesV74051} " +
                    $"producer='{blockedWorkV74051}'");
            }

            return false;
        }

        private void WaitForGuestBufferAllocationForCpuVisibility(
            GuestBufferAllocation allocation)
        {
            if (IsGuestBufferAllocationReferencedByOpenBatch(allocation))
            {
                FlushBatchedGuestCommands();
            }

            var targetTimeline = allocation.LastUseTimeline;
            if (targetTimeline <= _completedTimeline)
            {
                return;
            }

            PendingGuestSubmission? target = null;
            foreach (var submission in _pendingGuestSubmissions)
            {
                if (submission.Timeline == targetTimeline)
                {
                    target = submission;
                    break;
                }
            }

            if (target is null)
            {
                return;
            }

            var fence = target.Fence;
            var result = _vk.WaitForFences(
                _device,
                1,
                &fence,
                true,
                _guestFenceWaitTimeoutNs);

            if (result == Result.Timeout)
            {
                Console.Error.WriteLine(
                    $"[LOADER][WARN] vk.buffer_visibility_timeout " +
                    $"base=0x{allocation.BaseAddress:X16} timeline={targetTimeline} " +
                    $"submission='{target.DebugName}'; avoiding infinite host wait.");
                return;
            }
            if (result == Result.ErrorDeviceLost)
            {
                _deviceLost = true;
                return;
            }

            Check(
                result,
                $"vkWaitForFences(buffer visibility: 0x{allocation.BaseAddress:X16})");
            CollectCompletedGuestSubmissions(waitForOldest: false);
        }
        private bool TryExecuteGlobalOrderedGuestAction(VulkanGlobalOrderedGuestAction work)
        {
            // Logical dependency is global; now make every prior Vulkan submission CPU-visible.
            WaitForAllGuestSubmissionsForCpuVisibility();
            WriteBackAllDirtyGuestBuffers();
            work.Action();
            RenderPhaseProfile.RecordOrderedAction(work.DebugName, completed: true);
            if (_traceVulkanShaderEnabled)
            {
                TraceVulkanShader(
                    $"vk.global_ordered_action work_sequence={_activeGuestWorkSequence} " +
                    $"name='{work.DebugName}'");
            }

            return true;
        }


        private bool TryExecuteOrderedGuestAction(VulkanOrderedGuestAction work)
        {
            // RootFix V17.1: EVENT_WRITE without a guest-memory payload only
            // triggers an HLE event notification. It remains ordered in the
            // guest-work queue, but does not require all prior Vulkan compute
            // submissions to become CPU-visible before the notification fires.
            //
            // Memory-bearing actions retain the full visibility path:
            // WRITE_DATA, RELEASE_MEM, DMA_DATA, ACQUIRE_MEM and the V15.1
            // global shader-resource synchronization.
            var hostEventOnly =
                !work.RequireGlobalVisibility &&
                work.DebugName.StartsWith(
                    "event_write type=",
                    StringComparison.Ordinal);

            // SHARPEMU_V74_0_56_17_DISABLED_ACQUIRE_NOFLUSH
            // Preserve the ordered action itself, but when the CPU image-write
            // tracker is disabled its ApplyAcquire body has no GPU-visible work.
            // In that exact state a batch flush is pure submission fragmentation.
            var disabledAcquireNoFlushV7405617 =
                _disabledAcquireNoFlushV7405617 &&
                !SharpEmu.HLE.GuestImageWriteTracker.Enabled &&
                !work.RequireGlobalVisibility &&
                !work.RequiresGpuToCpuVisibility &&
                !work.RequiresQueueCompletionOnly &&
                work.DebugName.StartsWith(
                    "acquire_mem_flush ",
                    StringComparison.Ordinal);

            var hostOnlyNoFlushV7405617 =
                hostEventOnly || disabledAcquireNoFlushV7405617;

            if (work.RequireGlobalVisibility)
            {
                WaitForAllGuestSubmissionsForCpuVisibility();
                WriteBackAllDirtyGuestBuffers();
            }
            else if (!hostOnlyNoFlushV7405617)
            {
                                // V28.0.3: CPU->GPU ordered actions avoid global GPU readback.
                if (work.RequiresGpuToCpuVisibility)
                {
                    if (!TryMakeActiveGuestQueueSubmissionsCpuVisible())
                                    {
                                        RenderPhaseProfile.RecordOrderedAction(work.DebugName, completed: false);
                                        return false;
                                    }
                    WriteBackAllDirtyGuestBuffers(_activeGuestQueue.Name);
                }
                else if (work.RequiresQueueCompletionOnly)
                {
                    // V73.5: preserve the PM4 position in this logical queue.
                    // The immediate packet payload is already CPU-resident, so
                    // completed shader/storage buffers do not need readback.
                    if (!TryMakeActiveGuestQueueSubmissionsCpuVisible())
                    {
                        RenderPhaseProfile.RecordOrderedAction(work.DebugName, completed: false);
                        return false;
                    }
                }
                else
                {
                    // Submit prior commands to preserve logical queue order, but do not
                    // wait for host visibility or scan unrelated dirty storage buffers.
                    FlushBatchedGuestCommands();
                }
            }
            else
            {
                if (disabledAcquireNoFlushV7405617)
                {
                    var noFlushCountV7405617 =
                        Interlocked.Increment(
                            ref _v7405617DisabledAcquireNoFlushTraceCount);
                    if (noFlushCountV7405617 <= 128 ||
                        (noFlushCountV7405617 &
                         (noFlushCountV7405617 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.56.17][ACQUIRE_NOFLUSH] " +
                            $"count={noFlushCountV7405617} " +
                            $"queue={_activeGuestQueue.Name} " +
                            $"submission={_activeGuestQueue.SubmissionId} " +
                            $"work_sequence={_activeGuestWorkSequence} " +
                            $"name='{work.DebugName}'");
                    }
                }
                else
                {
                    var fastPath =
                        Interlocked.Increment(
                            ref _v17OrderedEventFastPaths);
                    if (fastPath <= 16 ||
                        (fastPath & (fastPath - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V17][EVENT_FASTPATH] n={fastPath} " +
                            $"queue={_activeGuestQueue.Name} " +
                            $"submission={_activeGuestQueue.SubmissionId} " +
                            $"work_sequence={_activeGuestWorkSequence} " +
                            $"name='{work.DebugName}'");
                    }
                }
            }

            work.Action();
            RenderPhaseProfile.RecordOrderedAction(work.DebugName, completed: true);
            if (_traceVulkanShaderEnabled)
            {
                TraceVulkanShader(
                    $"vk.ordered_action queue={_activeGuestQueue.Name} " +
                    $"submission={_activeGuestQueue.SubmissionId} " +
                    $"work_sequence={_activeGuestWorkSequence} name='{work.DebugName}'");
            }

            return true;
        }

        private void ExecuteOrderedGuestFlip(VulkanOrderedGuestFlip work)
        {
            FlushBatchedGuestCommands();
            _guestImages.TryGetValue(work.Address, out var source);
            if (_deviceLost ||
                source is null ||
                !source.Initialized)
            {
                Console.Error.WriteLine(
                    $"[LOADER][WARN] vk.flip_capture_failed version={work.Version} " +
                    $"queue={_activeGuestQueue.Name} addr=0x{work.Address:X16} " +
                    $"found={(source is not null)} initialized={(source?.Initialized ?? false)}");
                return;
            }

            GetGuestImageSourceSync(
                source,
                out var sourceStage,
                out var sourceAccess);
            var sourceLayout = source.Layout;
            EnsureGuestSubmissionCapacity();            var snapshot = CreateGuestFlipSnapshot(source, work.Version);
            var commandBuffer = AllocateGuestCommandBuffer();
            var submitted = false;
            try
            {
                var beginInfo = new CommandBufferBeginInfo
                {
                    SType = StructureType.CommandBufferBeginInfo,
                    Flags = CommandBufferUsageFlags.OneTimeSubmitBit,
                };
                Check(
                    _vk.BeginCommandBuffer(commandBuffer, &beginInfo),
                    "vkBeginCommandBuffer(flip capture)");

                var barriers = stackalloc ImageMemoryBarrier[2];
                barriers[0] = new ImageMemoryBarrier
                {
                    SType = StructureType.ImageMemoryBarrier,
                    SrcAccessMask = sourceAccess,
                    DstAccessMask = AccessFlags.TransferReadBit,
                    OldLayout = sourceLayout,
                    NewLayout = ImageLayout.TransferSrcOptimal,
                    SrcQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    DstQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    Image = source.Image,
                    SubresourceRange = ColorSubresourceRange(),
                };
                barriers[1] = new ImageMemoryBarrier
                {
                    SType = StructureType.ImageMemoryBarrier,
                    SrcAccessMask = 0,
                    DstAccessMask = AccessFlags.TransferWriteBit,
                    OldLayout = ImageLayout.Undefined,
                    NewLayout = ImageLayout.TransferDstOptimal,
                    SrcQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    DstQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    Image = snapshot.Image,
                    SubresourceRange = ColorSubresourceRange(),
                };
                _vk.CmdPipelineBarrier(
                    commandBuffer,
                    sourceStage,
                    PipelineStageFlags.TransferBit,
                    0,
                    0,
                    null,
                    0,
                    null,
                    2,
                    barriers);

                var copy = new ImageCopy
                {
                    SrcSubresource = new ImageSubresourceLayers(
                        ImageAspectFlags.ColorBit, 0, 0, 1),
                    DstSubresource = new ImageSubresourceLayers(
                        ImageAspectFlags.ColorBit, 0, 0, 1),
                    Extent = new Extent3D(source.Width, source.Height, 1),
                };
                _vk.CmdCopyImage(
                    commandBuffer,
                    source.Image,
                    ImageLayout.TransferSrcOptimal,
                    snapshot.Image,
                    ImageLayout.TransferDstOptimal,
                    1,
                    &copy);

                barriers[0] = new ImageMemoryBarrier
                {
                    SType = StructureType.ImageMemoryBarrier,
                    SrcAccessMask = AccessFlags.TransferReadBit,
                    DstAccessMask = sourceAccess,
                    OldLayout = ImageLayout.TransferSrcOptimal,
                    NewLayout = sourceLayout,
                    SrcQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    DstQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    Image = source.Image,
                    SubresourceRange = ColorSubresourceRange(),
                };
                barriers[1] = new ImageMemoryBarrier
                {
                    SType = StructureType.ImageMemoryBarrier,
                    SrcAccessMask = AccessFlags.TransferWriteBit,
                    DstAccessMask = AccessFlags.ShaderReadBit,
                    OldLayout = ImageLayout.TransferDstOptimal,
                    NewLayout = ImageLayout.ShaderReadOnlyOptimal,
                    SrcQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    DstQueueFamilyIndex = Vk.QueueFamilyIgnored,
                    Image = snapshot.Image,
                    SubresourceRange = ColorSubresourceRange(),
                };
                _vk.CmdPipelineBarrier(
                    commandBuffer,
                    PipelineStageFlags.TransferBit,
                    sourceStage,
                    0,
                    0,
                    null,
                    0,
                    null,
                    2,
                    barriers);

                Check(
                    _vk.EndCommandBuffer(commandBuffer),
                    "vkEndCommandBuffer(flip capture)");
                SubmitGuestCommandBuffer(commandBuffer, [], []);
                submitted = true;

                // Do not publish the snapshot to the presentation thread until
                // its copy has completed.  Without this hand-off the renderer
                // can consume a flip snapshot while the GPU is still copying
                // the final render target into it.  Diagnostic AGC logging
                // accidentally hid that race by slowing the producer down,
                // which is why SHARPEMU_LOG_AGC=1 appeared to "fix" centering.
                var flipCaptureTimeline = _submitTimeline;
                WaitForGuestSubmissionCompletion(
                    flipCaptureTimeline,
                    $"flip capture version={work.Version}");

                if (_deviceLost)
                {
                    return;
                }

                snapshot.Initialized = true;
                snapshot.Layout = ImageLayout.ShaderReadOnlyOptimal;
                _guestImageVersions.Add(work.Version, snapshot);
                _capturedGuestFlipVersions.Add(work.Version);
                _completedGuestFlipCaptures.Add(work.Version);

                lock (_gate)
                {
                    var sequence = (_latestPresentation?.Sequence ?? 0) + 1;
                    var isHdr =
                        VideoOutExports.TryGetDisplayBufferInfo(
                            work.VideoOutHandle,
                            work.DisplayBufferIndex,
                            out var displayBuffer) &&
                        VideoOutExports.IsHdrPixelFormat(displayBuffer.PixelFormat);
                    var presentation = new Presentation(
                        null,
                        work.Width,
                        work.Height,
                        sequence,
                        GuestDrawKind.None,
                        TranslatedDraw: null,
                        RequiredGuestWorkSequence: _activeGuestWorkSequence,
                        IsSplash: false,
                        GuestImageAddress: work.Address,
                        GuestImageVersion: work.Version,
                        IsHdr: isHdr);
                    _latestPresentation = presentation;
                    _pendingGuestImagePresentations.Enqueue(presentation);
                    while (_pendingGuestImagePresentations.Count > MaxPendingGuestFlipVersions)
                    {
                        _pendingGuestImagePresentations.Dequeue();
                    }
                }

                CollectAbandonedGuestImageVersions();

                var effectivePitch = work.PitchInPixel == 0
                    ? work.Width
                    : work.PitchInPixel;
                TraceVulkanShader(
                    $"vk.flip_capture version={work.Version} " +
                    $"queue={_activeGuestQueue.Name} submission={_activeGuestQueue.SubmissionId} " +
                    $"work_sequence={_activeGuestWorkSequence} addr=0x{work.Address:X16} " +
                    $"size={work.Width}x{work.Height} pitch={effectivePitch}");
            }
            finally
            {
                if (!submitted)
                {
                    ReleaseGuestCommandBuffer(commandBuffer);
                    DestroyGuestImage(snapshot);
                }
            }
        }

        private void ExecuteOrderedGuestFlipWait(VulkanOrderedGuestFlipWait work)
        {
            var captured = work.Version == 0 ||
                _completedGuestFlipCaptures.Contains(work.Version);
            TraceVulkanShader(
                $"vk.flip_wait_safe version={work.Version} " +
                $"queue={_activeGuestQueue.Name} submission={_activeGuestQueue.SubmissionId} " +
                $"handle={work.VideoOutHandle} index={work.DisplayBufferIndex} " +
                $"capture_complete={(captured ? 1 : 0)}");

            if (!captured && !_loggedFlipWaitOrderViolation)
            {
                _loggedFlipWaitOrderViolation = true;
                Console.Error.WriteLine(
                    $"[LOADER][WARN] vk.flip_wait_order version={work.Version} " +
                    "reached without a completed framebuffer capture.");
            }

            if (work.Version != 0)
            {
                _completedGuestFlipCaptures.Remove(work.Version);
                lock (_gate)
                {
                    _orderedGuestFlipWorkSequences.Remove(work.Version);
                }
            }
        }

        private bool _loggedFlipWaitOrderViolation;

        private GuestImageResource CreateGuestFlipSnapshot(
            GuestImageResource source,
            long version)
        {
            var imageInfo = new ImageCreateInfo
            {
                SType = StructureType.ImageCreateInfo,
                ImageType = ImageType.Type2D,
                Format = source.Format,
                Extent = new Extent3D(source.Width, source.Height, 1),
                MipLevels = 1,
                ArrayLayers = 1,
                Samples = SampleCountFlags.Count1Bit,
                Tiling = ImageTiling.Optimal,
                Usage = ImageUsageFlags.TransferSrcBit |
                        ImageUsageFlags.TransferDstBit |
                        ImageUsageFlags.SampledBit,
                SharingMode = SharingMode.Exclusive,
                InitialLayout = ImageLayout.Undefined,
            };
            Check(
                _vk.CreateImage(_device, &imageInfo, null, out var image),
                "vkCreateImage(flip snapshot)");
            _vk.GetImageMemoryRequirements(_device, image, out var requirements);
            var allocationInfo = new MemoryAllocateInfo
            {
                SType = StructureType.MemoryAllocateInfo,
                AllocationSize = requirements.Size,
                MemoryTypeIndex = FindMemoryType(
                    requirements.MemoryTypeBits,
                    MemoryPropertyFlags.DeviceLocalBit),
            };
            DeviceMemory memory = default;
            try
            {
                Check(
                    _vk.AllocateMemory(_device, &allocationInfo, null, out memory),
                    "vkAllocateMemory(flip snapshot)");
                Check(
                    _vk.BindImageMemory(_device, image, memory, 0),
                    "vkBindImageMemory(flip snapshot)");
            }
            catch
            {
                if (memory.Handle != 0)
                {
                    _vk.FreeMemory(_device, memory, null);
                }
                _vk.DestroyImage(_device, image, null);
                throw;
            }

            SetDebugName(
                ObjectType.Image,
                image.Handle,
                $"guest flip v{version} source 0x{source.Address:X16}");
            return new GuestImageResource
            {
                Address = source.Address,
                FlipVersion = version,
                Width = source.Width,
                Height = source.Height,
                LogicalWidth = source.LogicalWidth,
                LogicalHeight = source.LogicalHeight,
                MipLevels = 1,
                GuestFormat = source.GuestFormat,
                Format = source.Format,
                Image = image,
                Memory = memory,
            };
        }

        private static byte[]? TryReadGuestTexturePixels(GuestDrawTexture texture)
        {
            var memory = _guestMemory;
            if (memory is null || texture.Address == 0)
            {
                return null;
            }

            var width = Math.Max(texture.Width, 1);
            var height = Math.Max(texture.Height, 1);
            var rowLength = texture.TileMode == 0
                ? Math.Max(texture.Pitch, width)
                : width;
            var depth = GetGuestTextureDepth(texture.Type, texture.Depth);
            var byteCount = GetTextureByteCount(texture.Format, rowLength, height, depth);
            if (byteCount == 0 || byteCount > int.MaxValue)
            {
                return null;
            }

            var pixels = new byte[(int)byteCount];
            return TryReadGuestTextureBacking(
                    memory,
                    texture.Address,
                    pixels)
                ? pixels
                : null;
        }

        /// <summary>
        /// Returns a skipped draw's pooled data arrays: draws dropped before
        /// resource creation would otherwise strand their rented buffers.
        /// </summary>
        private static void ReturnPooledGuestData(VulkanTranslatedGuestDraw draw)
        {
            var returned = new HashSet<byte[]>(
                System.Collections.Generic.ReferenceEqualityComparer.Instance);
            foreach (var buffer in draw.GlobalMemoryBuffers)
            {
                if (buffer.Pooled && returned.Add(buffer.Data))
                {
                    GuestDataPool.Shared.Return(buffer.Data);
                }
            }

            foreach (var buffer in draw.VertexBuffers)
            {
                if (buffer.Pooled && returned.Add(buffer.Data))
                {
                    GuestDataPool.Shared.Return(buffer.Data);
                }
            }

            if (draw.IndexBuffer is { Pooled: true } indexBuffer &&
                returned.Add(indexBuffer.Data))
            {
                GuestDataPool.Shared.Return(indexBuffer.Data);
            }
        }

        private void ProcessDeferredTextureDestroys()
        {
            var deferredStartV74050 = _traceGpuRetirementPhasesV74050
                ? Stopwatch.GetTimestamp()
                : 0L;
            var textureCountV74050 = 0;
            var resourceCountV74050 = 0;
            var imageCountV74050 = 0;

            while (_deferredTextureDestroys.TryPeek(out var entry) &&
                   entry.RetireTimeline <= _completedTimeline)
            {
                _deferredTextureDestroys.Dequeue();
                DestroyCachedTextureResource(entry.Texture);
                textureCountV74050++;
            }
            var textureEndV74050 = Stopwatch.GetTimestamp();

            while (_deferredResourceDestroys.TryPeek(out var resourceEntry) &&
                   resourceEntry.RetireTimeline <= _completedTimeline)
            {
                _deferredResourceDestroys.Dequeue();
                DestroyTranslatedDrawResources(resourceEntry.Resources);
                resourceCountV74050++;
            }
            var resourceEndV74050 = Stopwatch.GetTimestamp();

            while (_deferredGuestImageVersionDestroys.TryPeek(out var imageEntry) &&
                   imageEntry.RetireTimeline <= _completedTimeline)
            {
                _deferredGuestImageVersionDestroys.Dequeue();
                DestroyGuestImage(imageEntry.Image);
                FlipProgressTracker.RecordFlip(imageEntry.Image.FlipVersion);
                TraceVulkanShader(
                    $"vk.flip_retired version={imageEntry.Image.FlipVersion} " +
                    $"timeline={imageEntry.RetireTimeline} reason=presentation-dropped");
                imageCountV74050++;
            }
            var imageEndV74050 = Stopwatch.GetTimestamp();

            if (_traceGpuRetirementPhasesV74050 && deferredStartV74050 != 0)
            {
                var tickToMsV74050 = 1000.0 / Stopwatch.Frequency;
                var textureMsV74050 = (textureEndV74050 - deferredStartV74050) * tickToMsV74050;
                var resourceMsV74050 = (resourceEndV74050 - textureEndV74050) * tickToMsV74050;
                var imageMsV74050 = (imageEndV74050 - resourceEndV74050) * tickToMsV74050;
                var totalMsV74050 = (imageEndV74050 - deferredStartV74050) * tickToMsV74050;

                if (totalMsV74050 >= _gpuRetirementPhaseThresholdMsV74050)
                {
                    var traceCountV74050 = Interlocked.Increment(ref _v74050DeferredCleanupTraceCount);
                    if (traceCountV74050 <= 256 ||
                        (traceCountV74050 & (traceCountV74050 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.50][DEFERRED_CLEANUP_PHASES] " +
                            $"count={traceCountV74050} total_ms={totalMsV74050:F3} " +
                            $"texture_ms={textureMsV74050:F3} resource_ms={resourceMsV74050:F3} " +
                            $"image_ms={imageMsV74050:F3} textures={textureCountV74050} " +
                            $"resources={resourceCountV74050} images={imageCountV74050} " +
                            $"completed={_completedTimeline}");
                    }
                }
            }
        }

        private void WaitFrameSlot(int slot) => TryWaitFrameSlot(slot, ulong.MaxValue);

        // Returns false when the slot's fence is still unsignaled after
        // timeoutNs (the GPU is behind, e.g. a slow-compute backlog). Callers
        // on the macOS main thread must NOT wait forever here or the Cocoa
        // event pump stalls and the window goes "Not Responding" (F1 overlay /
        // close stop working). A bounded wait lets Render() skip the frame and
        // return to the pump; the fence still signals later and the frame is
        // retried.
        private bool TryWaitFrameSlot(int slot, ulong timeoutNs)
        {
            if (_frameFencePending.Length <= slot || !_frameFencePending[slot])
            {
                if (_frameGuestImageVersions.Length > slot &&
                    _frameGuestImageVersions[slot] is { } unsubmittedVersion)
                {
                    _frameGuestImageVersions[slot] = null;
                    _capturedGuestFlipVersions.Remove(unsubmittedVersion.FlipVersion);
                    DestroyGuestImage(unsubmittedVersion);
                    FlipProgressTracker.RecordFlip(unsubmittedVersion.FlipVersion);
                    TraceVulkanShader(
                        $"vk.flip_retired version={unsubmittedVersion.FlipVersion} " +
                        $"frame_slot={slot} reason=frame-not-submitted");
                }
                return true;
            }

            var fence = _frameFences[slot];
            var frameWaitStartV74045 = _traceComputePhasesV74034
                ? Stopwatch.GetTimestamp()
                : 0L;
            var waitResult = _vk.WaitForFences(_device, 1, &fence, true, timeoutNs);
            if (waitResult == Result.Timeout)
            {
                if (_traceComputePhasesV74034)
                {
                    var timeoutTraceV74045 = Interlocked.Increment(
                        ref _v74045FrameSlotTimeoutTraceCount);
                    if (timeoutTraceV74045 <= 64 ||
                        (timeoutTraceV74045 & (timeoutTraceV74045 - 1)) == 0)
                    {
                        var waitedMsV74045 =
                            (Stopwatch.GetTimestamp() - frameWaitStartV74045) *
                            1000.0 / Stopwatch.Frequency;
                        Console.Error.WriteLine(
                            $"[V74.0.45][FRAME_SLOT_TIMEOUT] " +
                            $"count={timeoutTraceV74045} slot={slot} " +
                            $"ms={waitedMsV74045:F3} frame_timeline={_frameTimelines[slot]} " +
                            $"completed={_completedTimeline} submit={_submitTimeline} " +
                            $"gpu_pending={_pendingGuestSubmissions.Count} " +
                            $"guest_work_pending={_pendingGuestWorkCount}");
                    }
                }

                return false;
            }

            Check(waitResult, "vkWaitForFences(frame)");
            if (_traceComputePhasesV74034 && frameWaitStartV74045 != 0)
            {
                var waitedMsV74045 =
                    (Stopwatch.GetTimestamp() - frameWaitStartV74045) *
                    1000.0 / Stopwatch.Frequency;
                if (waitedMsV74045 >= 1.0)
                {
                    var readyTraceV74045 = Interlocked.Increment(
                        ref _v74045FrameSlotReadyWaitTraceCount);
                    if (readyTraceV74045 <= 32 ||
                        (readyTraceV74045 & (readyTraceV74045 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.45][FRAME_SLOT_READY_WAIT] " +
                            $"count={readyTraceV74045} slot={slot} " +
                            $"ms={waitedMsV74045:F3} frame_timeline={_frameTimelines[slot]} " +
                            $"completed_before={_completedTimeline} submit={_submitTimeline}");
                    }
                }
            }
            Check(_vk.ResetFences(_device, 1, &fence), "vkResetFences(frame)");
            _frameFencePending[slot] = false;
            if (_frameTimelines[slot] > _completedTimeline)
            {
                _completedTimeline = _frameTimelines[slot];
            }

            if (_frameTranslatedResources[slot] is { } translated)
            {
                _frameTranslatedResources[slot] = null;
                DestroyTranslatedDrawResources(translated);
            }

            if (_frameTextureRetireBuffers.Length > slot)
            {
                foreach (var (buffer, memory) in _frameTextureRetireBuffers[slot])
                {
                    if (buffer.Handle != 0)
                    {
                        _vk.DestroyBuffer(_device, buffer, null);
                    }
                    if (memory.Handle != 0)
                    {
                        _vk.FreeMemory(_device, memory, null);
                    }
                }
                _frameTextureRetireBuffers[slot].Clear();
            }

            if (_frameGuestImageVersions[slot] is { } guestImageVersion)
            {
                _frameGuestImageVersions[slot] = null;
                _capturedGuestFlipVersions.Remove(guestImageVersion.FlipVersion);
                DestroyGuestImage(guestImageVersion);
                FlipProgressTracker.RecordFlip(guestImageVersion.FlipVersion);
                TraceVulkanShader(
                    $"vk.flip_retired version={guestImageVersion.FlipVersion} " +
                    $"frame_slot={slot} timeline={_frameTimelines[slot]}");
            }

            ProcessDeferredTextureDestroys();
            return true;
        }

        private void WaitAllFrameSlots()
        {
            for (var slot = 0; slot < _frameFencePending.Length; slot++)
            {
                WaitFrameSlot(slot);
            }
        }

        private void CollectAbandonedGuestImageVersions()
        {
            if (_guestImageVersions.Count == 0)
            {
                return;
            }

            HashSet<long> referencedVersions;
            lock (_gate)
            {
                referencedVersions = _pendingGuestImagePresentations
                    .Select(static presentation => presentation.GuestImageVersion)
                    .Where(static version => version != 0)
                    .ToHashSet();
                if (_latestPresentation is { GuestImageVersion: not 0 } latest)
                {
                    referencedVersions.Add(latest.GuestImageVersion);
                }
            }

            foreach (var entry in _guestImageVersions.ToArray())
            {
                if (referencedVersions.Contains(entry.Key))
                {
                    continue;
                }

                _guestImageVersions.Remove(entry.Key);
                _capturedGuestFlipVersions.Remove(entry.Key);
                _deferredGuestImageVersionDestroys.Enqueue(
                    (entry.Value, _submitTimeline));
                TraceVulkanShader(
                    $"vk.flip_retire_deferred version={entry.Key} " +
                    $"timeline={_submitTimeline} reason=presentation-dropped");
            }
        }

        // Used on teardown paths that already drained the queue (device
        // wait-idle): releases per-slot state without touching fences that
        // were never submitted.
        private void DrainFrameSlots()
        {
            WaitAllFrameSlots();
            _completedTimeline = _submitTimeline;
            ProcessDeferredTextureDestroys();
        }

        private IReadOnlyList<GuestImageResource> GetTraceImages(
            TranslatedDrawResources resources,
            IReadOnlyList<GuestImageResource>? renderTargets = null,
            ulong shaderAddress = 0)
        {
            if (!_traceGuestImagesEnabled &&
                !_traceGuestImageAddressFilterEnabled &&
                GuestImageTraceInterval() is null)
            {
                return Array.Empty<GuestImageResource>();
            }

            var candidates = new HashSet<GuestImageResource>();
            foreach (var renderTarget in renderTargets ?? [])
            {
                candidates.Add(renderTarget);
            }

            foreach (var texture in resources.Textures)
            {
                if ((texture.IsStorage || _traceGuestImageAddressFilterEnabled) &&
                    texture.GuestImage is { } image)
                {
                    candidates.Add(image);
                }
            }

            return candidates
                .Where(image => ShouldTraceGuestImageContents(image, shaderAddress))
                .ToArray();
        }

        private void CreateGuestDrawResources()
        {
            var presentationFormat = PresentationTargetFormat;
            var colorAttachment = new AttachmentDescription
            {
                Format = presentationFormat,
                Samples = SampleCountFlags.Count1Bit,
                LoadOp = AttachmentLoadOp.Clear,
                StoreOp = AttachmentStoreOp.Store,
                StencilLoadOp = AttachmentLoadOp.DontCare,
                StencilStoreOp = AttachmentStoreOp.DontCare,
                InitialLayout = ImageLayout.Undefined,
                FinalLayout = PresentationTargetFinalLayout,
            };
            var colorReference = new AttachmentReference
            {
                Attachment = 0,
                Layout = ImageLayout.ColorAttachmentOptimal,
            };
            var subpass = new SubpassDescription
            {
                PipelineBindPoint = PipelineBindPoint.Graphics,
                ColorAttachmentCount = 1,
                PColorAttachments = &colorReference,
            };
            var dependency = new SubpassDependency
            {
                SrcSubpass = Vk.SubpassExternal,
                DstSubpass = 0,
                SrcStageMask = PipelineStageFlags.ColorAttachmentOutputBit,
                DstStageMask = PipelineStageFlags.ColorAttachmentOutputBit,
                DstAccessMask = AccessFlags.ColorAttachmentWriteBit,
            };
            var renderPassInfo = new RenderPassCreateInfo
            {
                SType = StructureType.RenderPassCreateInfo,
                AttachmentCount = 1,
                PAttachments = &colorAttachment,
                SubpassCount = 1,
                PSubpasses = &subpass,
                DependencyCount = 1,
                PDependencies = &dependency,
            };
            Check(
                _vk.CreateRenderPass(
                    _device,
                    &renderPassInfo,
                    null,
                    out var swapchainRenderPass),
                "vkCreateRenderPass");
            if (swapchainRenderPass.Handle == 0)
            {
                throw new InvalidOperationException(
                    "vkCreateRenderPass returned a null swapchain render pass");
            }

            _renderPass = swapchainRenderPass;

            _swapchainImageViews = new ImageView[_swapchainImages.Length];
            _framebuffers = new Framebuffer[_swapchainImages.Length];
            if (_hdrOutputActive)
            {
                _presentationImages = new Image[_swapchainImages.Length];
                _presentationImageMemory = new DeviceMemory[_swapchainImages.Length];
                _presentationImageViews = new ImageView[_swapchainImages.Length];
                _presentationSampleViews = new ImageView[_swapchainImages.Length];
            }
            for (var index = 0; index < _swapchainImages.Length; index++)
            {
                var viewInfo = new ImageViewCreateInfo
                {
                    SType = StructureType.ImageViewCreateInfo,
                    Image = _swapchainImages[index],
                    ViewType = ImageViewType.Type2D,
                    Format = _swapchainFormat,
                    Components = new ComponentMapping(
                        ComponentSwizzle.Identity,
                        ComponentSwizzle.Identity,
                        ComponentSwizzle.Identity,
                        ComponentSwizzle.Identity),
                    SubresourceRange = ColorSubresourceRange(),
                };
                Check(
                    _vk.CreateImageView(_device, &viewInfo, null, out _swapchainImageViews[index]),
                    "vkCreateImageView");

                var imageView = _swapchainImageViews[index];
                if (_hdrOutputActive)
                {
                    CreatePresentationImage(index);
                    imageView = _presentationImageViews[index];
                }
                var framebufferInfo = new FramebufferCreateInfo
                {
                    SType = StructureType.FramebufferCreateInfo,
                    RenderPass = swapchainRenderPass,
                    AttachmentCount = 1,
                    PAttachments = &imageView,
                    Width = _extent.Width,
                    Height = _extent.Height,
                    Layers = 1,
                };
                Check(
                    _vk.CreateFramebuffer(_device, &framebufferInfo, null, out _framebuffers[index]),
                    "vkCreateFramebuffer");
            }

            var layoutInfo = new PipelineLayoutCreateInfo
            {
                SType = StructureType.PipelineLayoutCreateInfo,
            };
            Check(
                _vk.CreatePipelineLayout(_device, &layoutInfo, null, out _pipelineLayout),
                "vkCreatePipelineLayout");
            CreateBarycentricPipeline();
            if (_hdrOutputActive)
            {
                CreateHdrPresentationResources();
            }
        }

        private Format PresentationTargetFormat =>
            _hdrOutputActive ? Format.B8G8R8A8Unorm : _swapchainFormat;

        private ImageLayout PresentationTargetFinalLayout =>
            _hdrOutputActive ? ImageLayout.ShaderReadOnlyOptimal : ImageLayout.PresentSrcKhr;

        private Image PresentationTargetImage(uint imageIndex) =>
            _hdrOutputActive ? _presentationImages[imageIndex] : _swapchainImages[imageIndex];

        private void CreatePresentationImage(int index)
        {
            var imageInfo = new ImageCreateInfo
            {
                SType = StructureType.ImageCreateInfo,
                Flags = ImageCreateFlags.CreateMutableFormatBit,
                ImageType = ImageType.Type2D,
                Format = Format.B8G8R8A8Unorm,
                Extent = new Extent3D(_extent.Width, _extent.Height, 1),
                MipLevels = 1,
                ArrayLayers = 1,
                Samples = SampleCountFlags.Count1Bit,
                Tiling = ImageTiling.Optimal,
                Usage = ImageUsageFlags.ColorAttachmentBit |
                        ImageUsageFlags.TransferDstBit |
                        ImageUsageFlags.TransferSrcBit |
                        ImageUsageFlags.SampledBit,
                SharingMode = SharingMode.Exclusive,
                InitialLayout = ImageLayout.Undefined,
            };
            Check(
                _vk.CreateImage(_device, &imageInfo, null, out _presentationImages[index]),
                "vkCreateImage(HDR presentation source)");
            _vk.GetImageMemoryRequirements(
                _device,
                _presentationImages[index],
                out var requirements);
            var allocationInfo = new MemoryAllocateInfo
            {
                SType = StructureType.MemoryAllocateInfo,
                AllocationSize = requirements.Size,
                MemoryTypeIndex = FindMemoryType(
                    requirements.MemoryTypeBits,
                    MemoryPropertyFlags.DeviceLocalBit),
            };
            Check(
                _vk.AllocateMemory(
                    _device,
                    &allocationInfo,
                    null,
                    out _presentationImageMemory[index]),
                "vkAllocateMemory(HDR presentation source)");
            Check(
                _vk.BindImageMemory(
                    _device,
                    _presentationImages[index],
                    _presentationImageMemory[index],
                    0),
                "vkBindImageMemory(HDR presentation source)");

            _presentationImageViews[index] = CreatePresentationImageView(
                _presentationImages[index],
                Format.B8G8R8A8Unorm);
            _presentationSampleViews[index] = CreatePresentationImageView(
                _presentationImages[index],
                Format.B8G8R8A8Srgb);
        }

        private ImageView CreatePresentationImageView(Image image, Format format)
        {
            var viewInfo = new ImageViewCreateInfo
            {
                SType = StructureType.ImageViewCreateInfo,
                Image = image,
                ViewType = ImageViewType.Type2D,
                Format = format,
                Components = new ComponentMapping(
                    ComponentSwizzle.Identity,
                    ComponentSwizzle.Identity,
                    ComponentSwizzle.Identity,
                    ComponentSwizzle.Identity),
                SubresourceRange = ColorSubresourceRange(),
            };
            Check(
                _vk.CreateImageView(_device, &viewInfo, null, out var view),
                "vkCreateImageView(HDR presentation source)");
            return view;
        }

        private void CreateHdrPresentationResources()
        {
            var colorAttachment = new AttachmentDescription
            {
                Format = _swapchainFormat,
                Samples = SampleCountFlags.Count1Bit,
                LoadOp = AttachmentLoadOp.Clear,
                StoreOp = AttachmentStoreOp.Store,
                StencilLoadOp = AttachmentLoadOp.DontCare,
                StencilStoreOp = AttachmentStoreOp.DontCare,
                InitialLayout = ImageLayout.Undefined,
                FinalLayout = ImageLayout.PresentSrcKhr,
            };
            var colorReference = new AttachmentReference(0, ImageLayout.ColorAttachmentOptimal);
            var subpass = new SubpassDescription
            {
                PipelineBindPoint = PipelineBindPoint.Graphics,
                ColorAttachmentCount = 1,
                PColorAttachments = &colorReference,
            };
            var dependency = new SubpassDependency
            {
                SrcSubpass = Vk.SubpassExternal,
                DstSubpass = 0,
                SrcStageMask = PipelineStageFlags.ColorAttachmentOutputBit,
                DstStageMask = PipelineStageFlags.ColorAttachmentOutputBit,
                DstAccessMask = AccessFlags.ColorAttachmentWriteBit,
            };
            var renderPassInfo = new RenderPassCreateInfo
            {
                SType = StructureType.RenderPassCreateInfo,
                AttachmentCount = 1,
                PAttachments = &colorAttachment,
                SubpassCount = 1,
                PSubpasses = &subpass,
                DependencyCount = 1,
                PDependencies = &dependency,
            };
            Check(
                _vk.CreateRenderPass(_device, &renderPassInfo, null, out _hdrRenderPass),
                "vkCreateRenderPass(HDR presentation)");

            _hdrFramebuffers = new Framebuffer[_swapchainImageViews.Length];
            for (var index = 0; index < _swapchainImageViews.Length; index++)
            {
                var view = _swapchainImageViews[index];
                var framebufferInfo = new FramebufferCreateInfo
                {
                    SType = StructureType.FramebufferCreateInfo,
                    RenderPass = _hdrRenderPass,
                    AttachmentCount = 1,
                    PAttachments = &view,
                    Width = _extent.Width,
                    Height = _extent.Height,
                    Layers = 1,
                };
                Check(
                    _vk.CreateFramebuffer(
                        _device,
                        &framebufferInfo,
                        null,
                        out _hdrFramebuffers[index]),
                    "vkCreateFramebuffer(HDR presentation)");
            }

            var binding = new DescriptorSetLayoutBinding
            {
                Binding = 1,
                DescriptorType = DescriptorType.CombinedImageSampler,
                DescriptorCount = 1,
                StageFlags = ShaderStageFlags.FragmentBit,
            };
            var descriptorLayoutInfo = new DescriptorSetLayoutCreateInfo
            {
                SType = StructureType.DescriptorSetLayoutCreateInfo,
                BindingCount = 1,
                PBindings = &binding,
            };
            Check(
                _vk.CreateDescriptorSetLayout(
                    _device,
                    &descriptorLayoutInfo,
                    null,
                    out _hdrDescriptorSetLayout),
                "vkCreateDescriptorSetLayout(HDR presentation)");

            var descriptorPoolSize = new DescriptorPoolSize
            {
                Type = DescriptorType.CombinedImageSampler,
                DescriptorCount = checked((uint)_presentationSampleViews.Length * 2),
            };
            var descriptorPoolInfo = new DescriptorPoolCreateInfo
            {
                SType = StructureType.DescriptorPoolCreateInfo,
                MaxSets = checked((uint)_presentationSampleViews.Length * 2),
                PoolSizeCount = 1,
                PPoolSizes = &descriptorPoolSize,
            };
            Check(
                _vk.CreateDescriptorPool(
                    _device,
                    &descriptorPoolInfo,
                    null,
                    out _hdrDescriptorPool),
                "vkCreateDescriptorPool(HDR presentation)");

            var samplerInfo = new SamplerCreateInfo
            {
                SType = StructureType.SamplerCreateInfo,
                MagFilter = Filter.Linear,
                MinFilter = Filter.Linear,
                MipmapMode = SamplerMipmapMode.Linear,
                AddressModeU = SamplerAddressMode.ClampToEdge,
                AddressModeV = SamplerAddressMode.ClampToEdge,
                AddressModeW = SamplerAddressMode.ClampToEdge,
                MaxLod = 1f,
            };
            Check(
                _vk.CreateSampler(_device, &samplerInfo, null, out _hdrSampler),
                "vkCreateSampler(HDR presentation)");

            _hdrDescriptorSets = new DescriptorSet[_presentationSampleViews.Length];
            _hdrPqDescriptorSets = new DescriptorSet[_presentationSampleViews.Length];
            for (var pq = 0; pq < 2; pq++)
            {
                var descriptorSets = pq == 0 ? _hdrDescriptorSets : _hdrPqDescriptorSets;
                var imageViews = pq == 0 ? _presentationSampleViews : _presentationImageViews;
                for (var index = 0; index < descriptorSets.Length; index++)
                {
                    var layout = _hdrDescriptorSetLayout;
                    var allocateInfo = new DescriptorSetAllocateInfo
                    {
                        SType = StructureType.DescriptorSetAllocateInfo,
                        DescriptorPool = _hdrDescriptorPool,
                        DescriptorSetCount = 1,
                        PSetLayouts = &layout,
                    };
                    Check(
                        _vk.AllocateDescriptorSets(
                            _device,
                            &allocateInfo,
                            out descriptorSets[index]),
                        "vkAllocateDescriptorSets(HDR presentation)");
                    var imageInfo = new DescriptorImageInfo
                    {
                        Sampler = _hdrSampler,
                        ImageView = imageViews[index],
                        ImageLayout = ImageLayout.ShaderReadOnlyOptimal,
                    };
                    var write = new WriteDescriptorSet
                    {
                        SType = StructureType.WriteDescriptorSet,
                        DstSet = descriptorSets[index],
                        DstBinding = 1,
                        DescriptorCount = 1,
                        DescriptorType = DescriptorType.CombinedImageSampler,
                        PImageInfo = &imageInfo,
                    };
                    _vk.UpdateDescriptorSets(_device, 1, &write, 0, null);
                }
            }

            var descriptorSetLayout = _hdrDescriptorSetLayout;
            var pipelineLayoutInfo = new PipelineLayoutCreateInfo
            {
                SType = StructureType.PipelineLayoutCreateInfo,
                SetLayoutCount = 1,
                PSetLayouts = &descriptorSetLayout,
            };
            Check(
                _vk.CreatePipelineLayout(
                    _device,
                    &pipelineLayoutInfo,
                    null,
                    out _hdrPipelineLayout),
                "vkCreatePipelineLayout(HDR presentation)");
            CreateHdrPresentationPipelines();
        }

        private void CreateHdrPresentationPipelines()
        {
            CreateHdrPresentationPipeline(
                SpirvFixedShaders.CreateCopyFragment(_hdrSdrWhiteLevel),
                "SDR",
                out _hdrPipeline);
            CreateHdrPresentationPipeline(
                SpirvFixedShaders.CreatePqToScRgbFragment(),
                "PQ",
                out _hdrPqPipeline);
        }

        private void CreateHdrPresentationPipeline(
            byte[] fragmentBytes,
            string label,
            out Pipeline pipeline)
        {
            var vertexModule = CreateShaderModule(SpirvFixedShaders.CreateFullscreenVertex(1));
            var fragmentModule = CreateShaderModule(fragmentBytes);
            var entryPoint = (byte*)SilkMarshal.StringToPtr("main");
            try
            {
                var stages = stackalloc PipelineShaderStageCreateInfo[2];
                stages[0] = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.VertexBit,
                    Module = vertexModule,
                    PName = entryPoint,
                };
                stages[1] = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.FragmentBit,
                    Module = fragmentModule,
                    PName = entryPoint,
                };
                var vertexInput = new PipelineVertexInputStateCreateInfo
                {
                    SType = StructureType.PipelineVertexInputStateCreateInfo,
                };
                var inputAssembly = new PipelineInputAssemblyStateCreateInfo
                {
                    SType = StructureType.PipelineInputAssemblyStateCreateInfo,
                    Topology = PrimitiveTopology.TriangleList,
                };
                var viewport = new Viewport(0, 0, _extent.Width, _extent.Height, 0, 1);
                var scissor = new Rect2D(new Offset2D(0, 0), _extent);
                var viewportState = new PipelineViewportStateCreateInfo
                {
                    SType = StructureType.PipelineViewportStateCreateInfo,
                    ViewportCount = 1,
                    PViewports = &viewport,
                    ScissorCount = 1,
                    PScissors = &scissor,
                };
                var rasterization = new PipelineRasterizationStateCreateInfo
                {
                    SType = StructureType.PipelineRasterizationStateCreateInfo,
                    PolygonMode = PolygonMode.Fill,
                    CullMode = CullModeFlags.None,
                    FrontFace = FrontFace.CounterClockwise,
                    LineWidth = 1,
                };
                var multisample = new PipelineMultisampleStateCreateInfo
                {
                    SType = StructureType.PipelineMultisampleStateCreateInfo,
                    RasterizationSamples = SampleCountFlags.Count1Bit,
                };
                var blendAttachment = new PipelineColorBlendAttachmentState
                {
                    ColorWriteMask = ColorComponentFlags.RBit |
                                     ColorComponentFlags.GBit |
                                     ColorComponentFlags.BBit |
                                     ColorComponentFlags.ABit,
                };
                var blend = new PipelineColorBlendStateCreateInfo
                {
                    SType = StructureType.PipelineColorBlendStateCreateInfo,
                    AttachmentCount = 1,
                    PAttachments = &blendAttachment,
                };
                var pipelineInfo = new GraphicsPipelineCreateInfo
                {
                    SType = StructureType.GraphicsPipelineCreateInfo,
                    StageCount = 2,
                    PStages = stages,
                    PVertexInputState = &vertexInput,
                    PInputAssemblyState = &inputAssembly,
                    PViewportState = &viewportState,
                    PRasterizationState = &rasterization,
                    PMultisampleState = &multisample,
                    PColorBlendState = &blend,
                    Layout = _hdrPipelineLayout,
                    RenderPass = _hdrRenderPass,
                };
                Check(
                    _vk.CreateGraphicsPipelines(
                        _device,
                        _pipelineCache,
                        1,
                        &pipelineInfo,
                        null,
                        out pipeline),
                    $"vkCreateGraphicsPipelines(HDR {label} presentation)");
                MarkPipelineCacheDirty();
            }
            finally
            {
                SilkMarshal.Free((nint)entryPoint);
                _vk.DestroyShaderModule(_device, fragmentModule, null);
                _vk.DestroyShaderModule(_device, vertexModule, null);
            }
        }

        private void RecordHdrPresentation(uint imageIndex, bool isHdr)
        {
            var sourceBarrier = new ImageMemoryBarrier
            {
                SType = StructureType.ImageMemoryBarrier,
                SrcAccessMask = AccessFlags.MemoryWriteBit |
                                AccessFlags.TransferWriteBit |
                                AccessFlags.ColorAttachmentWriteBit,
                DstAccessMask = AccessFlags.ShaderReadBit,
                OldLayout = ImageLayout.ShaderReadOnlyOptimal,
                NewLayout = ImageLayout.ShaderReadOnlyOptimal,
                SrcQueueFamilyIndex = Vk.QueueFamilyIgnored,
                DstQueueFamilyIndex = Vk.QueueFamilyIgnored,
                Image = _presentationImages[imageIndex],
                SubresourceRange = ColorSubresourceRange(),
            };
            _vk.CmdPipelineBarrier(
                _commandBuffer,
                PipelineStageFlags.AllCommandsBit,
                (PipelineStageFlags.VertexShaderBit | PipelineStageFlags.FragmentShaderBit | PipelineStageFlags.ComputeShaderBit /* V30 resource consumer visibility */),
                0,
                0,
                null,
                0,
                null,
                1,
                &sourceBarrier);

            var clearValue = new ClearValue
            {
                Color = new ClearColorValue(0f, 0f, 0f, 1f),
            };
            var renderPassInfo = new RenderPassBeginInfo
            {
                SType = StructureType.RenderPassBeginInfo,
                RenderPass = _hdrRenderPass,
                Framebuffer = _hdrFramebuffers[imageIndex],
                RenderArea = new Rect2D(new Offset2D(0, 0), _extent),
                ClearValueCount = 1,
                PClearValues = &clearValue,
            };
            _vk.CmdBeginRenderPass(
                _commandBuffer,
                &renderPassInfo,
                SubpassContents.Inline);
            _vk.CmdBindPipeline(
                _commandBuffer,
                PipelineBindPoint.Graphics,
                isHdr ? _hdrPqPipeline : _hdrPipeline);
            var descriptorSet = isHdr
                ? _hdrPqDescriptorSets[imageIndex]
                : _hdrDescriptorSets[imageIndex];
            _vk.CmdBindDescriptorSets(
                _commandBuffer,
                PipelineBindPoint.Graphics,
                _hdrPipelineLayout,
                0,
                1,
                &descriptorSet,
                0,
                null);
            _vk.CmdDraw(_commandBuffer, 3, 1, 0, 0);
            _vk.CmdEndRenderPass(_commandBuffer);
        }

        private void CreateBarycentricPipeline()
        {
            var vertexBytes = Convert.FromBase64String(FullscreenBarycentricVertexSpirv);
            var fragmentBytes = Convert.FromBase64String(FullscreenBarycentricFragmentSpirv);
            var vertexModule = CreateShaderModule(vertexBytes);
            var fragmentModule = CreateShaderModule(fragmentBytes);
            var entryPoint = (byte*)SilkMarshal.StringToPtr("main");
            try
            {
                var shaderStages = stackalloc PipelineShaderStageCreateInfo[2];
                shaderStages[0] = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.VertexBit,
                    Module = vertexModule,
                    PName = entryPoint,
                };
                shaderStages[1] = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.FragmentBit,
                    Module = fragmentModule,
                    PName = entryPoint,
                };

                var vertexInput = new PipelineVertexInputStateCreateInfo
                {
                    SType = StructureType.PipelineVertexInputStateCreateInfo,
                };
                var inputAssembly = new PipelineInputAssemblyStateCreateInfo
                {
                    SType = StructureType.PipelineInputAssemblyStateCreateInfo,
                    Topology = PrimitiveTopology.TriangleList,
                };
                var viewport = new Viewport(0, 0, _extent.Width, _extent.Height, 0, 1);
                var scissor = new Rect2D(new Offset2D(0, 0), _extent);
                var viewportState = new PipelineViewportStateCreateInfo
                {
                    SType = StructureType.PipelineViewportStateCreateInfo,
                    ViewportCount = 1,
                    PViewports = &viewport,
                    ScissorCount = 1,
                    PScissors = &scissor,
                };
                var rasterization = new PipelineRasterizationStateCreateInfo
                {
                    SType = StructureType.PipelineRasterizationStateCreateInfo,
                    PolygonMode = PolygonMode.Fill,
                    CullMode = CullModeFlags.None,
                    FrontFace = FrontFace.CounterClockwise,
                    LineWidth = 1,
                };
                var multisample = new PipelineMultisampleStateCreateInfo
                {
                    SType = StructureType.PipelineMultisampleStateCreateInfo,
                    RasterizationSamples = SampleCountFlags.Count1Bit,
                };
                var colorBlendAttachment = new PipelineColorBlendAttachmentState
                {
                    ColorWriteMask =
                        ColorComponentFlags.RBit |
                        ColorComponentFlags.GBit |
                        ColorComponentFlags.BBit |
                        ColorComponentFlags.ABit,
                };
                var colorBlend = new PipelineColorBlendStateCreateInfo
                {
                    SType = StructureType.PipelineColorBlendStateCreateInfo,
                    AttachmentCount = 1,
                    PAttachments = &colorBlendAttachment,
                };
                var pipelineInfo = new GraphicsPipelineCreateInfo
                {
                    SType = StructureType.GraphicsPipelineCreateInfo,
                    StageCount = 2,
                    PStages = shaderStages,
                    PVertexInputState = &vertexInput,
                    PInputAssemblyState = &inputAssembly,
                    PViewportState = &viewportState,
                    PRasterizationState = &rasterization,
                    PMultisampleState = &multisample,
                    PColorBlendState = &colorBlend,
                    Layout = _pipelineLayout,
                    RenderPass = _renderPass,
                    Subpass = 0,
                };
                Check(
                    _vk.CreateGraphicsPipelines(
                        _device,
                        _pipelineCache,
                        1,
                        &pipelineInfo,
                        null,
                        out _barycentricPipeline),
                    "vkCreateGraphicsPipelines");
                MarkPipelineCacheDirty();
            }
            finally
            {
                SilkMarshal.Free((nint)entryPoint);
                _vk.DestroyShaderModule(_device, fragmentModule, null);
                _vk.DestroyShaderModule(_device, vertexModule, null);
            }
        }

        private static int _shaderModuleDumpSequence;

        private ShaderModule CreateShaderModule(byte[] code)
        {
            if (IsShaderValidationEnabledV61161())
            {
                ValidateShaderSpirvV61161(code);
            }
            string? dumpPath = null;
            var dumpDirectory = Environment.GetEnvironmentVariable("SHARPEMU_SHADER_SPIRV_DUMP_DIR");
            if (!string.IsNullOrWhiteSpace(dumpDirectory))
            {
                Directory.CreateDirectory(dumpDirectory);

                var sequence = Interlocked.Increment(ref _shaderModuleDumpSequence);
                dumpPath = Path.Combine(dumpDirectory, $"{sequence:D4}.spv");
                File.WriteAllBytes(dumpPath, code);

                _pendingShaderModuleDumpPath = dumpPath;
            }


            try
            {
                fixed (byte* codePointer = code)
                {
                    var createInfo = new ShaderModuleCreateInfo
                    {
                        SType = StructureType.ShaderModuleCreateInfo,
                        CodeSize = (nuint)code.Length,
                        PCode = (uint*)codePointer,
                    };
                    Check(
                        _vk.CreateShaderModule(_device, &createInfo, null, out var module),
                        "vkCreateShaderModule");
                    return module;
                }
            }
            finally
            {
                _pendingShaderModuleDumpPath = null;
            }
        }


        // V61.16.2_SHADER_SPIRV_VALIDATION
        private static bool IsShaderValidationEnabledV61161()
        {
            var value = Environment.GetEnvironmentVariable("SHARPEMU_SHADER_VALIDATE");
            return string.Equals(value, "1", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "true", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "yes", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "on", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsShaderValidationStrictV61161()
        {
            var value = Environment.GetEnvironmentVariable("SHARPEMU_SHADER_VALIDATE_STRICT");
            return string.Equals(value, "1", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "true", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "yes", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "on", StringComparison.OrdinalIgnoreCase);
        }

        private static void ValidateShaderSpirvV61161(byte[] code)
        {
            var strict = IsShaderValidationStrictV61161();
            var issues = new System.Collections.Generic.List<string>();

            if (code.Length < 20)
            {
                issues.Add($"SPIR-V is too short: {code.Length} bytes.");
            }

            if ((code.Length & 3) != 0)
            {
                issues.Add($"SPIR-V byte length is not uint32 aligned: {code.Length}.");
            }

            uint magic = 0;
            uint version = 0;
            uint generator = 0;
            uint bound = 0;
            uint schema = 0;

            if (code.Length >= 20)
            {
                magic = BitConverter.ToUInt32(code, 0);
                version = BitConverter.ToUInt32(code, 4);
                generator = BitConverter.ToUInt32(code, 8);
                bound = BitConverter.ToUInt32(code, 12);
                schema = BitConverter.ToUInt32(code, 16);

                if (magic != 0x07230203u)
                {
                    issues.Add($"Invalid SPIR-V magic 0x{magic:X8}.");
                }

                if (bound == 0)
                {
                    issues.Add("SPIR-V id bound is zero.");
                }
            }

            var directory = Environment.GetEnvironmentVariable("SHARPEMU_SHADER_VALIDATE_DIR");
            if (string.IsNullOrWhiteSpace(directory))
            {
                directory = Environment.GetEnvironmentVariable("SHARPEMU_SHADER_SPIRV_DUMP_DIR");
            }

            if (string.IsNullOrWhiteSpace(directory))
            {
                directory = Path.Combine(
                    Environment.CurrentDirectory,
                    "artifacts",
                    "shader-validation");
            }

            Directory.CreateDirectory(directory);

            var sequence = Interlocked.Increment(ref _shaderModuleDumpSequence);
            var stem = $"{sequence:D5}-shader";
            var spvPath = Path.Combine(directory, stem + ".spv");
            File.WriteAllBytes(spvPath, code);

            var report = new System.Collections.Generic.List<string>
            {
                "SharpEmu SPIR-V validation report",
                $"bytes={code.Length}",
                $"magic=0x{magic:X8}",
                $"version=0x{version:X8}",
                $"generator=0x{generator:X8}",
                $"bound={bound}",
                $"schema={schema}",
                $"strict={strict}",
                $"spv={spvPath}",
            };

            var validator = FindSpirvToolV61161("spirv-val");
            if (validator is not null)
            {
                var result = RunSpirvToolV61161(
                    validator,
                    $"\"{spvPath}\"",
                    15000);

                report.Add($"spirv-val={validator}");
                report.Add($"spirv-val.exit={result.ExitCode}");

                if (!string.IsNullOrWhiteSpace(result.StandardOutput))
                {
                    report.Add("spirv-val.stdout:");
                    report.Add(result.StandardOutput.TrimEnd());
                }

                if (!string.IsNullOrWhiteSpace(result.StandardError))
                {
                    report.Add("spirv-val.stderr:");
                    report.Add(result.StandardError.TrimEnd());
                }

                if (result.ExitCode != 0)
                {
                    issues.Add($"spirv-val failed with exit code {result.ExitCode}.");
                }
            }
            else
            {
                report.Add("spirv-val=not-found; internal header validation only");
            }

            var disassembler = FindSpirvToolV61161("spirv-dis");
            if (disassembler is not null)
            {
                var disassemblyPath = Path.Combine(directory, stem + ".spvasm");
                var result = RunSpirvToolV61161(
                    disassembler,
                    $"\"{spvPath}\" -o \"{disassemblyPath}\"",
                    15000);

                report.Add($"spirv-dis={disassembler}");
                report.Add($"spirv-dis.exit={result.ExitCode}");
                report.Add($"spvasm={disassemblyPath}");

                if (result.ExitCode != 0 &&
                    !string.IsNullOrWhiteSpace(result.StandardError))
                {
                    report.Add("spirv-dis.stderr:");
                    report.Add(result.StandardError.TrimEnd());
                }
            }
            else
            {
                report.Add("spirv-dis=not-found");
            }

            if (issues.Count == 0)
            {
                report.Add("result=VALID");
                Console.Error.WriteLine(
                    $"[LOADER][INFO] shader.spirv_valid bytes={code.Length} path='{spvPath}'");
            }
            else
            {
                report.Add("result=INVALID");
                report.Add("issues:");
                report.AddRange(issues);

                Console.Error.WriteLine(
                    $"[LOADER][WARN] shader.spirv_invalid bytes={code.Length} " +
                    $"issues={issues.Count} path='{spvPath}'");
            }

            var reportPath = Path.Combine(directory, stem + ".validation.txt");
            File.WriteAllLines(reportPath, report);

            if (strict && issues.Count != 0)
            {
                throw new InvalidDataException(
                    $"SPIR-V validation failed: {string.Join(" | ", issues)} " +
                    $"Report: {reportPath}");
            }
        }

        private static string? FindSpirvToolV61161(string toolName)
        {
            var explicitDirectory =
                Environment.GetEnvironmentVariable("SHARPEMU_SPIRV_TOOLS_DIR");

            var executableName = OperatingSystem.IsWindows()
                ? toolName + ".exe"
                : toolName;

            if (!string.IsNullOrWhiteSpace(explicitDirectory))
            {
                var candidate = Path.Combine(explicitDirectory, executableName);
                if (File.Exists(candidate))
                {
                    return candidate;
                }
            }

            var pathValue = Environment.GetEnvironmentVariable("PATH");
            if (!string.IsNullOrWhiteSpace(pathValue))
            {
                foreach (var entry in pathValue.Split(Path.PathSeparator))
                {
                    if (string.IsNullOrWhiteSpace(entry))
                    {
                        continue;
                    }

                    try
                    {
                        var candidate = Path.Combine(entry.Trim(), executableName);
                        if (File.Exists(candidate))
                        {
                            return candidate;
                        }
                    }
                    catch
                    {
                    }
                }
            }

            return null;
        }

        private static SpirvToolResultV61161 RunSpirvToolV61161(
            string executable,
            string arguments,
            int timeoutMilliseconds)
        {
            var startInfo = new System.Diagnostics.ProcessStartInfo
            {
                FileName = executable,
                Arguments = arguments,
                UseShellExecute = false,
                CreateNoWindow = true,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
            };

            using var process = new System.Diagnostics.Process
            {
                StartInfo = startInfo,
            };

            if (!process.Start())
            {
                return new SpirvToolResultV61161(
                    -1,
                    string.Empty,
                    "Failed to start process.");
            }

            var stdoutTask = process.StandardOutput.ReadToEndAsync();
            var stderrTask = process.StandardError.ReadToEndAsync();

            if (!process.WaitForExit(timeoutMilliseconds))
            {
                try
                {
                    process.Kill(entireProcessTree: true);
                }
                catch
                {
                }

                return new SpirvToolResultV61161(
                    -2,
                    stdoutTask.IsCompletedSuccessfully
                        ? stdoutTask.Result
                        : string.Empty,
                    "SPIR-V tool timed out.");
            }

            return new SpirvToolResultV61161(
                process.ExitCode,
                stdoutTask.GetAwaiter().GetResult(),
                stderrTask.GetAwaiter().GetResult());
        }

        private readonly record struct SpirvToolResultV61161(
            int ExitCode,
            string StandardOutput,
            string StandardError);

private TranslatedDrawResources CreateTranslatedDrawResources(
            VulkanTranslatedGuestDraw draw,
            RenderPass renderPass,
            IReadOnlyList<Format> renderTargetFormats,
            Extent2D extent,
            IReadOnlyList<GuestImageResource>? feedbackTargets = null,
            bool hasDepthAttachment = false,
            GuestDepthResource? feedbackDepth = null)
        {
            var isTitleDraw = IsTitleDraw(draw.VertexBuffers);
            var forceFullscreenVertex = _forceFullscreenPipeline ||
                _forceFullscreenVertex ||
                isTitleDraw && _forceTitleFullscreenVertex ||
                AnyTargetAddressMatches(
                    feedbackTargets,
                    "SHARPEMU_FORCE_FULLSCREEN_VERTEX_TARGETS");
            var forceRasterState = _forceFullscreenPipeline ||
                _forceDefaultRasterState ||
                isTitleDraw && _forceTitleDefaultRasterState ||
                AnyTargetAddressMatches(
                    feedbackTargets,
                    "SHARPEMU_FORCE_DEFAULT_RASTER_STATE_TARGETS");
            var forceTitleSolidFragment =
                _forceTitleSolidFragment &&
                isTitleDraw;
            var forceSolidFragment = forceTitleSolidFragment ||
                _forceFullscreenPipeline ||
                _forceSolidFragment ||
                AnyTargetAddressMatches(
                    feedbackTargets,
                    "SHARPEMU_FORCE_SOLID_FRAGMENT_TARGETS");
            var attributeFragmentLocation =
                _forceAttributeFragmentLocation.GetValueOrDefault();
            var forceAttributeFragment =
                _forceAttributeFragmentLocation.HasValue &&
                AnyTargetAddressMatches(
                    feedbackTargets,
                    "SHARPEMU_FORCE_ATTRIBUTE_FRAGMENT_TARGETS");
            var vertexSpirv = forceFullscreenVertex
                ? SpirvFixedShaders.CreateFullscreenVertex(0)
                : draw.VertexSpirv;
            var fragmentSpirv = forceSolidFragment
                ? SpirvFixedShaders.CreateSolidFragment(1f, 0f, 1f, 1f)
                : forceAttributeFragment
                    ? SpirvFixedShaders.CreateAttributeFragment(attributeFragmentLocation)
                : draw.PixelSpirv;
            if (forceSolidFragment && !string.IsNullOrWhiteSpace(_fixedFragmentDumpPath))
            {
                File.WriteAllBytes(_fixedFragmentDumpPath, fragmentSpirv);
            }
            if (draw.RenderState.Blends.Count != renderTargetFormats.Count)
            {
                throw new InvalidOperationException(
                    "color attachment formats and blend states must have matching counts");
            }
            if (vertexSpirv.Length == 0 &&
                !TryCompileFullscreenVertexShader(
                    draw.AttributeCount,
                    out vertexSpirv,
                    out var vertexError))
            {
                throw new InvalidOperationException($"translated vertex shader failed: {vertexError}");
            }

            var resources = new TranslatedDrawResources
            {
                DebugName = "SharpEmu draw",
                Textures = new TextureResource[draw.Textures.Count],
                GlobalMemoryBuffers =
                    new GlobalBufferResource[draw.GlobalMemoryBuffers.Count],
                VertexBuffers = new VertexBufferResource[draw.VertexBuffers.Count],
                VertexCount = GetDrawVertexCount(
                    draw.PrimitiveType,
                    draw.VertexCount,
                    draw.IndexBuffer,
                    draw.VertexBuffers.Count > 0),
                InstanceCount = Math.Max(draw.InstanceCount, 1),
                BaseVertex = draw.BaseVertex,
                Topology = GetPrimitiveTopology(
                    draw.PrimitiveType,
                    indexed: draw.IndexBuffer is not null,
                    vertexCount: draw.VertexCount,
                    hasVertexBuffers: draw.VertexBuffers.Count > 0),
                Blends = draw.RenderState.Blends.ToArray(),
                BlendConstant = draw.RenderState.BlendConstant,
                Scissor = draw.RenderState.Scissor,
                Viewport = draw.RenderState.Viewport,
                Raster = draw.RenderState.Raster,
                Depth = draw.RenderState.Depth,
                HasDepthAttachment = hasDepthAttachment,
                TargetFormats = renderTargetFormats.ToArray(),
            };
            if (forceFullscreenVertex)
            {
                resources.VertexCount = 3;
                resources.InstanceCount = 1;
                resources.Topology = PrimitiveTopology.TriangleList;
            }
            if (forceRasterState)
            {
                resources.Blends = Enumerable.Repeat(
                    GuestBlendState.Default,
                    renderTargetFormats.Count).ToArray();
                resources.Scissor = null;
                resources.Viewport = null;
                resources.Raster = GuestRasterState.Default;
                resources.Depth = GuestDepthState.Default;
            }
            if (isTitleDraw && _forceTitleDefaultBlend)
            {
                resources.Blends = Enumerable.Repeat(
                    GuestBlendState.Default,
                    renderTargetFormats.Count).ToArray();
            }
            if (isTitleDraw && _forceTitleDefaultViewportScissor)
            {
                resources.Scissor = null;
                resources.Viewport = null;
            }
            if (isTitleDraw && _forceTitleDisableCull)
            {
                resources.Raster = resources.Raster with
                {
                    CullFront = false,
                    CullBack = false,
                };
            }
            if (isTitleDraw && _forceTitleDisableDepth)
            {
                resources.Depth = GuestDepthState.Default;
            }
            if (isTitleDraw && _traceTitleState)
            {
                Console.Error.WriteLine(
                    $"[LOADER][TRACE] vk.title_state " +
                    $"viewport={resources.Viewport} scissor={resources.Scissor} " +
                    $"raster={resources.Raster} depth={resources.Depth} " +
                    $"blends=[{string.Join(',', resources.Blends)}]");
            }

            var resourcePhaseStartV7405623 =
                _traceDrawResourcePhasesV7405623
                    ? Stopwatch.GetTimestamp()
                    : 0L;
            var resourcePhaseLastV7405623 = resourcePhaseStartV7405623;
            long storageTicksV7405623 = 0;
            long textureTicksV7405623 = 0;
            long globalTicksV7405623 = 0;
            long vertexTicksV7405623 = 0;
            long descriptorTicksV7405623 = 0;
            long pipelineTicksV7405623 = 0;

            // SHARPEMU_V74_0_81_PRESS_ANY_BUTTON_SHADER_TREATMENT
            // This is intentionally not a replacement/fixed shader. Preserve
            // the guest SPIR-V, blend, viewport and vertex animation; the V81
            // treatment is to feed that real title shader the synchronized Bink
            // movie planes it expects. Emit a bounded proof of the guest shader
            // state so a remaining opcode/attribute defect can be isolated
            // without faking the PRESS ANY BUTTON text.
            if (isTitleDraw &&
                HostMovieBridge.IsTitleLoopCompositeActiveV74081)
            {
                var titleTraceCount =
                    Interlocked.Read(
                        ref _v74081TitleLoopCompositeCount);
                if (titleTraceCount < 64)
                {
                    var pixelDigest = Convert.ToHexString(
                        SHA256.HashData(draw.PixelSpirv).AsSpan(0, 4));
                    Console.Error.WriteLine(
                        "[V74.0.81][PRESS_ANY_BUTTON_SHADER] " +
                        $"pixel_digest={pixelDigest} " +
                        $"vertices={resources.VertexCount} " +
                        $"instances={resources.InstanceCount} " +
                        $"textures={draw.Textures.Count} " +
                        $"blends={resources.Blends.Length} " +
                        $"viewport={resources.Viewport} " +
                        $"scissor={resources.Scissor} " +
                        "mode=guest-original-with-synchronized-title-loop");
                }
            }
            try
            {
                foreach (var texture in draw.Textures)
                {
                    // Skip address-0 storage bindings here: the real resolution
                    // path uses a scratch image for those, but this warm-up pass
                    // called ResolveStorageGuestImage directly, which throws on
                    // address 0 and dropped the whole draw (Demon's Souls G-buffer
                    // normals/IDs passes -> lighting had no input -> black).
                    if (texture.IsStorage && texture.Address != 0)
                    {
                        _ = ResolveStorageGuestImage(texture);
                    }
                }

                if (resourcePhaseStartV7405623 != 0)
                {
                    var nowV7405623 = Stopwatch.GetTimestamp();
                    storageTicksV7405623 =
                        nowV7405623 - resourcePhaseLastV7405623;
                    resourcePhaseLastV7405623 = nowV7405623;
                }

                // SHARPEMU_V34_GRAPHICS_MOVIE_PUMP
                // Movie playback must not depend on compute dispatch cadence.
                // Decode/poll immediately before graphics resolves the Y/UV pair.
                PumpHostMovieFrame();
                var hostMovieTextures = FindHostMovieTextureBindings(draw.Textures);
                // SHARPEMU_V74_0_83_TITLE_UI_DRAW_DISCOVERY
                // V81's IsTitleDraw classifier produced zero PRESS_ANY_BUTTON
                // shader hits. Discover the actual overlay draws during the
                // correct loop without replacing guest shaders.
                if (HostMovieBridge.IsTitleLoopCompositeActiveV74081 &&
                    hostMovieTextures.Luma < 0 &&
                    hostMovieTextures.Chroma < 0)
                {
                    var candidateV74083 =
                        Interlocked.Increment(
                            ref _v74083TitleUiCandidateCount);

                    if (candidateV74083 <= 64 ||
                        (candidateV74083 &
                         (candidateV74083 - 1)) == 0)
                    {
                        var vsDigestV74083 =
                            Convert.ToHexString(
                                SHA256.HashData(draw.VertexSpirv).AsSpan(0, 4));
                        var psDigestV74083 =
                            Convert.ToHexString(
                                SHA256.HashData(draw.PixelSpirv).AsSpan(0, 4));

                        Console.Error.WriteLine(
                            "[V74.0.83][TITLE_UI_DRAW_CANDIDATE] " +
                            $"count={candidateV74083} " +
                            $"vs={vsDigestV74083} ps={psDigestV74083} " +
                            $"vertices={draw.VertexCount} " +
                            $"instances={draw.InstanceCount} " +
                            $"attributes={draw.AttributeCount} " +
                            $"textures={draw.Textures.Count} " +
                            $"globals={draw.GlobalMemoryBuffers.Count} " +
                            $"blends={resources.Blends.Length} " +
                            $"viewport={resources.Viewport} " +
                            $"scissor={resources.Scissor}");
                    }
                }
                for (var index = 0; index < draw.Textures.Count; index++)
                {
                    var texture = draw.Textures[index];
                    var resolved = index == hostMovieTextures.Luma
                        ? CreateHostMovieTextureResource(texture, plane: 0)
                        : index == hostMovieTextures.Chroma
                            ? CreateHostMovieTextureResource(texture, plane: 1)
                            : ResolveTextureResource(texture);
                    var feedbackTarget = feedbackTargets?.FirstOrDefault(target =>
                        ReferenceEquals(resolved.GuestImage, target));
                    // ResolveTextureResource may deliberately decline an
                    // address alias when the descriptor is incompatible with
                    // the render-target image. Only snapshot an alias which
                    // actually resolved to the target; a separately uploaded
                    // texture has no Vulkan attachment feedback hazard.
                    resources.Textures[index] =
                        feedbackDepth is not null &&
                        !texture.IsStorage &&
                        ReferenceEquals(resolved.GuestDepth, feedbackDepth)
                            ? CreateDepthFeedbackSnapshot(texture, feedbackDepth)
                            :
                        feedbackTarget is not null &&
                        ReferenceEquals(resolved.GuestImage, feedbackTarget)
                            ? CreateRenderTargetFeedbackSnapshot(texture, feedbackTarget)
                            : resolved;
                }

                if (resourcePhaseStartV7405623 != 0)
                {
                    var nowV7405623 = Stopwatch.GetTimestamp();
                    textureTicksV7405623 =
                        nowV7405623 - resourcePhaseLastV7405623;
                    resourcePhaseLastV7405623 = nowV7405623;
                }

                PrepareGuestBufferAllocations(draw.GlobalMemoryBuffers);
                for (var index = 0; index < draw.GlobalMemoryBuffers.Count; index++)
                {
                    resources.GlobalMemoryBuffers[index] =
                        CreateGlobalBufferResource(draw.GlobalMemoryBuffers[index]);
                }

                if (resourcePhaseStartV7405623 != 0)
                {
                    var nowV7405623 = Stopwatch.GetTimestamp();
                    globalTicksV7405623 =
                        nowV7405623 - resourcePhaseLastV7405623;
                    resourcePhaseLastV7405623 = nowV7405623;
                }

                var sharedVertexResources = new Dictionary<
                    byte[], VertexBufferResource>(
                    System.Collections.Generic.ReferenceEqualityComparer.Instance);
                for (var index = 0; index < draw.VertexBuffers.Count; index++)
                {
                    var guestVertex = draw.VertexBuffers[index];
                    if (sharedVertexResources.TryGetValue(
                            guestVertex.Data,
                            out var sharedVertex))
                    {
                        resources.VertexBuffers[index] =
                            CreateVertexBufferAlias(sharedVertex, guestVertex);
                    }
                    else
                    {
                        var vertexResource =
                            CreateVertexBufferResource(guestVertex);
                        resources.VertexBuffers[index] = vertexResource;
                        sharedVertexResources.Add(guestVertex.Data, vertexResource);
                    }
                }

                if (draw.IndexBuffer is { Length: > 0 } indexBuffer)
                {
                    resources.IndexBuffer = CreateHostBuffer(
                        indexBuffer.Data.AsSpan(0, indexBuffer.Length),
                        BufferUsageFlags.IndexBufferBit,
                        out resources.IndexMemory,
                        out _);
                    resources.Index32Bit = indexBuffer.Is32Bit;
                    if (indexBuffer.Pooled)
                    {
                        GuestDataPool.Shared.Return(indexBuffer.Data);
                    }
                }

                if (resourcePhaseStartV7405623 != 0)
                {
                    var nowV7405623 = Stopwatch.GetTimestamp();
                    vertexTicksV7405623 =
                        nowV7405623 - resourcePhaseLastV7405623;
                    resourcePhaseLastV7405623 = nowV7405623;
                }

                CreateTranslatedDescriptorResources(
                    resources,
                    ShaderStageFlags.VertexBit | ShaderStageFlags.FragmentBit);

                if (resourcePhaseStartV7405623 != 0)
                {
                    var nowV7405623 = Stopwatch.GetTimestamp();
                    descriptorTicksV7405623 =
                        nowV7405623 - resourcePhaseLastV7405623;
                    resourcePhaseLastV7405623 = nowV7405623;
                }

                CreateTranslatedPipeline(
                    resources,
                    vertexSpirv,
                    fragmentSpirv,
                    renderPass,
                    renderTargetFormats,
                    extent);

                if (resourcePhaseStartV7405623 != 0)
                {
                    var nowV7405623 = Stopwatch.GetTimestamp();
                    pipelineTicksV7405623 =
                        nowV7405623 - resourcePhaseLastV7405623;
                    var totalTicksV7405623 =
                        nowV7405623 - resourcePhaseStartV7405623;
                    var totalMsV7405623 =
                        totalTicksV7405623 * 1000.0 /
                        Stopwatch.Frequency;

                    if (totalMsV7405623 >= 20.0)
                    {
                        var traceCountV7405623 =
                            Interlocked.Increment(
                                ref _v7405623DrawResourcePhaseCount);

                        if (traceCountV7405623 <= 512 ||
                            (traceCountV7405623 &
                             (traceCountV7405623 - 1)) == 0)
                        {
                            var targetAddressV7405623 =
                                feedbackTargets is { Count: > 0 }
                                    ? feedbackTargets[0].Address
                                    : 0UL;

                            Console.Error.WriteLine(
                                $"[V74.0.56.23][DRAW_RESOURCE_PHASES] " +
                                $"count={traceCountV7405623} " +
                                $"total_ms={totalMsV7405623:F3} " +
                                $"storage_ms={storageTicksV7405623 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"texture_ms={textureTicksV7405623 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"global_ms={globalTicksV7405623 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"vertex_ms={vertexTicksV7405623 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"descriptor_ms={descriptorTicksV7405623 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"pipeline_ms={pipelineTicksV7405623 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"rt=0x{targetAddressV7405623:X16} " +
                                $"vertex_spirv={vertexSpirv.Length} " +
                                $"pixel_spirv={fragmentSpirv.Length} " +
                                $"textures={draw.Textures.Count} " +
                                $"globals={draw.GlobalMemoryBuffers.Count} " +
                                $"vertices={draw.VertexBuffers.Count} " +
                                $"indexed={(draw.IndexBuffer is null ? 0 : 1)} " +
                                $"pipeline_cached={(resources.PipelineCached ? 1 : 0)}");
                        }
                    }
                }

                return resources;
            }
            catch
            {
                DestroyTranslatedDrawResources(resources);
                throw;
            }
            finally
            {
                var returnedVertexData = new HashSet<byte[]>(
                    System.Collections.Generic.ReferenceEqualityComparer.Instance);
                foreach (var vertex in draw.VertexBuffers)
                {
                    if (vertex.Pooled && returnedVertexData.Add(vertex.Data))
                    {
                        GuestDataPool.Shared.Return(vertex.Data);
                    }
                }
            }
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        private TranslatedDrawResources CreateComputeDispatchResources(
            VulkanComputeGuestDispatch dispatch)
        {
            var traceResources =
                _traceVulkanShaderEnabled &&
                _traceVerboseComputeResources &&
                dispatch.Textures.Count >= 8;
            if (traceResources)
            {
                TraceVulkanShader(
                    $"vk.compute_resources begin groups={dispatch.GroupCountX}x" +
                    $"{dispatch.GroupCountY}x{dispatch.GroupCountZ} textures={dispatch.Textures.Count}");
            }

            var phaseStartV74034 = _traceComputePhasesV74034
                ? Stopwatch.GetTimestamp()
                : 0L;
            var phaseLastV74034 = phaseStartV74034;
            long storageTicksV74034 = 0;
            long textureTicksV74034 = 0;
            long bufferTicksV74034 = 0;
            long descriptorTicksV74034 = 0;
            long pipelineTicksV74034 = 0;

            var resources = new TranslatedDrawResources
            {
                DebugName = BuildComputeDebugName(dispatch),
                Textures = new TextureResource[dispatch.Textures.Count],
                GlobalMemoryBuffers =
                    new GlobalBufferResource[dispatch.GlobalMemoryBuffers.Count],
            };

            try
            {
                for (var index = 0; index < dispatch.Textures.Count; index++)
                {
                    var texture = dispatch.Textures[index];
                    // Address-zero storage descriptors are valid scratch bindings.
                    // ResolveTextureResource creates their transient image below;
                    // pre-resolving them as guest-backed images throws and drops
                    // the entire compute dispatch before that path can run.
                    if (texture.IsStorage && texture.Address != 0)
                    {
                        if (traceResources)
                        {
                            TraceVulkanShader(
                                $"vk.compute_resources storage[{index}] begin " +
                                $"addr=0x{texture.Address:X16} fmt={texture.Format} " +
                                $"size={texture.Width}x{texture.Height} " +
                                $"view_mips={texture.BaseMipLevel}+{texture.MipLevels} " +
                                $"resource_mips={texture.ResourceMipLevels} " +
                                $"relative_level={texture.MipLevel}");
                        }

                        _ = ResolveStorageGuestImage(texture);
                        if (traceResources)
                        {
                            TraceVulkanShader($"vk.compute_resources storage[{index}] ready");
                        }
                    }
                }

                if (phaseStartV74034 != 0)
                {
                    var nowV74034 = Stopwatch.GetTimestamp();
                    storageTicksV74034 = nowV74034 - phaseLastV74034;
                    phaseLastV74034 = nowV74034;
                }

                if (traceResources)
                {
                    TraceVulkanShader("vk.compute_resources resolve begin");
                }

                // SHARPEMU_V73_20_COMPUTE_BINK_YUV_BINDING
                // SHARPEMU_V74_0_6_3_COMPUTE_TEXTURE_RESOLVE_RESTORE
                // V73.20 had this compute mapping loop collapsed behind //.
                var hostMovieTextures = FindHostMovieTextureBindings(dispatch.Textures);
                if (hostMovieTextures.Luma >= 0 && hostMovieTextures.Chroma >= 0)
                {
                    // SHARPEMU_V73_20_COMPUTE_BINK_TRACE
                    if (Interlocked.Increment(ref _v7320ComputeBinkBindingTraceCount) <= 64)
                    {
                        var luma = dispatch.Textures[hostMovieTextures.Luma];
                        var chroma = dispatch.Textures[hostMovieTextures.Chroma];
                        Console.Error.WriteLine(
                            $"[V73.20][BINK] bink2.compute_yuv_binding " +
                            $"y={hostMovieTextures.Luma}:0x{luma.Address:X16}:{luma.Width}x{luma.Height} " +
                            $"uv={hostMovieTextures.Chroma}:0x{chroma.Address:X16}:{chroma.Width}x{chroma.Height} " +
                            $"host={_hostMovieFrameWidth}x{_hostMovieFrameHeight}");
                    }
                }

                for (var index = 0; index < dispatch.Textures.Count; index++)
                {
                    var texture = dispatch.Textures[index];
                    var resolvedTexture =
                        index == hostMovieTextures.Luma
                            ? CreateHostMovieTextureResource(texture, plane: 0)
                            : index == hostMovieTextures.Chroma
                                ? CreateHostMovieTextureResource(texture, plane: 1)
                                : ResolveTextureResource(texture);

                    if (resolvedTexture is null)
                    {
                        throw new InvalidOperationException(
                            $"compute texture resource remained null: " +
                            $"index={index} addr=0x{texture.Address:X16} " +
                            $"size={texture.Width}x{texture.Height} " +
                            $"fmt={texture.Format}/{texture.NumberType} " +
                            $"storage={(texture.IsStorage ? 1 : 0)}");
                    }

                    resources.Textures[index] = resolvedTexture;
                }

                if (phaseStartV74034 != 0)
                {
                    var nowV74034 = Stopwatch.GetTimestamp();
                    textureTicksV74034 = nowV74034 - phaseLastV74034;
                    phaseLastV74034 = nowV74034;
                }

                if (traceResources)
                {
                    TraceVulkanShader("vk.compute_resources resolve ready");
                }

                PrepareGuestBufferAllocations(dispatch.GlobalMemoryBuffers);
                for (var index = 0; index < dispatch.GlobalMemoryBuffers.Count; index++)
                {
                    resources.GlobalMemoryBuffers[index] =
                        CreateGlobalBufferResource(dispatch.GlobalMemoryBuffers[index]);
                }

                if (phaseStartV74034 != 0)
                {
                    var nowV74034 = Stopwatch.GetTimestamp();
                    bufferTicksV74034 = nowV74034 - phaseLastV74034;
                    phaseLastV74034 = nowV74034;
                }

                if (traceResources)
                {
                    TraceVulkanShader("vk.compute_resources descriptors begin");
                }

                CreateTranslatedDescriptorResources(resources, ShaderStageFlags.ComputeBit);
                if (phaseStartV74034 != 0)
                {
                    var nowV74034 = Stopwatch.GetTimestamp();
                    descriptorTicksV74034 = nowV74034 - phaseLastV74034;
                    phaseLastV74034 = nowV74034;
                }
                if (traceResources)
                {
                    TraceVulkanShader("vk.compute_resources descriptors ready");
                }

                if (traceResources)
                {
                    TraceVulkanShader(
                        $"vk.compute_resources pipeline begin " +
                        $"cs=0x{dispatch.ShaderAddress:X16} " +
                        $"spirv={dispatch.ComputeSpirv.Length} " +
                        $"textures={resources.Textures.Length} " +
                        $"globals={resources.GlobalMemoryBuffers.Length}");
                }

                CreateComputePipeline(resources, dispatch.ComputeSpirv);
                if (phaseStartV74034 != 0)
                {
                    var nowV74034 = Stopwatch.GetTimestamp();
                    pipelineTicksV74034 = nowV74034 - phaseLastV74034;
                    var totalTicksV74034 = nowV74034 - phaseStartV74034;
                    var totalMsV74034 =
                        totalTicksV74034 * 1000.0 / Stopwatch.Frequency;
                    if (totalMsV74034 >= 10.0)
                    {
                        var phaseTraceV74034 = Interlocked.Increment(
                            ref _v74034ComputeResourcePhaseTraceCount);
                        if (phaseTraceV74034 <= 128 ||
                            (phaseTraceV74034 & (phaseTraceV74034 - 1)) == 0)
                        {
                            Console.Error.WriteLine(
                                $"[V74.0.34][COMPUTE_RESOURCE_PHASES] " +
                                $"count={phaseTraceV74034} " +
                                $"cs=0x{dispatch.ShaderAddress:X16} " +
                                $"groups={dispatch.GroupCountX}x{dispatch.GroupCountY}x{dispatch.GroupCountZ} " +
                                $"textures={dispatch.Textures.Count} " +
                                $"globals={dispatch.GlobalMemoryBuffers.Count} " +
                                $"total_ms={totalMsV74034:F3} " +
                                $"storage_ms={storageTicksV74034 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"texture_ms={textureTicksV74034 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"buffer_ms={bufferTicksV74034 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"descriptor_ms={descriptorTicksV74034 * 1000.0 / Stopwatch.Frequency:F3} " +
                                $"pipeline_ms={pipelineTicksV74034 * 1000.0 / Stopwatch.Frequency:F3}");
                        }
                    }
                }
                if (traceResources)
                {
                    TraceVulkanShader("vk.compute_resources pipeline ready");
                }

                return resources;
            }
            catch
            {
                DestroyTranslatedDrawResources(resources);
                throw;
            }
        }

        private static bool TryCompileFullscreenVertexShader(
            uint attributeCount,
            out byte[] spirv,
            out string error)
        {
            spirv = [];
            error = string.Empty;
            if (attributeCount > 32)
            {
                error = $"too many interpolated attributes: {attributeCount}";
                return false;
            }

            spirv = SpirvFixedShaders.CreateFullscreenVertex(attributeCount);
            return true;
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        private void CreateTranslatedDescriptorResources(
            TranslatedDrawResources resources,
            ShaderStageFlags stageFlags)
        {
            var textureCount = resources.Textures.Length;
            var sampledImageCount = resources.Textures.Count(texture => !texture.IsStorage);
            var storageImageCount = textureCount - sampledImageCount;
            var globalBufferCount = resources.GlobalMemoryBuffers.Length;
            var bindingCount = textureCount + (globalBufferCount == 0 ? 0 : 1);
            var layout = GetOrCreateDescriptorLayout(resources, stageFlags, bindingCount);
            resources.DescriptorSetLayout = layout.DescriptorSetLayout;
            resources.PipelineLayout = layout.PipelineLayout;
            resources.DescriptorLayoutCached = true;
            if (bindingCount == 0)
            {
                return;
            }

            var setLayout = layout.DescriptorSetLayout;

            var poolSizes = new DescriptorPoolSize[
                (sampledImageCount == 0 ? 0 : 1) +
                (storageImageCount == 0 ? 0 : 1) +
                (globalBufferCount == 0 ? 0 : 1)];
            var poolSizeIndex = 0;
            if (sampledImageCount != 0)
            {
                poolSizes[poolSizeIndex++] = new DescriptorPoolSize
                {
                    Type = DescriptorType.CombinedImageSampler,
                    DescriptorCount = (uint)sampledImageCount,
                };
            }

            if (storageImageCount != 0)
            {
                poolSizes[poolSizeIndex++] = new DescriptorPoolSize
                {
                    Type = DescriptorType.StorageImage,
                    DescriptorCount = (uint)storageImageCount,
                };
            }

            if (globalBufferCount != 0)
            {
                poolSizes[poolSizeIndex] = new DescriptorPoolSize
                {
                    Type = DescriptorType.StorageBuffer,
                    DescriptorCount = (uint)globalBufferCount,
                };
            }

            if (_recycledDescriptorPools.TryPop(out var recycledPool))
            {
                Check(
                    _vk.ResetDescriptorPool(_device, recycledPool, 0),
                    "vkResetDescriptorPool");
                resources.DescriptorPool = recycledPool;
            }
            else
            {
                // Generously sized so any draw's set fits, making the pool
                // recyclable regardless of the draw's binding mix. AAA titles
                // (e.g. Demon's Souls) bind well over 32 textures in a single
                // descriptor set, so the sampled-image budget in particular
                // must be large enough to avoid a per-draw dynamic fallback.
                var genericPoolSizes = stackalloc DescriptorPoolSize[3];
                genericPoolSizes[0] = new DescriptorPoolSize
                {
                    Type = DescriptorType.CombinedImageSampler,
                    DescriptorCount = 256,
                };
                genericPoolSizes[1] = new DescriptorPoolSize
                {
                    Type = DescriptorType.StorageImage,
                    DescriptorCount = 64,
                };
                genericPoolSizes[2] = new DescriptorPoolSize
                {
                    Type = DescriptorType.StorageBuffer,
                    DescriptorCount = 64,
                };
                var poolInfo = new DescriptorPoolCreateInfo
                {
                    SType = StructureType.DescriptorPoolCreateInfo,
                    MaxSets = 1,
                    PoolSizeCount = 3,
                    PPoolSizes = genericPoolSizes,
                };
                DescriptorPool descriptorPool;
                Check(
                    _vk.CreateDescriptorPool(
                        _device,
                        &poolInfo,
                        null,
                        out descriptorPool),
                    "vkCreateDescriptorPool");
                resources.DescriptorPool = descriptorPool;
            }

            var allocateInfo = new DescriptorSetAllocateInfo
            {
                SType = StructureType.DescriptorSetAllocateInfo,
                DescriptorPool = resources.DescriptorPool,
                DescriptorSetCount = 1,
                PSetLayouts = &setLayout,
            };
            DescriptorSet descriptorSet;
            Check(
                _vk.AllocateDescriptorSets(_device, &allocateInfo, out descriptorSet),
                "vkAllocateDescriptorSets");
            resources.DescriptorSet = descriptorSet;

            var imageInfos = new DescriptorImageInfo[textureCount];
            var bufferInfos = new DescriptorBufferInfo[globalBufferCount];
            var writes = new WriteDescriptorSet[bindingCount];
            fixed (DescriptorImageInfo* imageInfoPointer = imageInfos)
            fixed (DescriptorBufferInfo* bufferInfoPointer = bufferInfos)
            fixed (WriteDescriptorSet* writePointer = writes)
            {
                var writeIndex = 0;
                if (globalBufferCount != 0)
                {
                    for (var index = 0; index < globalBufferCount; index++)
                    {
                        bufferInfoPointer[index] = new DescriptorBufferInfo
                        {
                            Buffer = resources.GlobalMemoryBuffers[index].Buffer,
                            Offset = resources.GlobalMemoryBuffers[index].Offset,
                            Range = resources.GlobalMemoryBuffers[index].Size,
                        };
                    }

                    writePointer[writeIndex++] = new WriteDescriptorSet
                    {
                        SType = StructureType.WriteDescriptorSet,
                        DstSet = resources.DescriptorSet,
                        DstBinding = 0,
                        DescriptorCount = (uint)globalBufferCount,
                        DescriptorType = DescriptorType.StorageBuffer,
                        PBufferInfo = bufferInfoPointer,
                    };
                }

                for (var index = 0; index < textureCount; index++)
                {
                    var isStorage = resources.Textures[index].IsStorage;
                    if (!isStorage &&
                        resources.Textures[index].Sampler.Handle == 0)
                    {
                        resources.Textures[index].Sampler =
                            CreateSampler(resources.Textures[index].SamplerState);
                    }

                    imageInfoPointer[index] = new DescriptorImageInfo
                    {
                        Sampler = isStorage ? default : resources.Textures[index].Sampler,
                        ImageView = resources.Textures[index].View,
                        ImageLayout = isStorage ||
                            resources.Textures[index].GuestImage is { } guestImage &&
                            resources.Textures.Any(
                                texture =>
                                    texture.IsStorage &&
                                    texture.GuestImage == guestImage)
                                ? ImageLayout.General
                                : ImageLayout.ShaderReadOnlyOptimal,
                    };
                    writePointer[writeIndex++] = new WriteDescriptorSet
                    {
                        SType = StructureType.WriteDescriptorSet,
                        DstSet = resources.DescriptorSet,
                        DstBinding = (uint)(index + 1),
                        DescriptorCount = 1,
                        DescriptorType = isStorage
                            ? DescriptorType.StorageImage
                            : DescriptorType.CombinedImageSampler,
                        PImageInfo = &imageInfoPointer[index],
                    };
                }

                _vk.UpdateDescriptorSets(
                    _device,
                    (uint)bindingCount,
                    writePointer,
                    0,
                    null);
            }
        }

        private void CreateTranslatedPipeline(
            TranslatedDrawResources resources,
            byte[] vertexSpirv,
            byte[] fragmentSpirv,
            RenderPass renderPass,
            IReadOnlyList<Format> renderTargetFormats,
            Extent2D extent)
        {
            var pipelineKey = new GraphicsPipelineKey(
                GetShaderDigest(vertexSpirv),
                GetShaderDigest(fragmentSpirv),
                string.Join(',', renderTargetFormats.Select(format => (uint)format)),
                resources.HasDepthAttachment,
                resources.Topology,
                string.Join(';', resources.Blends.Select(blend =>
                    $"{(blend.Enable ? 1 : 0)}:{blend.ColorSrcFactor}:{blend.ColorDstFactor}:" +
                    $"{blend.ColorFunc}:{blend.AlphaSrcFactor}:{blend.AlphaDstFactor}:" +
                    $"{blend.AlphaFunc}:{(blend.SeparateAlphaBlend ? 1 : 0)}:{blend.WriteMask}")),
                GetResourceLayoutKey(resources),
                GetVertexLayoutKey(resources),
                resources.Raster,
                resources.HasDepthAttachment ? resources.Depth : GuestDepthState.Default);
            if (_graphicsPipelines.TryGetValue(pipelineKey, out var cachedPipeline))
            {
                resources.Pipeline = cachedPipeline;
                resources.PipelineCached = true;
                return;
            }

            var pipelineCreateStartV74030 = _traceShaderPipelineTimingV74030
                ? Stopwatch.GetTimestamp()
                : 0L;
            var vertexModule = CreateShaderModule(vertexSpirv);
            var fragmentModule = CreateShaderModule(fragmentSpirv);
            var entryPoint = (byte*)SilkMarshal.StringToPtr("main");
            try
            {
                var shaderStages = stackalloc PipelineShaderStageCreateInfo[2];
                shaderStages[0] = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.VertexBit,
                    Module = vertexModule,
                    PName = entryPoint,
                };
                shaderStages[1] = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.FragmentBit,
                    Module = fragmentModule,
                    PName = entryPoint,
                };

                // One Vulkan binding per unique host buffer and input rate
                // (fetch_index). Attributes share that binding with
                // Offset = OffsetBytes.
                var bindingByBuffer = new Dictionary<(ulong Handle, bool PerInstance), uint>();
                var vertexBindingList = new List<VertexInputBindingDescription>();
                var vertexAttributeDescriptions =
                    new VertexInputAttributeDescription[resources.VertexBuffers.Length];
                for (var index = 0; index < resources.VertexBuffers.Length; index++)
                {
                    var vertexBuffer = resources.VertexBuffers[index];
                    var bufferKey = (vertexBuffer.Buffer.Handle, vertexBuffer.PerInstance);
                    if (!bindingByBuffer.TryGetValue(bufferKey, out var bindingIndex))
                    {
                        bindingIndex = (uint)vertexBindingList.Count;
                        bindingByBuffer[bufferKey] = bindingIndex;
                        vertexBindingList.Add(new VertexInputBindingDescription
                        {
                            Binding = bindingIndex,
                            Stride = vertexBuffer.Stride == 0
                                ? Math.Max(vertexBuffer.ComponentCount, 1) * sizeof(float)
                                : vertexBuffer.Stride,
                            InputRate = vertexBuffer.PerInstance
                                ? VertexInputRate.Instance
                                : VertexInputRate.Vertex,
                        });
                    }

                    vertexAttributeDescriptions[index] = new VertexInputAttributeDescription
                    {
                        Location = vertexBuffer.Location,
                        Binding = bindingIndex,
                        Format = ToVkVertexFormat(
                            vertexBuffer.DataFormat,
                            vertexBuffer.NumberFormat,
                            vertexBuffer.ComponentCount),
                        Offset = vertexBuffer.OffsetBytes,
                    };
                }

                var vertexBindingDescriptions = vertexBindingList.ToArray();

                fixed (VertexInputBindingDescription* vertexBindingPointerBase = vertexBindingDescriptions)
                fixed (VertexInputAttributeDescription* vertexAttributePointerBase = vertexAttributeDescriptions)
                {
                    var vertexInput = new PipelineVertexInputStateCreateInfo
                    {
                        SType = StructureType.PipelineVertexInputStateCreateInfo,
                        VertexBindingDescriptionCount = (uint)vertexBindingDescriptions.Length,
                        PVertexBindingDescriptions = vertexBindingDescriptions.Length == 0
                            ? null
                            : vertexBindingPointerBase,
                        VertexAttributeDescriptionCount = (uint)vertexAttributeDescriptions.Length,
                        PVertexAttributeDescriptions = vertexAttributeDescriptions.Length == 0
                            ? null
                            : vertexAttributePointerBase,
                    };
                    var inputAssembly = new PipelineInputAssemblyStateCreateInfo
                    {
                        SType = StructureType.PipelineInputAssemblyStateCreateInfo,
                        Topology = resources.Topology,
                        // Metal always applies primitive restart to strip/fan
                        // topologies with the max index as the cut value, so
                        // match that here. Enabling it for lists is what makes
                        // MoltenVK warn ("Metal does not support disabling
                        // primitive restart"); lists never carry a restart
                        // index, so leaving it off for them is both correct
                        // and warning-free.
                        PrimitiveRestartEnable = RequiresPrimitiveRestart(resources.Topology),
                    };
                    var viewport = new Viewport(0, 0, extent.Width, extent.Height, 0, 1);
                    var scissor = new Rect2D(new Offset2D(0, 0), extent);
                    var viewportState = new PipelineViewportStateCreateInfo
                    {
                        SType = StructureType.PipelineViewportStateCreateInfo,
                        ViewportCount = 1,
                        PViewports = &viewport,
                        ScissorCount = 1,
                        PScissors = &scissor,
                    };
                    var raster = resources.Raster;
                    var cullMode = CullModeFlags.None;
                    if (raster.CullFront)
                    {
                        cullMode |= CullModeFlags.FrontBit;
                    }

                    if (raster.CullBack)
                    {
                        cullMode |= CullModeFlags.BackBit;
                    }

                    var rasterization = new PipelineRasterizationStateCreateInfo
                    {
                        SType = StructureType.PipelineRasterizationStateCreateInfo,
                        // Wireframe (PolygonMode.Line) needs the fillModeNonSolid
                        // device feature and is effectively unused by shipping
                        // titles, so fall back to a solid fill.
                        PolygonMode = PolygonMode.Fill,
                        CullMode = cullMode,
                        FrontFace = raster.FrontFaceClockwise
                            ? FrontFace.Clockwise
                            : FrontFace.CounterClockwise,
                        LineWidth = 1,
                    };
                    var multisample = new PipelineMultisampleStateCreateInfo
                    {
                        SType = StructureType.PipelineMultisampleStateCreateInfo,
                        RasterizationSamples = SampleCountFlags.Count1Bit,
                    };
                    var colorBlendAttachments = stackalloc PipelineColorBlendAttachmentState[resources.Blends.Length];
                    for (var index = 0; index < resources.Blends.Length; index++)
                    {
                        var blend = resources.Blends[index];
                        colorBlendAttachments[index] = new PipelineColorBlendAttachmentState
                        {
                            BlendEnable = blend.Enable &&
                                IsBlendableFormat(renderTargetFormats[index]),
                            SrcColorBlendFactor = ToVkBlendFactor(blend.ColorSrcFactor),
                            DstColorBlendFactor = ToVkBlendFactor(blend.ColorDstFactor),
                            ColorBlendOp = ToVkBlendOp(blend.ColorFunc),
                            SrcAlphaBlendFactor = blend.SeparateAlphaBlend
                                ? ToVkBlendFactor(blend.AlphaSrcFactor)
                                : ToVkBlendFactor(blend.ColorSrcFactor),
                            DstAlphaBlendFactor = blend.SeparateAlphaBlend
                                ? ToVkBlendFactor(blend.AlphaDstFactor)
                                : ToVkBlendFactor(blend.ColorDstFactor),
                            AlphaBlendOp = blend.SeparateAlphaBlend
                                ? ToVkBlendOp(blend.AlphaFunc)
                                : ToVkBlendOp(blend.ColorFunc),
                            ColorWriteMask = ToVkColorWriteMask(blend.WriteMask),
                        };
                    }
                    var colorBlend = new PipelineColorBlendStateCreateInfo
                    {
                        SType = StructureType.PipelineColorBlendStateCreateInfo,
                        AttachmentCount = (uint)resources.Blends.Length,
                        PAttachments = colorBlendAttachments,
                    };
                    var dynamicStateValues = stackalloc DynamicState[3];
                    dynamicStateValues[0] = DynamicState.Viewport;
                    dynamicStateValues[1] = DynamicState.Scissor;
                    // CB_BLEND_RED..ALPHA vary per draw without a pipeline
                    // identity change, so the constant stays dynamic.
                    dynamicStateValues[2] = DynamicState.BlendConstants;
                    var dynamicState = new PipelineDynamicStateCreateInfo
                    {
                        SType = StructureType.PipelineDynamicStateCreateInfo,
                        DynamicStateCount = 3,
                        PDynamicStates = dynamicStateValues,
                    };
                    var depth = resources.Depth;
                    var depthStencil = new PipelineDepthStencilStateCreateInfo
                    {
                        SType = StructureType.PipelineDepthStencilStateCreateInfo,
                        DepthTestEnable = depth.TestEnable,
                        DepthWriteEnable = depth.WriteEnable,
                        DepthCompareOp = ToVkCompareOp(depth.CompareOp),
                        DepthBoundsTestEnable = false,
                        StencilTestEnable = false,
                    };
                    var pipelineInfo = new GraphicsPipelineCreateInfo
                    {
                        SType = StructureType.GraphicsPipelineCreateInfo,
                        StageCount = 2,
                        PStages = shaderStages,
                        PVertexInputState = &vertexInput,
                        PInputAssemblyState = &inputAssembly,
                        PViewportState = &viewportState,
                        PRasterizationState = &rasterization,
                        PMultisampleState = &multisample,
                        PColorBlendState = &colorBlend,
                        PDepthStencilState = resources.HasDepthAttachment ? &depthStencil : null,
                        PDynamicState = &dynamicState,
                        Layout = resources.PipelineLayout,
                        RenderPass = renderPass,
                        Subpass = 0,
                    };
                    Pipeline pipeline;
                    Check(
                        _vk.CreateGraphicsPipelines(
                            _device,
                            _pipelineCache,
                            1,
                            &pipelineInfo,
                        null,
                        out pipeline),
                    "vkCreateGraphicsPipelines(translated)");
                    MarkPipelineCacheDirty();
                    resources.Pipeline = pipeline;
                    if (_graphicsPipelines.Count < MaxGraphicsPipelineCacheEntries)
                    {
                        resources.PipelineCached = true;
                        _graphicsPipelines.Add(pipelineKey, pipeline);
                    }
                    else
                    {
                        // DestroyTranslatedDrawResources retires this pipeline
                        // with the draw fence because it is not cache-owned.
                        resources.PipelineCached = false;
                    }
                    Interlocked.Increment(ref _perfPipelineCreations);
                    SetDebugName(
                        ObjectType.Pipeline,
                        pipeline.Handle,
                        $"SharpEmu graphics ps={fragmentSpirv.Length}b attrs={resources.Textures.Length}");
                }
            }
            finally
            {
                SilkMarshal.Free((nint)entryPoint);
                _vk.DestroyShaderModule(_device, fragmentModule, null);
                _vk.DestroyShaderModule(_device, vertexModule, null);
                if (_traceShaderPipelineTimingV74030 && pipelineCreateStartV74030 != 0)
                {
                    var elapsedMsV74030 = (Stopwatch.GetTimestamp() - pipelineCreateStartV74030) *
                        1000.0 / Stopwatch.Frequency;
                    if (elapsedMsV74030 >= 25.0)
                    {
                        var traceCountV74030 = Interlocked.Increment(
                            ref _pipelineCreateSlowTraceCountV74030);
                        Console.Error.WriteLine(
                            $"[V74.0.30][PIPELINE_CREATE_SLOW] count={traceCountV74030} " +
                            $"stage=graphics ms={elapsedMsV74030:F3} " +
                            $"vs_bytes={vertexSpirv.Length} ps_bytes={fragmentSpirv.Length} " +
                            $"rt_count={renderTargetFormats.Count}");
                    }
                }
            }
        }

        private DescriptorLayoutBundle GetOrCreateDescriptorLayout(
            TranslatedDrawResources resources,
            ShaderStageFlags stageFlags,
            int bindingCount)
        {
            var key = new DescriptorLayoutKey(stageFlags, GetResourceLayoutKey(resources));
            if (_descriptorLayouts.TryGetValue(key, out var cached))
            {
                return cached;
            }

            DescriptorSetLayout descriptorSetLayout = default;
            if (bindingCount != 0)
            {
                var bindings = new DescriptorSetLayoutBinding[bindingCount];
                var bindingOffset = 0;
                if (resources.GlobalMemoryBuffers.Length != 0)
                {
                    bindings[bindingOffset++] = new DescriptorSetLayoutBinding
                    {
                        Binding = 0,
                        DescriptorType = DescriptorType.StorageBuffer,
                        DescriptorCount = (uint)resources.GlobalMemoryBuffers.Length,
                        StageFlags = stageFlags,
                    };
                }

                for (var index = 0; index < resources.Textures.Length; index++)
                {
                    bindings[bindingOffset + index] = new DescriptorSetLayoutBinding
                    {
                        Binding = (uint)(index + 1),
                        DescriptorType = resources.Textures[index].IsStorage
                            ? DescriptorType.StorageImage
                            : DescriptorType.CombinedImageSampler,
                        DescriptorCount = 1,
                        StageFlags = stageFlags,
                    };
                }

                fixed (DescriptorSetLayoutBinding* bindingPointer = bindings)
                {
                    var descriptorInfo = new DescriptorSetLayoutCreateInfo
                    {
                        SType = StructureType.DescriptorSetLayoutCreateInfo,
                        BindingCount = (uint)bindings.Length,
                        PBindings = bindingPointer,
                    };
                    Check(
                        _vk.CreateDescriptorSetLayout(
                            _device,
                            &descriptorInfo,
                            null,
                            out descriptorSetLayout),
                        "vkCreateDescriptorSetLayout");
                }
            }

            var pipelineInfo = new PipelineLayoutCreateInfo
            {
                SType = StructureType.PipelineLayoutCreateInfo,
            };
            if (descriptorSetLayout.Handle != 0)
            {
                pipelineInfo.SetLayoutCount = 1;
                pipelineInfo.PSetLayouts = &descriptorSetLayout;
            }

            var computePushConstantRange = new PushConstantRange
            {
                StageFlags = ShaderStageFlags.ComputeBit,
                Offset = 0,
                Size = 3 * sizeof(uint),
            };
            if ((stageFlags & ShaderStageFlags.ComputeBit) != 0)
            {
                pipelineInfo.PushConstantRangeCount = 1;
                pipelineInfo.PPushConstantRanges = &computePushConstantRange;
            }

            PipelineLayout pipelineLayout;
            Check(
                _vk.CreatePipelineLayout(
                    _device,
                    &pipelineInfo,
                    null,
                    out pipelineLayout),
                "vkCreatePipelineLayout");
            var created = new DescriptorLayoutBundle(descriptorSetLayout, pipelineLayout);
            _descriptorLayouts.Add(key, created);
            return created;
        }

        private string GetShaderDigest(byte[] spirv)
        {
            if (_shaderDigests.TryGetValue(spirv, out var digest))
            {
                return digest;
            }

            digest = Convert.ToHexString(SHA256.HashData(spirv));
            _shaderDigests.Add(spirv, digest);
            return digest;
        }

        private static string GetResourceLayoutKey(TranslatedDrawResources resources) =>
            resources.ResourceLayoutKey ??= BuildResourceLayoutKey(resources);

        private static string GetVertexLayoutKey(TranslatedDrawResources resources) =>
            resources.VertexLayoutKey ??= BuildVertexLayoutKey(resources);

        private static string BuildResourceLayoutKey(TranslatedDrawResources resources)
        {
            var key = new StringBuilder();
            key.Append(resources.GlobalMemoryBuffers.Length).Append(':');
            foreach (var texture in resources.Textures)
            {
                key.Append(texture.IsStorage ? 'S' : 'T');
            }

            return key.ToString();
        }

        private static string BuildVertexLayoutKey(TranslatedDrawResources resources)
        {
            var key = new StringBuilder();
            foreach (var buffer in resources.VertexBuffers)
            {
                key.Append(buffer.Location).Append(',')
                    .Append(buffer.ComponentCount).Append(',')
                    .Append(buffer.DataFormat).Append(',')
                    .Append(buffer.NumberFormat).Append(',')
                    .Append(buffer.Stride == 0
                        ? Math.Max(buffer.ComponentCount, 1) * sizeof(float)
                        : buffer.Stride)
                    .Append(';');
            }

            return key.ToString();
        }

        [MethodImpl(MethodImplOptions.NoInlining)]
        private void CreateComputePipeline(
            TranslatedDrawResources resources,
            byte[] computeSpirv)
        {
            var pipelineKey = new ComputePipelineKey(
                GetShaderDigest(computeSpirv),
                GetResourceLayoutKey(resources));
            if (_computePipelines.TryGetValue(pipelineKey, out var cachedPipeline))
            {
                resources.Pipeline = cachedPipeline;
                resources.PipelineCached = true;
                return;
            }

            var pipelineCreateStartV74030 = _traceShaderPipelineTimingV74030
                ? Stopwatch.GetTimestamp()
                : 0L;
            var computeModule = CreateShaderModule(computeSpirv);
            var entryPoint = (byte*)SilkMarshal.StringToPtr("main");
            try
            {
                var stage = new PipelineShaderStageCreateInfo
                {
                    SType = StructureType.PipelineShaderStageCreateInfo,
                    Stage = ShaderStageFlags.ComputeBit,
                    Module = computeModule,
                    PName = entryPoint,
                };
                var pipelineInfo = new ComputePipelineCreateInfo
                {
                    SType = StructureType.ComputePipelineCreateInfo,
                    Flags = PipelineCreateFlags.CreateDispatchBaseBit,
                    Stage = stage,
                    Layout = resources.PipelineLayout,
                };
                Pipeline pipeline;
                Check(
                    _vk.CreateComputePipelines(
                        _device,
                        _pipelineCache,
                        1,
                        &pipelineInfo,
                        null,
                        out pipeline),
                    "vkCreateComputePipelines(translated)");
                MarkPipelineCacheDirty();
                resources.Pipeline = pipeline;
                if (_computePipelines.Count < MaxComputePipelineCacheEntries)
                {
                    resources.PipelineCached = true;
                    _computePipelines.Add(pipelineKey, pipeline);
                }
                else
                {
                    resources.PipelineCached = false;
                }
                SetDebugName(
                    ObjectType.Pipeline,
                    pipeline.Handle,
                    $"SharpEmu compute cs={computeSpirv.Length}b");
            }
            finally
            {
                SilkMarshal.Free((nint)entryPoint);
                _vk.DestroyShaderModule(_device, computeModule, null);
                if (_traceShaderPipelineTimingV74030 && pipelineCreateStartV74030 != 0)
                {
                    var elapsedMsV74030 = (Stopwatch.GetTimestamp() - pipelineCreateStartV74030) *
                        1000.0 / Stopwatch.Frequency;
                    if (elapsedMsV74030 >= 25.0)
                    {
                        var traceCountV74030 = Interlocked.Increment(
                            ref _pipelineCreateSlowTraceCountV74030);
                        Console.Error.WriteLine(
                            $"[V74.0.30][PIPELINE_CREATE_SLOW] count={traceCountV74030} " +
                            $"stage=compute ms={elapsedMsV74030:F3} cs_bytes={computeSpirv.Length}");
                    }
                }
            }
        }

        private void PumpHostMovieFrame()
        {
            // SHARPEMU_V74_0_83_ACTIVE_MOVIE_RECONCILE
            // A RAD movie produces no decoded BGRA frame for this pump. Clear
            // any previous internal-loop frame as soon as bridge ownership
            // changes, otherwise stale logo_intro_loop pixels can trigger the
            // descriptorless exclusive fallback while logo_intro is active.
            var activeBridgeMovieV74083 =
                HostMovieBridge.ActiveMoviePathV74083;
            if (!string.IsNullOrWhiteSpace(_hostMovieFramePath) &&
                !string.Equals(
                    _hostMovieFramePath,
                    activeBridgeMovieV74083,
                    StringComparison.OrdinalIgnoreCase))
            {
                var stalePathV74083 = _hostMovieFramePath;

                ReleaseNaturalBinkDescriptorlessDirectFallback(
                    "active-host-movie-changed-v83");
                ClearTitleLoopCompositeBindingV74081();

                _hostMovieFrameWidth = 0;
                _hostMovieFrameHeight = 0;
                _hostMovieFrameSerial = -1;
                _v74011DirectFallbackPresentedFrameSerial = -1;

                var resetCountV74083 =
                    Interlocked.Increment(
                        ref _v74083StaleMovieStateResetCount);

                Console.Error.WriteLine(
                    "[V74.0.83][STALE_BINK_RESET] " +
                    $"count={resetCountV74083} " +
                    $"stale='{Path.GetFileName(stalePathV74083)}' " +
                    $"active='{Path.GetFileName(activeBridgeMovieV74083)}' " +
                    "fallback=False yuv_bindings=cleared");
            }
            // SHARPEMU_V74_0_82_TITLE_LOOP_30FPS_PUMP
            // The title movie is 30 fps. V34 already pumps it from the graphics
            // texture-resolution boundary, and compute/present paths can also
            // call this method. Cap all title-loop callers to the movie cadence
            // so decoder locks/catch-up work are not repeated several times for
            // the same movie frame.
            if (HostMovieBridge.IsTitleLoopCompositeActiveV74081 &&
                _hostMovieFramePixels is not null)
            {
                var nowV74082 = Stopwatch.GetTimestamp();
                var lastV74082 =
                    Volatile.Read(ref _v74082TitleLoopPumpTick);
                var minimumTicksV74082 =
                    Math.Max(1L, Stopwatch.Frequency / 30);

                if (lastV74082 != 0 &&
                    nowV74082 >= lastV74082 &&
                    nowV74082 - lastV74082 < minimumTicksV74082)
                {
                    var skippedV74082 =
                        Interlocked.Increment(
                            ref _v74082TitleLoopPumpSkipCount);

                    if (skippedV74082 <= 8 ||
                        (skippedV74082 &
                         (skippedV74082 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            "[V74.0.82.2][TITLE_LOOP_PUMP_THROTTLE] " +
                            $"skipped={skippedV74082} " +
                            "cap_fps=30");
                    }

                    return;
                }

                Volatile.Write(
                    ref _v74082TitleLoopPumpTick,
                    nowV74082);
            }
            // SHARPEMU_V74_0_81_TITLE_LOOP_BINDING_LIFETIME
            // Do not consume the guest's button event. Once the title movie has
            // actually been sampled, loss of its Y/UV bindings for 20 seconds
            // means the guest moved to a different composition state. This is
            // deliberately longer than a 0.1-fps debug frame so slow emulation
            // cannot accidentally terminate the loop.
            if (HostMovieBridge.IsTitleLoopCompositeActiveV74081 &&
                _v74081TitleLoopBindingSeen &&
                Stopwatch.GetElapsedTime(
                    _v74081TitleLoopLastBindingTick).TotalSeconds >= 20.0)
            {
                if (HostMovieBridge.StopTitleLoopCompositeV74081(
                        "no-title-yuv-bindings-20s"))
                {
                    ClearTitleLoopCompositeBindingV74081();
                    return;
                }
            }
            // [V61.13.10][DIRECT_PRESENT_SINGLE_CONSUMER]
            // The auto-boot direct decoder already drives Submit(BGRA). A second
            // TryDecodeNextFrame consumer was joining around serial 92/178,
            // producing the visible "plays a few seconds then restarts" symptom.
            if (_binkDirectPresentOnly && HostMovieBridge.IsDirectPresentationActive)
            {
                return;
            }
            // [V61.13.9][BINK_WALLCLOCK_PUMP]
            TryCompleteExpiredBinkWallClockSession();
            // [V67.1.3][BINK_HARNESS_PUMP]
            BinkIntroHarnessTrace.Event("PRESENTER_PUMP");
            if (!HostMovieBridge.TryDecodeNextFrame(
                    // [V61.13.6][BINK_REALTIME_CLOCK]
                    advanceClock: _binkRealtimeClock ||
                                  _naturalBinkDescriptorlessDirectFallbackActive ||
                                  (_hostMovieLumaTextureAddress != 0 &&
                                   _hostMovieChromaTextureAddress != 0),
                    out var pixels,
                    out var width,
                    out var height,
                    out var advanced,
                    out var frameSerial,
                    out var hostPath))
            {
                BinkIntroHarnessTrace.Event("PRESENTER_DECODE_MISS");

                // SHARPEMU_V74_0_12_BINK_COMPLETION_VISUAL_RELEASE
                // V74.0.11 kept the last exclusive fallback frame forever after
                // HostMovieBridge finished the movie. That hides any guest UI
                // that becomes ready immediately after the startup cinematic.
                if (_naturalBinkDescriptorlessDirectFallbackActive &&
                    !HostMovieBridge.IsHostPlaybackActive)
                {
                    ReleaseNaturalBinkDescriptorlessDirectFallback(
                        "host-playback-completed");
                    _hostMovieFramePixels = null;
                    _hostMovieFrameWidth = 0;
                    _hostMovieFrameHeight = 0;
                    _hostMovieFrameSerial = -1;
                    _hostMovieLumaTextureAddress = 0;
                    _hostMovieChromaTextureAddress = 0;
                }

                // Keep the last decoded image while a movie is still active and
                // temporarily has no replacement. Completed movies are handled
                // above so exclusive ownership cannot mask the frontend.
                return;
            }

            if (!string.Equals(
                    _hostMovieFramePath,
                    hostPath,
                    StringComparison.OrdinalIgnoreCase))
            {
                _hostMovieFramePath = hostPath;
                _v74011DirectFallbackPresentedFrameSerial = -1;

                // [V61.13.8.2][BINK_SESSION_PATH]
                if (!string.Equals(
                        _binkSessionPath,
                        hostPath,
                        StringComparison.OrdinalIgnoreCase))
                {
                    if (_binkSessionActive)
                    {
                        BinkHostPlaybackAssist.EndMovieSession(_binkSessionPath);
                    }

                    _binkSessionPath = hostPath;
                    _binkSessionActive = true;

                    // [V61.13.9][BINK_SESSION_TIMELINE]
                    _binkSessionCompleted = false;
                    _binkSessionStartTick = Environment.TickCount64;
                    var v61139DurationMs =
                        BinkHostPlaybackAssist.GetExpectedDurationMs(hostPath);
                    _binkSessionEndTick =
                        _binkWallClockSessions && v61139DurationMs > 0
                            ? _binkSessionStartTick + v61139DurationMs
                            : 0;
                    _binkSessionBaseSerial = frameSerial;

                    BinkHostPlaybackAssist.LogExternal(
                        "SESSION_TIMELINE",
                        "file='" + Path.GetFileName(hostPath) +
                        "' expected_ms=" + v61139DurationMs +
                        " base_serial=" + frameSerial);
                }

                _binkSessionLastFrameTick = Environment.TickCount64;
                BinkHostPlaybackAssist.OnMovieFrame(hostPath);

                // [V61.13.7][BINK_SESSION_PATH]
                if (!string.Equals(
                        _binkSessionPath,
                        hostPath,
                        StringComparison.OrdinalIgnoreCase))
                {
                    if (_binkSessionActive)
                    {
                        BinkHostPlaybackAssist.EndMovieSession(_binkSessionPath);
                    }

                    _binkSessionPath = hostPath;
                    _binkSessionActive = true;

                    // [V61.13.9][BINK_SESSION_TIMELINE]
                    _binkSessionCompleted = false;
                    _binkSessionStartTick = Environment.TickCount64;
                    var v61139DurationMs =
                        BinkHostPlaybackAssist.GetExpectedDurationMs(hostPath);
                    _binkSessionEndTick =
                        _binkWallClockSessions && v61139DurationMs > 0
                            ? _binkSessionStartTick + v61139DurationMs
                            : 0;
                    _binkSessionBaseSerial = frameSerial;

                    BinkHostPlaybackAssist.LogExternal(
                        "SESSION_TIMELINE",
                        "file='" + Path.GetFileName(hostPath) +
                        "' expected_ms=" + v61139DurationMs +
                        " base_serial=" + frameSerial);
                }

                _binkSessionLastFrameTick = Environment.TickCount64;
                BinkHostPlaybackAssist.OnMovieFrame(hostPath);
                _hostMovieLumaTextureAddress = 0;
                _hostMovieChromaTextureAddress = 0;
                _hostMovieLumaDstSelect = 0;
                _hostMovieChromaDstSelect = 0;
                _hostMovieConvertedFrameSerial = -1;
                _hostMovieLumaUploadedFrameSerial = -1;
                _hostMovieChromaUploadedFrameSerial = -1;
                _v740842LearnedUiBinkLumaAddresses.Clear();
                _v740842LearnedUiBinkChromaAddresses.Clear();
                _v74081TitleLoopBindingSeen = false;
                _v74081TitleLoopLastBindingTick = 0;
            }

            // [V61.13.9][BINK_CATCHUP]
            if (_binkWallClockSessions &&
                !_binkSessionCompleted &&
                _binkSessionStartTick > 0 &&
                _binkSessionBaseSerial >= 0 &&
                _binkCatchupMaxFrames > 1)
            {
                var v61139ElapsedMs =
                    Math.Max(0L, Environment.TickCount64 - _binkSessionStartTick);
                var v61139TargetOffset =
                    v61139ElapsedMs * _binkTargetFps / 1000L;
                var v61139CurrentOffset =
                    Math.Max(0L, frameSerial - _binkSessionBaseSerial);

                if (v61139CurrentOffset < v61139TargetOffset)
                {
                    var v61139CatchStart =
                        System.Diagnostics.Stopwatch.GetTimestamp();
                    var v61139Caught = 0;

                    while (v61139Caught < _binkCatchupMaxFrames - 1 &&
                           v61139CurrentOffset < v61139TargetOffset &&
                           System.Diagnostics.Stopwatch.GetTimestamp() -
                               v61139CatchStart < _binkCatchupBudgetTicks)
                    {
                        if (!HostMovieBridge.TryDecodeNextFrame(
                                advanceClock: true,
                                out var v61139Pixels,
                                out var v61139Width,
                                out var v61139Height,
                                out var v61139Advanced,
                                out var v61139Serial,
                                out var v61139Path) ||
                            !v61139Advanced ||
                            !string.Equals(
                                v61139Path,
                                hostPath,
                                StringComparison.OrdinalIgnoreCase))
                        {
                            break;
                        }

                        pixels = v61139Pixels;
                        width = v61139Width;
                        height = v61139Height;
                        advanced = v61139Advanced;
                        frameSerial = v61139Serial;
                        v61139CurrentOffset =
                            Math.Max(0L, frameSerial - _binkSessionBaseSerial);
                        v61139Caught++;
                    }

                    if (v61139Caught > 0)
                    {
                        BinkHostPlaybackAssist.LogExternal(
                            "CATCHUP",
                            "file='" + Path.GetFileName(hostPath) +
                            "' frames=" + v61139Caught +
                            " current_offset=" + v61139CurrentOffset +
                            " target_offset=" + v61139TargetOffset);
                    }
                }
            }
            if (!advanced && _hostMovieFramePixels is not null)
            {
                return;
            }

            BinkIntroHarnessTrace.Event(
                "PRESENTER_FRAME",
                "host='" + hostPath + "' size=" + width + "x" + height +
                " serial=" + frameSerial + " advanced=" + advanced);
            _binkSessionLastFrameTick = Environment.TickCount64;
            if (!_binkWallClockSessions || !_binkSessionCompleted)
            {
                _binkSessionActive = true;
            }
            BinkHostPlaybackAssist.OnMovieFrame(hostPath);

            _binkSessionLastFrameTick = Environment.TickCount64;
            if (!_binkWallClockSessions || !_binkSessionCompleted)
            {
                _binkSessionActive = true;
            }
            BinkHostPlaybackAssist.OnMovieFrame(hostPath);

            if (HostMovieBridge.IsDemonSoulsUiBinkCompositePathV740841(hostPath))
            {
                if (_v740842OwnedUiBinkFramePixels is null ||
                    _v740842OwnedUiBinkFramePixels.Length != pixels.Length)
                {
                    _v740842OwnedUiBinkFramePixels = new byte[pixels.Length];
                }
                pixels.AsSpan().CopyTo(_v740842OwnedUiBinkFramePixels);
                _hostMovieFramePixels = _v740842OwnedUiBinkFramePixels;

                var snapshot = Interlocked.Increment(
                    ref _v740842UiBinkFrameSnapshotCount);
                if (snapshot <= 16 || (snapshot & (snapshot - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        "[V74.0.84.2.1][UI_BINK_FRAME_SNAPSHOT] " +
                        $"count={snapshot} file='{Path.GetFileName(hostPath)}' " +
                        $"serial={frameSerial} bytes={pixels.Length} " +
                        "source=decoder-buffer copy=presenter-owned");
                }
            }
            else
            {
                _hostMovieFramePixels = pixels;
            }
            _hostMovieFrameWidth = width;
            _hostMovieFrameHeight = height;
            _hostMovieFrameSerial = frameSerial;

            // SHARPEMU_V74_0_12_STARTUP_BINK_EARLY_DIRECT_FALLBACK
            // The one-shot startup completion shim can block the guest while
            // the host is showing the real cinematic. Do not wait for a guest
            // texture-resolution call to discover textures=0: the presenter
            // already has the decoded frame and can own the startup logo now.
            if (!_naturalBinkDescriptorlessDirectFallbackActive &&
                IsOneShotStartupBinkV74012(hostPath))
            {
                ActivateNaturalBinkDescriptorlessDirectFallback(
                    "startup-one-shot-host-frame");
            }

            if (_naturalBinkDescriptorlessDirectFallbackActive)
            {
                PresentNaturalBinkDescriptorlessFallbackFrame("pump");
            }
        }

        private static bool IsOneShotStartupBinkV74012(string? hostPath)
        {
            if (string.IsNullOrWhiteSpace(hostPath))
            {
                return false;
            }

            var name = Path.GetFileName(hostPath);
            return
                string.Equals(
                    name,
                    "ps_studios_logo.bk2",
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    name,
                    "logo_intro.bk2",
                    StringComparison.OrdinalIgnoreCase);
        }

        private void ActivateNaturalBinkDescriptorlessDirectFallback(string reason)
        {
            // SHARPEMU_V74_0_83_STALE_FALLBACK_REJECT
            var activeMovieV74083 =
                HostMovieBridge.ActiveMoviePathV74083;
            if (!string.IsNullOrWhiteSpace(_hostMovieFramePath) &&
                !string.Equals(
                    _hostMovieFramePath,
                    activeMovieV74083,
                    StringComparison.OrdinalIgnoreCase))
            {
                var staleForTraceV74083 = _hostMovieFramePath;
                var rejectedV74083 =
                    Interlocked.Increment(
                        ref _v74083StaleFallbackRejectCount);

                ReleaseNaturalBinkDescriptorlessDirectFallback(
                    "stale-host-frame-v83");
                ClearTitleLoopCompositeBindingV74081();

                if (rejectedV74083 <= 16 ||
                    (rejectedV74083 &
                     (rejectedV74083 - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        "[V74.0.83][STALE_FALLBACK_REJECT] " +
                        $"count={rejectedV74083} " +
                        $"stale='{Path.GetFileName(staleForTraceV74083)}' " +
                        $"active='{Path.GetFileName(activeMovieV74083)}'");
                }

                return;
            }
            // SHARPEMU_V74_0_82_TITLE_LOOP_NONEXCLUSIVE
            // Generic natural-Bink fallback is correct for startup one-shots:
            // if the guest exposes no Y/UV descriptors, direct-submit the host
            // movie. It is NOT correct for the title loop because direct submit
            // becomes _binkExclusiveFrame and covers the guest PRESS ANY BUTTON
            // / menu overlay. A title-loop descriptor miss must leave the latest
            // guest-composited frame visible until the real Y/UV pair returns.
            if (HostMovieBridge.IsTitleLoopCompositeActiveV74081)
            {
                ReleaseNaturalBinkDescriptorlessDirectFallback(
                    "title-loop-nonexclusive");

                var suppressedV74082 =
                    Interlocked.Increment(
                        ref _v74082TitleLoopFallbackSuppressCount);
                if (suppressedV74082 <= 32 ||
                    (suppressedV74082 &
                     (suppressedV74082 - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        "[V74.0.82.2][TITLE_LOOP_NONEXCLUSIVE_MISS] " +
                        $"count={suppressedV74082} " +
                        $"reason={reason} " +
                        $"frame={_hostMovieFrameSerial} " +
                        "action=keep-guest-composite");
                }

                return;
            }
            if (_hostMovieFramePixels is null ||
                _hostMovieFrameWidth == 0 ||
                _hostMovieFrameHeight == 0 ||
                string.IsNullOrWhiteSpace(_hostMovieFramePath) ||
                HostMovieBridge.IsDirectPresentationActive ||
                !HostMovieBridge.IsHostPlaybackActive)
            {
                return;
            }

            var entering = false;
            lock (_gate)
            {
                if (!_naturalBinkDescriptorlessDirectFallbackActive)
                {
                    _naturalBinkDescriptorlessDirectFallbackActive = true;
                    entering = true;
                }
            }

            if (entering)
            {
                Console.Error.WriteLine(
                    $"[V74.0.11][BINK] bink2.descriptorless_direct_fallback_start " +
                    $"reason={reason} file='{Path.GetFileName(_hostMovieFramePath)}' " +
                    $"host={_hostMovieFrameWidth}x{_hostMovieFrameHeight} " +
                    $"serial={_hostMovieFrameSerial}");
            }

            PresentNaturalBinkDescriptorlessFallbackFrame(reason);
        }

        private void PresentNaturalBinkDescriptorlessFallbackFrame(string reason)
        {
            // SHARPEMU_V74_0_82_TITLE_LOOP_NONEXCLUSIVE_PRESENT_GUARD
            // Secondary safety: even if an older path left the generic direct
            // fallback active, never Submit() a title-loop frame as an exclusive
            // host presentation.
            if (HostMovieBridge.IsTitleLoopCompositeActiveV74081)
            {
                ReleaseNaturalBinkDescriptorlessDirectFallback(
                    "title-loop-present-guard");
                return;
            }
            if (!_naturalBinkDescriptorlessDirectFallbackActive ||
                _hostMovieFramePixels is null ||
                _hostMovieFrameWidth == 0 ||
                _hostMovieFrameHeight == 0 ||
                _v74011DirectFallbackPresentedFrameSerial == _hostMovieFrameSerial)
            {
                return;
            }

            var stableFrame =
                GC.AllocateUninitializedArray<byte>(_hostMovieFramePixels.Length);
            // SHARPEMU_V74_0_11_2_SYSTEM_BUFFER_QUALIFICATION
            System.Buffer.BlockCopy(
                _hostMovieFramePixels,
                0,
                stableFrame,
                0,
                _hostMovieFramePixels.Length);

            _v74011DirectFallbackPresentedFrameSerial = _hostMovieFrameSerial;
            Submit(stableFrame, _hostMovieFrameWidth, _hostMovieFrameHeight);

            var trace = Interlocked.Increment(ref _v74011DirectFallbackTraceCount);
            if (trace <= 8 || (trace & (trace - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V74.0.11][BINK] bink2.descriptorless_direct_frame " +
                    $"n={trace} reason={reason} " +
                    $"file='{Path.GetFileName(_hostMovieFramePath)}' " +
                    $"serial={_hostMovieFrameSerial} " +
                    $"size={_hostMovieFrameWidth}x{_hostMovieFrameHeight}");
            }
        }

        private void ReleaseNaturalBinkDescriptorlessDirectFallback(string reason)
        {
            var released = false;
            lock (_gate)
            {
                if (_naturalBinkDescriptorlessDirectFallbackActive)
                {
                    _naturalBinkDescriptorlessDirectFallbackActive = false;
                    _binkExclusiveFrame = null;
                    released = true;
                }
            }

            if (released)
            {
                Console.Error.WriteLine(
                    $"[V74.0.11][BINK] bink2.descriptorless_direct_fallback_end " +
                    $"reason={reason} file='{Path.GetFileName(_hostMovieFramePath)}' " +
                    $"serial={_hostMovieFrameSerial}");
            }
        }

        private readonly record struct HostMovieTextureBindings(int Luma, int Chroma)
        {
            public static HostMovieTextureBindings None { get; } = new(-1, -1);
        }

        // SHARPEMU_V74_0_84_2_1_UI_BINK_STICKY_PLANE_INTEGRITY
        private static bool IsUiBinkStickyPlaneEnabledV740842() =>
            Environment.GetEnvironmentVariable("SHARPEMU_DS_UI_BINK_STICKY_PLANES") != "0";

        private HostMovieTextureBindings FindLearnedUiBinkTextureBindingsV740842(
            IReadOnlyList<GuestDrawTexture> textures)
        {
            if (!IsUiBinkStickyPlaneEnabledV740842() ||
                !HostMovieBridge.IsDemonSoulsUiBinkCompositePathV740841(
                    _hostMovieFramePath) ||
                (_v740842LearnedUiBinkLumaAddresses.Count == 0 &&
                 _v740842LearnedUiBinkChromaAddresses.Count == 0))
            {
                return HostMovieTextureBindings.None;
            }

            var lumaIndex = -1;
            var chromaIndex = -1;
            for (var index = 0; index < textures.Count; index++)
            {
                var texture = textures[index];
                if (texture.Address == 0 ||
                    texture.IsStorage ||
                    texture.IsFallback ||
                    texture.ArrayedView ||
                    texture.ArrayLayers > 1)
                {
                    continue;
                }

                if (lumaIndex < 0 &&
                    texture.Format == 1 &&
                    texture.Width >= 1280 &&
                    texture.Height >= 720 &&
                    _v740842LearnedUiBinkLumaAddresses.Contains(texture.Address))
                {
                    lumaIndex = index;
                }
                else if (chromaIndex < 0 &&
                         texture.Format == 3 &&
                         texture.Width >= 640 &&
                         texture.Height >= 360 &&
                         _v740842LearnedUiBinkChromaAddresses.Contains(texture.Address))
                {
                    chromaIndex = index;
                }
            }

            if (lumaIndex < 0 && chromaIndex < 0)
            {
                return HostMovieTextureBindings.None;
            }

            var trace = Interlocked.Increment(
                ref _v740842UiBinkStickyPlaneCount);
            if (trace <= 16 || (trace & (trace - 1)) == 0)
            {
                var lumaAddress = lumaIndex >= 0
                    ? textures[lumaIndex].Address
                    : 0UL;
                var chromaAddress = chromaIndex >= 0
                    ? textures[chromaIndex].Address
                    : 0UL;
                Console.Error.WriteLine(
                    "[V74.0.84.2.1][UI_BINK_STICKY_PLANE] " +
                    $"count={trace} file='{Path.GetFileName(_hostMovieFramePath)}' " +
                    $"luma_index={lumaIndex} luma=0x{lumaAddress:X16} " +
                    $"chroma_index={chromaIndex} chroma=0x{chromaAddress:X16} " +
                    "action=host-plane-substitution raw-guest-sample=blocked");
            }

            return new HostMovieTextureBindings(lumaIndex, chromaIndex);
        }

        private HostMovieTextureBindings FindHostMovieTextureBindings(
            IReadOnlyList<GuestDrawTexture> textures)
        {
            if (_hostMovieFramePixels is null ||
                _hostMovieFrameWidth == 0 ||
                _hostMovieFrameHeight == 0)
            {
                return HostMovieTextureBindings.None;
            }

            if (_hostMovieLumaTextureAddress != 0 &&
                _hostMovieChromaTextureAddress != 0)
            {
                var lumaIndex = -1;
                var chromaIndex = -1;
                for (var index = 0; index < textures.Count; index++)
                {
                    if (textures[index].Address == _hostMovieLumaTextureAddress)
                    {
                        lumaIndex = index;
                    }
                    else if (textures[index].Address == _hostMovieChromaTextureAddress)
                    {
                        chromaIndex = index;
                    }
                }

                if (lumaIndex >= 0 && chromaIndex >= 0)
                {
                    return RememberHostMovieTextureMappings(
                        textures,
                        lumaIndex,
                        chromaIndex);
                }

                // Bluepoint alternates decoder output between multiple Y/UV
                // surface pairs. Fall through and discover the active pair
                // instead of sampling the stale guest surface on every other
                // movie draw.
            }

            var bestLumaIndex = -1;
            var bestChromaIndex = -1;
            ulong bestArea = 0;
            for (var lumaIndex = 0; lumaIndex < textures.Count; lumaIndex++)
            {
                var luma = textures[lumaIndex];
                if (!IsHostMovieLumaCandidate(luma))
                {
                    continue;
                }

                for (var chromaIndex = 0; chromaIndex < textures.Count; chromaIndex++)
                {
                    var chroma = textures[chromaIndex];
                    if (!IsHostMovieChromaCandidate(luma, chroma))
                    {
                        continue;
                    }

                    var area = (ulong)luma.Width * luma.Height;
                    if (bestLumaIndex < 0 || area > bestArea)
                    {
                        bestLumaIndex = lumaIndex;
                        bestChromaIndex = chromaIndex;
                        bestArea = area;
                    }
                }
            }

            if (bestLumaIndex < 0 || bestChromaIndex < 0) 

            { 

                // SHARPEMU_V73_19_1_BINK_BINDING_MISS_TRACE 

                if (textures.Count == 0)
                {
                    ActivateNaturalBinkDescriptorlessDirectFallback(
                        "guest-texture-descriptors=0");
                }

                if (Interlocked.Increment(ref _v73191BinkBindingMissTraceCount) <= 96) 

                { 

                    var descriptors = string.Join( 

                        ",", 

                        textures.Take(24).Select((texture, index) => 

                            $"{index}:0x{texture.Address:X16}:" + 

                            $"{texture.Width}x{texture.Height}:" + 

                            $"f{texture.Format}/n{texture.NumberType}:" + 

                            $"storage={texture.IsStorage}:" + 

                            $"fallback={texture.IsFallback}:" + 

                            $"layers={texture.ArrayLayers}")); 

                    Console.Error.WriteLine( 

                        $"[V73.19.1][BINK] bink2.yuv_pair_not_found " + 

                        $"file='{Path.GetFileName(_hostMovieFramePath)}' " + 

                        $"host={_hostMovieFrameWidth}x{_hostMovieFrameHeight} " + 

                        $"textures={textures.Count} [{descriptors}]"); 

                } 

                return FindLearnedUiBinkTextureBindingsV740842(textures);

            }

            var lumaTexture = textures[bestLumaIndex];
            var chromaTexture = textures[bestChromaIndex];
            ReleaseNaturalBinkDescriptorlessDirectFallback("guest-yuv-pair-bound");
            _hostMovieLumaTextureAddress = lumaTexture.Address;
            _hostMovieChromaTextureAddress = chromaTexture.Address;
            // [V67.1.3][BINK_HARNESS_YUV]
            BinkIntroHarnessTrace.Event(
                "YUV_BOUND",
                "host='" + _hostMovieFramePath +
                "' y=0x" + lumaTexture.Address.ToString("X16") +
                " " + lumaTexture.Width + "x" + lumaTexture.Height +
                " uv=0x" + chromaTexture.Address.ToString("X16") +
                " " + chromaTexture.Width + "x" + chromaTexture.Height);
            _hostMovieLumaDstSelect = lumaTexture.DstSelect;
            _hostMovieChromaDstSelect = chromaTexture.DstSelect;
            var traceKey =
                $"{_hostMovieFramePath}|{lumaTexture.Address:X16}|{chromaTexture.Address:X16}";
            if (_tracedHostMovieTextureBindings.Add(traceKey))
            {
                Console.Error.WriteLine(
                    $"[LOADER][INFO] Bink2 YUV textures bound: " +
                    $"{Path.GetFileName(_hostMovieFramePath)} " +
                    $"y={bestLumaIndex}:0x{lumaTexture.Address:X16}:" +
                    $"{lumaTexture.Width}x{lumaTexture.Height}:dst=0x{lumaTexture.DstSelect:X} " +
                    $"uv={bestChromaIndex}:0x{chromaTexture.Address:X16}:" +
                    $"{chromaTexture.Width}x{chromaTexture.Height}:dst=0x{chromaTexture.DstSelect:X} " +
                    $"host={_hostMovieFrameWidth}x{_hostMovieFrameHeight}.");
            }

                        NoteTitleLoopCompositeBindingV74081(
                textures,
                bestLumaIndex,
                bestChromaIndex);

return new HostMovieTextureBindings(bestLumaIndex, bestChromaIndex);
        }

        private void NoteTitleLoopCompositeBindingV74081(
            IReadOnlyList<GuestDrawTexture> textures,
            int lumaIndex,
            int chromaIndex)
        {
            if (!HostMovieBridge.IsTitleLoopCompositeActiveV74081 ||
                lumaIndex < 0 ||
                chromaIndex < 0 ||
                lumaIndex >= textures.Count ||
                chromaIndex >= textures.Count)
            {
                return;
            }

            _v74081TitleLoopBindingSeen = true;
            _v74081TitleLoopLastBindingTick =
                Stopwatch.GetTimestamp();

            var count = Interlocked.Increment(
                ref _v74081TitleLoopCompositeCount);
            if (count <= 64 ||
                (count & (count - 1)) == 0)
            {
                var luma = textures[lumaIndex];
                var chroma = textures[chromaIndex];
                Console.Error.WriteLine(
                    "[V74.0.81][TITLE_LOOP_PRESS_COMPOSITE] " +
                    $"count={count} " +
                    $"file='{Path.GetFileName(_hostMovieFramePath)}' " +
                    $"frame={_hostMovieFrameSerial} " +
                    $"y=0x{luma.Address:X16}:{luma.Width}x{luma.Height} " +
                    $"uv=0x{chroma.Address:X16}:{chroma.Width}x{chroma.Height} " +
                    "guest_shader_animation=True guest_input=True");
            }
        }

        private void ClearTitleLoopCompositeBindingV74081()
        {
            _v74081TitleLoopBindingSeen = false;
            _v74081TitleLoopLastBindingTick = 0;
            _hostMovieFramePixels = null;
            _hostMovieFramePath = null;
            _hostMovieLumaTextureAddress = 0;
            _hostMovieChromaTextureAddress = 0;
            _hostMovieLumaDstSelect = 0;
            _hostMovieChromaDstSelect = 0;
            _hostMovieConvertedFrameSerial = -1;
            _hostMovieLumaUploadedFrameSerial = -1;
            _hostMovieChromaUploadedFrameSerial = -1;
        }

        private HostMovieTextureBindings RememberHostMovieTextureMappings(
            IReadOnlyList<GuestDrawTexture> textures,
            int lumaIndex,
            int chromaIndex)
        {
            _hostMovieLumaDstSelect = textures[lumaIndex].DstSelect;
            _hostMovieChromaDstSelect = textures[chromaIndex].DstSelect;
                        NoteTitleLoopCompositeBindingV74081(
                textures,
                lumaIndex,
                chromaIndex);

if (IsUiBinkStickyPlaneEnabledV740842() &&
    HostMovieBridge.IsDemonSoulsUiBinkCompositePathV740841(
        _hostMovieFramePath))
{
    var learnedLuma = _v740842LearnedUiBinkLumaAddresses.Add(
        textures[lumaIndex].Address);
    var learnedChroma = _v740842LearnedUiBinkChromaAddresses.Add(
        textures[chromaIndex].Address);
    if (learnedLuma || learnedChroma)
    {
        var trace = Interlocked.Increment(
            ref _v740842UiBinkPlaneLearnCount);
        Console.Error.WriteLine(
            "[V74.0.84.2.1][UI_BINK_PLANE_LEARN] " +
            $"count={trace} file='{Path.GetFileName(_hostMovieFramePath)}' " +
            $"y=0x{textures[lumaIndex].Address:X16} " +
            $"uv=0x{textures[chromaIndex].Address:X16} " +
            $"learned_y={_v740842LearnedUiBinkLumaAddresses.Count} " +
            $"learned_uv={_v740842LearnedUiBinkChromaAddresses.Count}");
    }
}
return new HostMovieTextureBindings(lumaIndex, chromaIndex);
        }

        private bool IsHostMovieLumaCandidate(GuestDrawTexture texture)
        {
            // SHARPEMU_V73_19_1_NATURAL_BINK_640_YUV
            // Runtime defaults deliberately cap NIHAV at 640x360. The old
            // 1280x720 floor made a matching natural guest Y/UV pair impossible.
            if (texture.Address == 0 ||
                texture.IsStorage ||
                texture.IsFallback ||
                texture.ArrayedView ||
                texture.ArrayLayers > 1 ||
                texture.Format != 1 ||
                texture.NumberType != 0 ||
                texture.Width < 640 ||
                texture.Height < 360)
            {
                return false;
            }

            var guestAspect = (ulong)texture.Width * _hostMovieFrameHeight;
            var hostAspect = (ulong)texture.Height * _hostMovieFrameWidth;
            var difference = guestAspect > hostAspect
                ? guestAspect - hostAspect
                : hostAspect - guestAspect;
            return difference * 100 <= Math.Max(guestAspect, hostAspect) * 2;
        }

        private static bool IsHostMovieChromaCandidate(
            GuestDrawTexture luma,
            GuestDrawTexture chroma)
        {
            return chroma.Address != 0 &&
                   chroma.Address != luma.Address &&
                   !chroma.IsStorage &&
                   !chroma.IsFallback &&
                   !chroma.ArrayedView &&
                   chroma.ArrayLayers <= 1 &&
                   chroma.Format == 3 &&
                   chroma.NumberType == 0 &&
                   luma.Width == chroma.Width * 2 &&
                   luma.Height == chroma.Height * 2;
        }

        private TextureResource CreateHostMovieTextureResource(
            GuestDrawTexture texture,
            int plane)
        {
            EnsureHostMovieYuvFrame();
            var isLuma = plane == 0;
            var pixels = isLuma ? _hostMovieLumaPixels! : _hostMovieChromaPixels!;
            var width = isLuma
                ? _hostMovieFrameWidth
                : (_hostMovieFrameWidth + 1) / 2;
            var height = isLuma
                ? _hostMovieFrameHeight
                : (_hostMovieFrameHeight + 1) / 2;
            EnsureHostMovieImages(
                _hostMovieFrameWidth,
                _hostMovieFrameHeight,
                _hostMovieLumaDstSelect,
                (_hostMovieFrameWidth + 1) / 2,
                (_hostMovieFrameHeight + 1) / 2,
                _hostMovieChromaDstSelect);

            var uploadedFrameSerial = isLuma
                ? _hostMovieLumaUploadedFrameSerial
                : _hostMovieChromaUploadedFrameSerial;
            var needsUpload = uploadedFrameSerial != _hostMovieFrameSerial;
            VkBuffer stagingBuffer = default;
            DeviceMemory stagingMemory = default;
            if (needsUpload)
            {
                (stagingBuffer, stagingMemory) = CreateTextureStagingBuffer(
                    pixels,
                    $"Bink2 frame {_hostMovieFrameSerial} plane {plane} staging");
            }

            return new TextureResource
            {
                Address = texture.Address,
                StagingBuffer = stagingBuffer,
                StagingMemory = stagingMemory,
                Image = isLuma ? _hostMovieImage : _hostMovieChromaImage,
                View = isLuma ? _hostMovieImageView : _hostMovieChromaImageView,
                Width = width,
                Height = height,
                RowLength = width,
                DstSelect = texture.DstSelect,
                NeedsUpload = needsUpload,
                IsHostMovie = true,
                HostMoviePlane = plane,
                HostMovieFrameSerial = _hostMovieFrameSerial,
                SamplerState = texture.Sampler,
            };
        }

        // SHARPEMU_V74_0_84_1_UI_BINK_GUEST_CHROMA_ORDER
        // The live Bluepoint Bink shader samples the interleaved chroma plane
        // through its original R/G swizzle. Historical SharpEmu paths used VU
        // here and the recovered fallback color path also required UV swap.
        // Default to VU only for Demon's Souls UI Binks; set
        // SHARPEMU_DS_UI_BINK_CHROMA_ORDER=uv for an instant A/B opt-out.
        private const bool V740841BaseConversionProducesUv = true;

        private static void SwapUiBinkChromaPairsV740841(Span<byte> chroma)
        {
            for (var index = 0; index + 1 < chroma.Length; index += 2)
            {
                (chroma[index], chroma[index + 1]) =
                    (chroma[index + 1], chroma[index]);
            }
        }

        private bool NormalizeDemonSoulsUiBinkChromaV740841(
            Span<byte> chroma)
        {
            if (!HostMovieBridge.IsDemonSoulsUiBinkCompositePathV740841(
                    _hostMovieFramePath))
            {
                return false;
            }

            var desiredUv = string.Equals(
                Environment.GetEnvironmentVariable(
                    "SHARPEMU_DS_UI_BINK_CHROMA_ORDER"),
                "uv",
                StringComparison.OrdinalIgnoreCase);
            var shouldSwap = V740841BaseConversionProducesUv
                ? !desiredUv
                : desiredUv;
            if (shouldSwap)
            {
                SwapUiBinkChromaPairsV740841(chroma);
            }

            var trace = Interlocked.Increment(
                ref _v740841UiBinkChromaTraceCount);
            if (trace <= 16 || (trace & (trace - 1)) == 0)
            {
                Console.Error.WriteLine(
                    "[V74.0.84.1][UI_BINK_CHROMA] " +
                    $"count={trace} file='{Path.GetFileName(_hostMovieFramePath)}' " +
                    $"base={(V740841BaseConversionProducesUv ? "UV" : "VU")} " +
                    $"desired={(desiredUv ? "UV" : "VU")} swap={shouldSwap} " +
                    "matrix=BT709 plane=interleaved-rg");
            }

            return shouldSwap;
        }
        private void EnsureHostMovieYuvFrame()
        {
            if (_hostMovieConvertedFrameSerial == _hostMovieFrameSerial)
            {
                return;
            }

            var bgra = _hostMovieFramePixels ??
                throw new InvalidOperationException("Host movie frame is unavailable.");
            var width = checked((int)_hostMovieFrameWidth);
            var height = checked((int)_hostMovieFrameHeight);
            var chromaWidth = (width + 1) / 2;
            var chromaHeight = (height + 1) / 2;
            if (_hostMovieLumaPixels?.Length != width * height)
            {
                _hostMovieLumaPixels = GC.AllocateUninitializedArray<byte>(width * height);
            }
            if (_hostMovieChromaPixels?.Length != chromaWidth * chromaHeight * 2)
            {
                _hostMovieChromaPixels =
                    GC.AllocateUninitializedArray<byte>(chromaWidth * chromaHeight * 2);
            }

            ConvertBgraToYuv420(
                bgra,
                width,
                height,
                _hostMovieLumaPixels,
                _hostMovieChromaPixels);
            NormalizeDemonSoulsUiBinkChromaV740841(
                _hostMovieChromaPixels);
            _hostMovieConvertedFrameSerial = _hostMovieFrameSerial;
        }

        internal static void ConvertBgraToYuv420(
            ReadOnlySpan<byte> bgra,
            int width,
            int height,
            Span<byte> luma,
            Span<byte> chroma)
        {
            var chromaWidth = (width + 1) / 2;
            for (var y = 0; y < height; y++)
            {
                for (var x = 0; x < width; x++)
                {
                    var source = (y * width + x) * 4;
                    var b = bgra[source];
                    var g = bgra[source + 1];
                    var r = bgra[source + 2];
                    luma[y * width + x] = ClampByte(
                        (54 * r + 183 * g + 19 * b + 128) >> 8);
                }
            }

            for (var y = 0; y < height; y += 2)
            {
                for (var x = 0; x < width; x += 2)
                {
                    var red = 0;
                    var green = 0;
                    var blue = 0;
                    var samples = 0;
                    for (var sampleY = y; sampleY < Math.Min(y + 2, height); sampleY++)
                    {
                        for (var sampleX = x; sampleX < Math.Min(x + 2, width); sampleX++)
                        {
                            var source = (sampleY * width + sampleX) * 4;
                            blue += bgra[source];
                            green += bgra[source + 1];
                            red += bgra[source + 2];
                            samples++;
                        }
                    }

                    red /= samples;
                    green /= samples;
                    blue /= samples;
                    var destination = ((y / 2) * chromaWidth + x / 2) * 2;
                    // [V61.13.10][BT709_UV_ORDER]
                    // Interleaved plane is UV: Cb first, Cr second.
                    // V72.4.3.2.2 HOST_MOVIE_UV_ORDER
                    chroma[destination] = ClampByte(
                        ((-29 * red - 99 * green + 128 * blue + 128) >> 8) + 128);
                    chroma[destination + 1] = ClampByte(
                        ((128 * red - 116 * green - 12 * blue + 128) >> 8) + 128);
                }
            }
        }

        private static byte ClampByte(int value) => (byte)Math.Clamp(value, 0, 255);

        [MethodImpl(MethodImplOptions.NoInlining)]
        private TextureResource ResolveTextureResource(GuestDrawTexture texture)
        {
            // V74.0.67.2.1 pre-composite descriptor redirect.
            if (!texture.IsStorage &&
                TryResolveUpscalerPreCompositeTexture(
                    texture,
                    out var preCompositeUpscaled))
            {
                return preCompositeUpscaled;
            }
            if (texture.IsStorage)
            {
                return ResolveStorageImageResource(texture);
            }

            if (texture.Address != 0 &&
                TryResolveGuestDepthTexture(texture, out var depthTexture))
            {
                return depthTexture;
            }

            var vkFormat = GetTextureFormat(texture.Format, texture.NumberType);
            if (texture.Address != 0 &&
                !(texture.ArrayedView && texture.ArrayLayers > 1) &&
                TryResolveGuestImageAlias(texture, vkFormat, out var guestImage) &&
                TryGetOrCreateGuestImageView(
                    guestImage,
                    vkFormat,
                    mipLevel: texture.BaseMipLevel,
                    levelCount: texture.MipLevels,
                    dstSelect: texture.DstSelect,
                    out var view,
                    arrayedView: texture.ArrayedView))
            {
                TouchSampledGuestImageV7407(guestImage);

                if (ShouldTraceVulkanResources() &&
                    _tracedTextureCacheHits.Add(
                        (texture.Address, texture.Width, texture.Height, vkFormat)))
                {
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.texture_cache_hit addr=0x{texture.Address:X16} " +
                        $"size={texture.Width}x{texture.Height} " +
                        $"image_format={guestImage.Format} view_format={vkFormat}");
                }

                if (guestImage.Width != texture.Width ||
                    guestImage.Height != texture.Height)
                {
                    TraceVulkanShader(
                        $"vk.texture_cache_alias addr=0x{texture.Address:X16} " +
                        $"texture={texture.Width}x{texture.Height} " +
                        $"image={guestImage.Width}x{guestImage.Height} " +
                        $"tile={texture.TileMode} format={vkFormat}");
                }

                if (string.Equals(
                        Environment.GetEnvironmentVariable("SHARPEMU_TRACE_GUEST_IMAGES"),
                        "alias",
                        StringComparison.OrdinalIgnoreCase) &&
                    _tracedGuestImageContents.Add(guestImage.Address))
                {
                    // Deferred: reading back here would clobber the command
                    // buffer mid-recording; drained after the next present.
                    _pendingAliasImageDumps.Enqueue(guestImage);
                }

                // With the write tracker off, AGC ships real texels again but
                // aliased guest images created as GPU RTs stay !IsCpuBacked, so
                // fingerprint refresh never runs and CPU-updated planes (guest
                // Bink) stay black. Promote only when this draw carried
                // non-zero guest pixels Ã¢â‚¬â€ same outcome as the old per-draw path.
                if (!guestImage.IsCpuBacked &&
                    !SharpEmu.HLE.GuestImageWriteTracker.Enabled &&
                    texture.RgbaPixels.Length > 0 &&
                    texture.RgbaPixels.AsSpan().IndexOfAnyExcept((byte)0) >= 0)
                {
                    guestImage.IsCpuBacked = true;
                }

                if (TryCreateCpuTextureRefreshResource(
                        texture,
                        guestImage,
                        view,
                        out var refreshResource))
                {
                    return refreshResource;
                }

                return new TextureResource
                {
                    Address = texture.Address,
                    Image = guestImage.Image,
                    View = view,
                    Width = guestImage.Width,
                    Height = guestImage.Height,
                    Depth = guestImage.Depth,
                    Type = guestImage.Type,
                    RowLength = guestImage.Width,
                    DstSelect = texture.DstSelect,
                    SamplerState = texture.Sampler,
                    GuestImage = guestImage,
                };
            }

            // SHARPEMU_V74_0_56_32_DCC_METADATA_ALIAS
            // Address-based lookup can miss a DCC alias because the AGC->GPU
            // seam historically discarded CB_COLOR metadata provenance. Try
            // the real GPU image by metadata before any CPU texture path.
            if (texture.GpuReferenceOnly &&
                TryResolveGuestImageMetadataAliasV7405632(
                    texture,
                    vkFormat,
                    out var metadataImageV7405632) &&
                TryGetOrCreateGuestImageView(
                    metadataImageV7405632,
                    vkFormat,
                    mipLevel: texture.BaseMipLevel,
                    levelCount: texture.MipLevels,
                    dstSelect: texture.DstSelect,
                    out var metadataViewV7405632,
                    arrayedView: texture.ArrayedView))
            {
                TouchSampledGuestImageV7407(
                    metadataImageV7405632);

                return new TextureResource
                {
                    Address = texture.Address,
                    Image = metadataImageV7405632.Image,
                    View = metadataViewV7405632,
                    Width = metadataImageV7405632.Width,
                    Height = metadataImageV7405632.Height,
                    Depth = metadataImageV7405632.Depth,
                    Type = metadataImageV7405632.Type,
                    RowLength = metadataImageV7405632.Width,
                    DstSelect = texture.DstSelect,
                    SamplerState = texture.Sampler,
                    GuestImage = metadataImageV7405632,
                };
            }

            if (texture.GpuReferenceOnly)
            {
                // Never feed DCC-compressed guest RAM into the standalone
                // texture self-heal. Preserve the old safe semantic only after
                // the execution-time GPU alias lookup has failed.
                var fallbackV7405632 = texture with
                {
                    Address = 0,
                    Width = 1,
                    Height = 1,
                    Pitch = 1,
                    RgbaPixels = Array.Empty<byte>(),
                    IsFallback = true,
                    MetadataAddress = 0,
                    TiledSource = null,
                    Detile = null,
                    GpuReferenceOnly = false,
                };

                var missFallbackCountV7405632 =
                    Volatile.Read(
                        ref _v7405632DccMetadataAliasMissCount);

                if (missFallbackCountV7405632 <= 64 ||
                    (missFallbackCountV7405632 &
                     (missFallbackCountV7405632 - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        $"[V74.0.56.32][DCC_META_ALIAS] " +
                        $"action=miss-fallback " +
                        $"addr=0x{texture.Address:X16} " +
                        $"meta=0x{texture.MetadataAddress:X16} " +
                        $"size={texture.Width}x{texture.Height} " +
                        $"fmt={texture.Format}/{texture.NumberType}");
                }

                return CreateTextureResource(
                    fallbackV7405632);
            }

            if (ShouldTraceVulkanResources() && texture.Address != 0)
            {
                if (_guestImages.TryGetValue(texture.Address, out var missImage))
                {
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.alias_miss addr=0x{texture.Address:X16} " +
                        $"reason={(IsCompatibleGuestImageAlias(texture, missImage) ? "format" : "size")} " +
                        $"tex={texture.Width}x{texture.Height}/f{texture.Format}/n{texture.NumberType}/vk{vkFormat} " +
                        $"img={missImage.Width}x{missImage.Height}/imgfmt{missImage.Format} " +
                        $"init={missImage.Initialized}");
                }
                else
                {
                    GuestImageResource? overlap = null;
                    ulong overlapBackingBytesV57 = 0;
                    ulong overlapRequestBytesV57 = 0;
                    var requestRowLengthV57 = texture.TileMode == 0
                        ? Math.Max(texture.Pitch, texture.Width)
                        : texture.Width;
                    var requestLayersV57 = GetEffectiveTextureArrayLayers(
                        texture.Type,
                        texture.ArrayedView,
                        texture.ArrayLayers);
                    var requestPlaneBytesV57 = GetTextureByteCount(
                        texture.Format,
                        requestRowLengthV57,
                        texture.Height,
                        GetGuestTextureDepth(texture.Type, texture.Depth));
                    if (requestPlaneBytesV57 != 0 &&
                        requestPlaneBytesV57 <= ulong.MaxValue / requestLayersV57)
                    {
                        overlapRequestBytesV57 =
                            requestPlaneBytesV57 * requestLayersV57;
                    }

                    foreach (var candidate in _guestImages.Values)
                    {
                        var candidateBytes = GetVulkanImageByteCount(
                            candidate.Format,
                            candidate.Width,
                            candidate.Height,
                            Math.Max(candidate.Depth, 1u));
                        if (candidateBytes == 0 ||
                            overlapRequestBytesV57 == 0 ||
                            ulong.MaxValue - candidate.Address < candidateBytes ||
                            ulong.MaxValue - texture.Address < overlapRequestBytesV57)
                        {
                            continue;
                        }

                        var candidateEnd = candidate.Address + candidateBytes;
                        var requestEnd = texture.Address + overlapRequestBytesV57;
                        if (texture.Address < candidate.Address ||
                            requestEnd > candidateEnd)
                        {
                            continue;
                        }

                        overlap = candidate;
                        overlapBackingBytesV57 = candidateBytes;
                        break;
                    }

                    if (overlap is not null)
                    {
                        Console.Error.WriteLine(
                            $"[LOADER][TRACE] vk.alias_full_containment_candidate " +
                            $"addr=0x{texture.Address:X16} backing=0x{overlap.Address:X16} " +
                            $"offset=0x{texture.Address - overlap.Address:X} " +
                            $"request_bytes={overlapRequestBytesV57} " +
                            $"backing_bytes={overlapBackingBytesV57} " +
                            $"tex={texture.Width}x{texture.Height}/f{texture.Format}/n{texture.NumberType} " +
                            $"img={overlap.LogicalWidth}x{overlap.LogicalHeight}/{overlap.Format}");
                    }

                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.alias_miss addr=0x{texture.Address:X16} " +
                        $"reason=absent tex={texture.Width}x{texture.Height}/f{texture.Format}/n{texture.NumberType}");
                }
            }

            if (_traceImageOverlap &&
                texture.Address != 0 &&
                IsTextureSnapshotAllZero(texture) &&
                TryFindOverlappingGpuGuestImage(texture, out var overlapImage, out var overlapBytes) &&
                Interlocked.Increment(ref _imageOverlapTraceCount) <= 512)
            {
                Console.Error.WriteLine(
                    $"[V23][IMAGE] vk.texture_overlap_probe addr=0x{texture.Address:X16} " +
                    $"size={texture.Width}x{texture.Height} fmt={texture.Format}/{texture.NumberType} " +
                    $"overlap_addr=0x{overlapImage.Address:X16} overlap_bytes={overlapBytes} " +
                    $"overlap_size={overlapImage.Width}x{overlapImage.Height} " +
                    $"overlap_format={overlapImage.Format} initialized={overlapImage.Initialized}");
            }
            return GetOrCreateCachedTextureResource(texture);
        }

        // V23: keep initialized GPU content when a stale CPU snapshot is all-zero.
        private static bool IsTextureSnapshotAllZero(GuestDrawTexture texture)
        {
            if (texture.RgbaPixels.Length > 0)
            {
                return texture.RgbaPixels.AsSpan().IndexOfAnyExcept((byte)0) < 0;
            }
            if (texture.TiledSource is { Length: > 0 } tiled)
            {
                return tiled.AsSpan().IndexOfAnyExcept((byte)0) < 0;
            }
            return false;
        }

        private static bool ShouldSuppressStaleZeroCpuRefresh(
            GuestImageResource guestImage,
            GuestDrawTexture texture,
            ReadOnlySpan<byte> pixels,
            bool hasUploadedGeneration,
            long uploadedGeneration)
        {
            if (!SharpEmu.HLE.GuestImageWriteTracker.Enabled ||
                !guestImage.Initialized ||
                pixels.Length == 0 ||
                pixels.IndexOfAnyExcept((byte)0) >= 0)
            {
                return false;
            }
            var explicitNewCpuWrite = texture.WriteGeneration > 0 &&
                (!hasUploadedGeneration || uploadedGeneration != texture.WriteGeneration);
            return !explicitNewCpuWrite;
        }

        private bool TryFindOverlappingGpuGuestImage(
            GuestDrawTexture texture,
            out GuestImageResource candidate,
            out ulong overlapBytes)
        {
            candidate = null!;
            overlapBytes = 0;
            if (texture.Address == 0)
            {
                return false;
            }
            var rowLength = texture.TileMode == 0
                ? Math.Max(texture.Pitch, texture.Width)
                : texture.Width;
            var requestBytes = GetTextureByteCount(
                texture.Format,
                rowLength,
                texture.Height,
                GetGuestTextureDepth(texture.Type, texture.Depth));
            if (requestBytes == 0 || ulong.MaxValue - texture.Address < requestBytes)
            {
                return false;
            }
            var requestEnd = texture.Address + requestBytes;
            foreach (var image in _guestImages.Values)
            {
                if (!image.Initialized || image.Address == 0 || image.Address == texture.Address)
                {
                    continue;
                }
                var imageBytes = GetVulkanImageByteCount(
                    image.Format,
                    image.Width,
                    image.Height,
                    Math.Max(image.Depth, 1u));
                if (imageBytes == 0 || ulong.MaxValue - image.Address < imageBytes)
                {
                    continue;
                }
                var imageEnd = image.Address + imageBytes;
                var overlapStart = texture.Address > image.Address ? texture.Address : image.Address;
                var overlapEnd = requestEnd < imageEnd ? requestEnd : imageEnd;
                if (overlapEnd <= overlapStart)
                {
                    continue;
                }
                var overlap = overlapEnd - overlapStart;
                if (overlap > overlapBytes)
                {
                    candidate = image;
                    overlapBytes = overlap;
                }
            }
            return candidate is not null;
        }
        private bool TryCreateCpuTextureRefreshResource(
            GuestDrawTexture texture,
            GuestImageResource guestImage,
            ImageView view,
            out TextureResource resource)
        {
            resource = default!;
            if (guestImage.Width != texture.Width ||
                guestImage.Height != texture.Height ||
                guestImage.Depth != GetGuestTextureDepth(texture.Type, texture.Depth) ||
                IsGuestTexture3D(guestImage.Type) != IsGuestTexture3D(texture.Type) ||
                guestImage.MipLevels != 1 ||
                texture.RgbaPixels.Length == 0)
            {
                return false;
            }

            // IsCpuBacked alone used to gate this path, but it is a latch that
            // flips false the first time the address is used as a render target
            // and never flips back. On PS5 that address is unified memory: a
            // surface that was rendered into once and is later rewritten by the
            // guest CPU (glyph atlas rasterization, a 4K UI sheet redrawn on the
            // brightness screen) must still be re-read. Fall back on the write
            // tracker, which reports genuine CPU stores and leaves pure
            // render-into-then-sample feedback untouched.
            bool hasUploadedGeneration;
            long uploadedGeneration;
            lock (_gate)
            {
                hasUploadedGeneration = _cpuBackedUploadGenerations.TryGetValue(
                    texture.Address,
                    out uploadedGeneration);
            }

            if (!ShouldRefreshGuestImageFromCpu(
                    guestImage.IsCpuBacked,
                    texture.WriteGeneration,
                    hasUploadedGeneration,
                    uploadedGeneration))
            {
                return false;
            }

            var rowLength = texture.TileMode == 0
                ? Math.Max(texture.Pitch, texture.Width)
                : texture.Width;
            var depth = GetGuestTextureDepth(texture.Type, texture.Depth);
            var expectedSize = GetTextureByteCount(
                texture.Format,
                rowLength,
                texture.Height,
                depth);
            if (expectedSize == 0 || expectedSize > int.MaxValue)
            {
                return false;
            }

            var pixels = texture.RgbaPixels.Length == (int)expectedSize
                ? texture.RgbaPixels
                : CreateFallbackTexturePixels(texture.Format, rowLength, texture.Height, expectedSize);
            if (ShouldSuppressStaleZeroCpuRefresh(
                    guestImage,
                    texture,
                    pixels,
                    hasUploadedGeneration,
                    uploadedGeneration))
            {
                if (_traceImageOverlap && Interlocked.Increment(ref _imageOverlapTraceCount) <= 512)
                {
                    Console.Error.WriteLine(
                        $"[V23][IMAGE] vk.texture_refresh_suppressed_zero addr=0x{texture.Address:X16} " +
                        $"size={texture.Width}x{texture.Height} generation={texture.WriteGeneration} " +
                        $"uploaded_generation={(hasUploadedGeneration ? uploadedGeneration : -1)}");
                }
                return false;
            }
            var fingerprint = ComputeTextureContentFingerprint(pixels);
            if ((guestImage.Initialized || guestImage.InitialUploadPending) &&
                guestImage.CpuContentFingerprint == fingerprint)
            {
                // Content unchanged despite a newer write generation: advance
                // the recorded generation so later draws can skip the copy
                // again instead of restaging identical texels every draw.
                if (texture.WriteGeneration >= 0)
                {
                    lock (_gate)
                    {
                        _cpuBackedUploadGenerations[texture.Address] =
                            texture.WriteGeneration;
                    }
                }

                return false;
            }

            var uploadPixels = texture.Format == 13
                ? ExpandRgb32Pixels(pixels)
                : pixels;
            var debugName = TextureDebugName(texture, guestImage.Format);
            var (stagingBuffer, stagingMemory) = CreateTextureStagingBuffer(
                uploadPixels,
                $"{debugName} refresh staging");
            TraceVulkanShader(
                $"vk.texture_refresh addr=0x{texture.Address:X16} " +
                $"size={texture.Width}x{texture.Height} bytes={uploadPixels.Length}");
            resource = new TextureResource
            {
                Address = texture.Address,
                StagingBuffer = stagingBuffer,
                StagingMemory = stagingMemory,
                Image = guestImage.Image,
                View = view,
                Width = guestImage.Width,
                Height = guestImage.Height,
                Depth = guestImage.Depth,
                Type = guestImage.Type,
                RowLength = rowLength,
                DstSelect = texture.DstSelect,
                NeedsUpload = true,
                SamplerState = texture.Sampler,
                GuestImage = guestImage,
                CpuContentFingerprint = fingerprint,
                UpdatesCpuContent = true,
                WriteGeneration = texture.WriteGeneration,
            };
            return true;
        }

        private bool TryResolveGuestImageAlias(
            GuestDrawTexture texture,
            Format viewFormat,
            out GuestImageResource guestImage)
        {
            GuestImageResource? best = null;
            var bestScore = int.MinValue;
            var candidateCount = 0;
            var guestFormat = GetGuestTextureFormat(texture.Format, texture.NumberType);

            void Consider(GuestImageResource candidate, bool isActive)
            {
                // SHARPEMU_V74_0_76_DCC_INITIALIZED_ALIAS_GUARD
                if (texture.GpuReferenceOnly &&
                    !candidate.Initialized)
                {
                    var rejectCountV74076 = Interlocked.Increment(
                        ref _v74076DccUninitializedAliasRejectCount);
                    if (rejectCountV74076 <= 64 ||
                        (rejectCountV74076 &
                         (rejectCountV74076 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.76][DCC_UNINITIALIZED_ALIAS_REJECT] " +
                            $"count={rejectCountV74076} " +
                            $"addr=0x{texture.Address:X16} " +
                            $"meta=0x{texture.MetadataAddress:X16} " +
                            $"image=0x{candidate.Address:X16} " +
                            $"size={texture.Width}x{texture.Height} " +
                            $"fmt={texture.Format}/{texture.NumberType}");
                    }
                    return;
                }

                if (!IsUsableGuestImageAlias(texture, viewFormat, candidate))
                {
                    return;
                }

                candidateCount++;
                var score = 0;
                if (candidate.LogicalWidth == texture.Width &&
                    candidate.LogicalHeight == texture.Height &&
                    candidate.LogicalDepth ==
                        GetGuestTextureDepth(texture.Type, texture.Depth))
                {
                    score += 32;
                }
                if (candidate.Format == viewFormat)
                {
                    score += 16;
                }
                if (candidate.GuestFormat == guestFormat)
                {
                    score += 8;
                }
                // Prefer a resource whose exact RDNA2 tiling provenance is
                // known. Unknown partial-state surfaces remain legal fallbacks,
                // but must never outrank an exact tile-mode match.
                if (candidate.TileModeKnown &&
                    candidate.TileMode == texture.TileMode)
                {
                    score += 64;
                }
                if (candidate.Initialized)
                {
                    score += 4;
                }
                if (candidate.MipLevels == texture.ResourceMipLevels)
                {
                    score += 2;
                }
                if (isActive)
                {
                    score += 1;
                }

                // V60: freshness is the primary invariant. Descriptor shape is
                // only a tie-breaker between resources with the same content
                // generation. This prevents a newly activated, exact-size but
                // stale image from hiding the compatible surface written by the
                // preceding pass at the same guest address.
                if (best is null ||
                    candidate.ContentGeneration > best.ContentGeneration ||
                    candidate.ContentGeneration == best.ContentGeneration &&
                    score > bestScore)
                {
                    best = candidate;
                    bestScore = score;
                }
            }

            if (_guestImages.TryGetValue(texture.Address, out var active))
            {
                Consider(active, isActive: true);
            }

            foreach (var (key, candidate) in _guestImageVariants)
            {
                if (key.Address == texture.Address)
                {
                    Consider(candidate, isActive: false);
                }
            }

            if (best is not null)
            {
                guestImage = best;
                var selectionKey = (
                    texture.Address,
                    texture.Width,
                    texture.Height,
                    GetGuestTextureDepth(texture.Type, texture.Depth),
                    texture.Type,
                    texture.TileMode,
                    viewFormat,
                    guestFormat);
                if (candidateCount > 1 &&
                    (!_v60GenerationSelections.TryGetValue(
                        selectionKey,
                        out var previousSelection) ||
                     previousSelection.Image != best.Image.Handle ||
                     previousSelection.Generation != best.ContentGeneration))
                {
                    _v60GenerationSelections[selectionKey] =
                        (best.Image.Handle, best.ContentGeneration);
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.generation_select " +
                        $"addr=0x{texture.Address:X16} candidates={candidateCount} " +
                        $"generation={best.ContentGeneration} score={bestScore} " +
                        $"tex={texture.Width}x{texture.Height}/{viewFormat} tile={texture.TileMode} " +
                        $"image={best.Width}x{best.Height}/{best.Format} " +
                        $"image_tile={(best.TileModeKnown ? best.TileMode.ToString() : "unknown")}");
                }

                if (ShouldTraceVulkanResources())
                {
                    Console.Error.WriteLine(
                        $"[LOADER][TRACE] vk.texture_variant_hit " +
                        $"addr=0x{texture.Address:X16} " +
                        $"tex={texture.Width}x{texture.Height}/{viewFormat} " +
                        $"image={best.Width}x{best.Height}/{best.Format} " +
                        $"initialized={best.Initialized} " +
                        $"generation={best.ContentGeneration}");
                }
                return true;
            }

            guestImage = null!;
            return false;
        }

        // SHARPEMU_V74_0_56_32_DCC_METADATA_ALIAS
        // Resolve only intentionally deferred DCC references. Ordinary sampled
        // textures keep the exact-address/variant behavior above.
        private bool TryResolveGuestImageMetadataAliasV7405632(
            GuestDrawTexture texture,
            Format viewFormat,
            out GuestImageResource guestImage)
        {
            guestImage = null!;

            if (!texture.GpuReferenceOnly ||
                texture.MetadataAddress == 0)
            {
                return false;
            }

            GuestImageResource? best = null;
            var bestScore = int.MinValue;
            var candidateCount = 0;
            var guestFormat =
                GetGuestTextureFormat(
                    texture.Format,
                    texture.NumberType);

            void Consider(
                GuestImageResource candidate,
                bool isActive)
            {
                // SHARPEMU_V74_0_77_1_DS_DCC_TYPED_ALIAS_GUARD
                // Current failing PPSA01341 capture:
                //   sample=0x460890000 meta=0x486B13000
                //   sample_fmt=R8G8B8A8Unorm
                //   image_fmt=R16G16Sfloat
                // A metadata match is provenance, not permission to reinterpret
                // an unrelated typed image. Keep this title/resource-specific:
                // exact-format candidates remain eligible and normal aliasing
                // outside this DCC identity is untouched.
                if (_v740771StrictDsDccTypedAlias &&
                    texture.MetadataAddress == 0x0000000486B13000UL &&
                    texture.Width == 2560 &&
                    texture.Height == 1440 &&
                    texture.Format == 10 &&
                    texture.NumberType == 0 &&
                    viewFormat == Format.R8G8B8A8Unorm &&
                    candidate.Format != viewFormat)
                {
                    var rejectCountV740771 = Interlocked.Increment(
                        ref _v740771DccTypedAliasRejectCount);
                    if (rejectCountV740771 <= 128 ||
                        (rejectCountV740771 &
                         (rejectCountV740771 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.77.1][DCC_TYPED_ALIAS_REJECT] " +
                            $"count={rejectCountV740771} " +
                            $"sample=0x{texture.Address:X16} " +
                            $"image=0x{candidate.Address:X16} " +
                            $"meta=0x{texture.MetadataAddress:X16} " +
                            $"sample_size={texture.Width}x{texture.Height} " +
                            $"image_size={candidate.LogicalWidth}x{candidate.LogicalHeight} " +
                            $"sample_fmt={viewFormat} " +
                            $"image_fmt={candidate.Format} " +
                            $"generation={candidate.ContentGeneration}");
                    }
                    return;
                }

                if (candidate.MetadataAddress == 0 ||
                    candidate.MetadataAddress != texture.MetadataAddress ||
                    !candidate.Initialized ||
                    !IsUsableGuestImageAlias(
                        texture,
                        viewFormat,
                        candidate))
                {
                    return;
                }

                candidateCount++;
                var score = 0;

                if (candidate.Address == texture.Address)
                {
                    score += 256;
                }

                if (candidate.LogicalWidth == texture.Width &&
                    candidate.LogicalHeight == texture.Height &&
                    candidate.LogicalDepth ==
                        GetGuestTextureDepth(
                            texture.Type,
                            texture.Depth))
                {
                    score += 128;
                }

                if (candidate.TileModeKnown &&
                    candidate.TileMode == texture.TileMode)
                {
                    score += 64;
                }

                if (candidate.Format == viewFormat)
                {
                    score += 32;
                }

                if (candidate.GuestFormat == guestFormat)
                {
                    score += 16;
                }

                if (candidate.MipLevels ==
                    texture.ResourceMipLevels)
                {
                    score += 8;
                }

                if (isActive)
                {
                    score += 1;
                }

                // Same rule as V60's address variants: newest written content
                // outranks a nicer descriptor shape.
                if (best is null ||
                    candidate.ContentGeneration >
                        best.ContentGeneration ||
                    candidate.ContentGeneration ==
                        best.ContentGeneration &&
                    score > bestScore)
                {
                    best = candidate;
                    bestScore = score;
                }
            }

            // SHARPEMU_V74_0_82_DCC_BUCKET_LOOKUP

            var metadataBucketV74082 =

                GetDccMetadataBucketV74082(texture.MetadataAddress);

            foreach (var candidate in metadataBucketV74082.Active)

            {

                Consider(candidate, isActive: true);

            }


            foreach (var candidate in metadataBucketV74082.Variants)

            {

                Consider(candidate, isActive: false);

            }

            // SHARPEMU_V74_0_80_DCC_PROVENANCE_RECOVERY
            // V56.32 can only resolve DCC by metadata when the producer
            // GuestImageResource actually retained that metadata VA. Older /
            // partial CB_COLOR paths can create and write the correct Vulkan
            // image first and learn DCC_BASE only later. Do not guess by
            // address or by size alone: repair provenance only when the
            // initialized zero-metadata candidates have an exact logical
            // shape, exact known tile mode, compatible view, and one uniquely
            // newest GPU content generation.
            if (best is null)
            {
                GuestImageResource? repairCandidateV74080 = null;
                var repairGenerationV74080 = 0L;
                var repairGenerationTiedV74080 = false;
                var repairCandidateCountV74080 = 0;

                void ConsiderMissingProvenanceV74080(
                    GuestImageResource candidate)
                {
                    if (candidate.MetadataAddress != 0 ||
                        !candidate.Initialized ||
                        candidate.ContentGeneration <= 0 ||
                        candidate.LogicalWidth != texture.Width ||
                        candidate.LogicalHeight != texture.Height ||
                        candidate.LogicalDepth !=
                            GetGuestTextureDepth(
                                texture.Type,
                                texture.Depth) ||
                        !candidate.TileModeKnown ||
                        candidate.TileMode != texture.TileMode ||
                        !IsUsableGuestImageAlias(
                            texture,
                            viewFormat,
                            candidate))
                    {
                        return;
                    }

                    repairCandidateCountV74080++;

                    if (repairCandidateV74080 is null ||
                        candidate.ContentGeneration >
                            repairGenerationV74080)
                    {
                        repairCandidateV74080 = candidate;
                        repairGenerationV74080 =
                            candidate.ContentGeneration;
                        repairGenerationTiedV74080 = false;
                    }
                    else if (candidate.ContentGeneration ==
                             repairGenerationV74080)
                    {
                        repairGenerationTiedV74080 = true;
                    }
                }

                foreach (var candidateV74080 in _guestImages.Values)
                {
                    ConsiderMissingProvenanceV74080(
                        candidateV74080);
                }

                foreach (var candidateV74080 in
                         _guestImageVariants.Values)
                {
                    ConsiderMissingProvenanceV74080(
                        candidateV74080);
                }

                if (repairCandidateV74080 is not null &&
                    !repairGenerationTiedV74080)
                {
                    repairCandidateV74080.MetadataAddress =
                        texture.MetadataAddress;
                    best = repairCandidateV74080;
                    bestScore = int.MaxValue;

                    var repairCountV74080 =
                        Interlocked.Increment(
                            ref _v74080DccProvenanceRecoveryCount);

                    if (repairCountV74080 <= 128 ||
                        (repairCountV74080 &
                         (repairCountV74080 - 1)) == 0)
                    {
                        Console.Error.WriteLine(
                            $"[V74.0.80][DCC_PROVENANCE_RECOVERY] " +
                            $"count={repairCountV74080} " +
                            $"sample=0x{texture.Address:X16} " +
                            $"producer=0x{repairCandidateV74080.Address:X16} " +
                            $"meta=0x{texture.MetadataAddress:X16} " +
                            $"generation={repairGenerationV74080} " +
                            $"candidates={repairCandidateCountV74080} " +
                            $"size={texture.Width}x{texture.Height} " +
                            $"fmt={texture.Format}/{texture.NumberType} " +
                            $"tile={texture.TileMode}");
                    }
                }
            }

            if (best is null)
            {
                var missCount = Interlocked.Increment(
                    ref _v7405632DccMetadataAliasMissCount);

                if (missCount <= 64 ||
                    (missCount & (missCount - 1)) == 0)
                {
                    Console.Error.WriteLine(
                        $"[V74.0.56.32][DCC_META_ALIAS] " +
                        $"action=miss count={missCount} " +
                        $"addr=0x{texture.Address:X16} " +
                        $"meta=0x{texture.MetadataAddress:X16} " +
                        $"size={texture.Width}x{texture.Height} " +
                        $"fmt={texture.Format}/{texture.NumberType} " +
                        $"vk={viewFormat} tile={texture.TileMode} " +
                        $"active={_guestImages.Count} " +
                        $"variants={_guestImageVariants.Count}");
                }

                return false;
            }

            guestImage = best;

            var hitCount = Interlocked.Increment(
                ref _v7405632DccMetadataAliasHitCount);

            if (hitCount <= 128 ||
                (hitCount & (hitCount - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V74.0.56.32][DCC_META_ALIAS] " +
                    $"action=hit count={hitCount} " +
                    $"sample=0x{texture.Address:X16} " +
                    $"image=0x{best.Address:X16} " +
                    $"meta=0x{texture.MetadataAddress:X16} " +
                    $"candidates={candidateCount} " +
                    $"generation={best.ContentGeneration} " +
                    $"score={bestScore} " +
                    $"sample_size={texture.Width}x{texture.Height} " +
                    $"image_size={best.LogicalWidth}x{best.LogicalHeight} " +
                    $"sample_fmt={viewFormat} " +
                    $"image_fmt={best.Format}");
            }

            return true;
        }

        private static bool IsUsableGuestImageAlias(
            GuestDrawTexture texture,
            Format viewFormat,
            GuestImageResource guestImage) =>
            texture.BaseMipLevel < guestImage.MipLevels &&
            IsCompatibleGuestImageAlias(texture, guestImage) &&
            IsCompatibleViewFormat(guestImage.Format, viewFormat);

        private bool TryResolveGuestDepthTexture(
            GuestDrawTexture texture,
            out TextureResource resource)
        {
            if (IsGuestTexture3D(texture.Type))
            {
                resource = null!;
                return false;
            }

            foreach (var depth in _guestDepthImages.Values)
            {
                if (texture.Address != depth.Address &&
                    texture.Address != depth.ReadAddress &&
                    texture.Address != depth.WriteAddress)
                {
                    continue;
                }

                if (texture.Width > depth.LogicalWidth || texture.Height > depth.LogicalHeight)
                {
                    continue;
                }

                if (!depth.SampleViews.TryGetValue(texture.DstSelect, out var view))
                {
                    var viewInfo = new ImageViewCreateInfo
                    {
                        SType = StructureType.ImageViewCreateInfo,
                        Image = depth.Image,
                        ViewType = ImageViewType.Type2D,
                        Format = DepthFormat,
                        Components = ToVkComponentMapping(texture.DstSelect),
                        SubresourceRange = new ImageSubresourceRange(
                            ImageAspectFlags.DepthBit,
                            0,
                            1,
                            0,
                            1),
                    };
                    Check(
                        _vk.CreateImageView(_device, &viewInfo, null, out view),
                        "vkCreateImageView(depth sample)");
                    SetDebugName(
                        ObjectType.ImageView,
                        view.Handle,
                        $"SharpEmu guest depth sample 0x{depth.Address:X16} " +
                        $"dst=0x{texture.DstSelect:X3}");
                    depth.SampleViews.Add(texture.DstSelect, view);
                }

                if (_tracedDepthTextureAliases.Add(
                        (texture.Address, texture.Width, texture.Height, texture.DstSelect)))
                {
                    TraceVulkanShader(
                        $"vk.depth_texture_alias addr=0x{texture.Address:X16} " +
                        $"depth=0x{depth.Address:X16} " +
                        $"texture={texture.Width}x{texture.Height} " +
                        $"surface={depth.Width}x{depth.Height} dst=0x{texture.DstSelect:X3}");
                }
                resource = new TextureResource
                {
                    Address = texture.Address,
                    Image = depth.Image,
                    View = view,
                    Width = depth.Width,
                    Height = depth.Height,
                    RowLength = depth.Width,
                    DstSelect = texture.DstSelect,
                    SamplerState = texture.Sampler,
                    GuestDepth = depth,
                };
                return true;
            }

            resource = null!;
            return false;
        }

        private readonly Dictionary<TextureContentIdentity, TextureResource> _textureCache = new();

        // SHARPEMU_V74_0_73_TEXTURE_RESOURCE_HOT_PATH
        // TextureContentIdentity currently includes GuestSampler even though
        // sampler objects are created/cached separately at descriptor binding.
        // Reuse image/view storage only when every content/view field matches
        // and ONLY the sampler differs. Explicit =0 restores exact-key-only.
        private static readonly bool _samplerImageAliasV74073 =
            !string.Equals(
                Environment.GetEnvironmentVariable("SHARPEMU_SAMPLER_IMAGE_ALIAS"),
                "0",
                StringComparison.Ordinal);
        private long _v74073SamplerImageAliasTraceCount;
        private long _v74073SamplerImageAliasHitCount;
        private long _v74073SamplerAliasDiscardedSourceBytes;

        private long _v7408StandaloneTextureUseSerial;
        private long _v7408StandaloneTextureTraceCount;
        private long _v74055DeferredTextureOwnershipHoldTraceCount;
        private long _v74055DuplicateTextureDestroyTraceCount;

        // [V74.0.56][DEVICE_LOST_CANDIDATE_AUDIT]
        // Diagnostic only: vkQueueSubmit can surface a prior GPU fault.
        private static readonly bool _traceDeviceLostCandidateV74056 =
            string.Equals(
                Environment.GetEnvironmentVariable(
                    "SHARPEMU_TRACE_DEVICE_LOST_CANDIDATE"),
                "1",
                StringComparison.Ordinal);
        private static readonly string? _deviceLostCandidateDumpDirV74056 =
            Environment.GetEnvironmentVariable(
                "SHARPEMU_DEVICE_LOST_CANDIDATE_DUMP_DIR");
        private const ulong DeviceLostCandidateShaderV74056 =
            0x000000044859A200UL;
        private long _v74056DeviceLostCandidateTraceCount;
        private readonly HashSet<string> _v74056DumpedCandidateSpirv = new(
            StringComparer.Ordinal);

        private long _v7408LastResidencyTraceTick;
        private ulong _v7408LastAllocatedBytes;

        private ulong GetStandaloneTextureCacheBytesV7408()
        {
            ulong total = 0;
            foreach (var resource in _textureCache.Values)
            {
                if (!resource.Cached ||
                    !resource.OwnsStorage ||
                    resource.GuestImage is not null)
                {
                    continue;
                }

                total = checked(total + resource.V7408ResidentBytes);
            }

            return total;
        }

        private ulong GetDeferredStandaloneTextureBytesV7408()
        {
            ulong total = 0;
            foreach (var entry in _deferredTextureDestroys)
            {
                if (entry.Texture.GuestImage is null)
                {
                    total = checked(total + entry.Texture.V7408ResidentBytes);
                }
            }

            return total;
        }

        private ulong GetGuestBufferCacheBytesV7408()
        {
            ulong total = 0;
            foreach (var allocation in _guestBufferAllocations)
            {
                total = checked(total + allocation.Size);
            }

            return total;
        }

        private void TouchStandaloneTextureV7408(TextureResource resource)
        {
            if (!resource.Cached ||
                !resource.OwnsStorage ||
                resource.GuestImage is not null)
            {
                return;
            }

            resource.V7408LastUseSerial =
                Interlocked.Increment(ref _v7408StandaloneTextureUseSerial);
        }

        private void TrimStandaloneTextureCacheToBudgetV7408(
            TextureResource? preserve = null)
        {
            if (_batchOpen || _textureCache.Count == 0)
            {
                return;
            }

            var totalBytes = GetStandaloneTextureCacheBytesV7408();
            if (totalBytes <= V7408StandaloneTextureCacheBudgetBytes)
            {
                return;
            }

            var targetBytes =
                V7408StandaloneTextureCacheBudgetBytes * 3UL / 4UL;
            var retireTimeline = _submitTimeline;

            var candidates = _textureCache
                .Where(entry =>
                    !ReferenceEquals(entry.Value, preserve) &&
                    entry.Value.Cached &&
                    entry.Value.OwnsStorage &&
                    entry.Value.GuestImage is null &&
                    Volatile.Read(
                        ref entry.Value.SamplerAliasBorrowCountV74073) == 0)
                .OrderBy(entry => entry.Value.V7408LastUseSerial)
                .ThenByDescending(entry => entry.Value.V7408ResidentBytes)
                .ToArray();

            var evicted = 0;
            ulong evictedBytes = 0;
            foreach (var entry in candidates)
            {
                if (totalBytes <= targetBytes)
                {
                    break;
                }

                if (!_textureCache.Remove(entry.Key))
                {
                    continue;
                }

                var resource = entry.Value;
                UnmarkTextureContentCached(entry.Key);
                resource.Cached = false;
                resource.DeferredDestroyPendingV74055 = true;

                var bytes = resource.V7408ResidentBytes;
                totalBytes = bytes >= totalBytes ? 0 : totalBytes - bytes;
                evictedBytes = checked(evictedBytes + bytes);
                evicted++;

                _deferredTextureDestroys.Enqueue(
                    (resource, retireTimeline));
            }

            if (evicted != 0)
            {
