        private void TraceResidencyPressureV7408()
        {
            var now = Environment.TickCount64;
            var previous = Volatile.Read(ref _v7408LastResidencyTraceTick);
            if (previous != 0 && unchecked(now - previous) < 2000)
            {
                return;
            }

            Volatile.Write(ref _v7408LastResidencyTraceTick, now);

            var textureBytes = GetStandaloneTextureCacheBytesV7408();
            var deferredTextureBytes = GetDeferredStandaloneTextureBytesV7408();
            var guestBufferBytes = GetGuestBufferCacheBytesV7408();
            var gcBytes = (ulong)Math.Max(GC.GetTotalMemory(forceFullCollection: false), 0L);
            var allocatedBytes = (ulong)Math.Max(
                GC.GetTotalAllocatedBytes(precise: false),
                0L);
            var previousAllocated = _v7408LastAllocatedBytes;
            _v7408LastAllocatedBytes = allocatedBytes;
            var allocatedDelta =
                previousAllocated == 0 || allocatedBytes < previousAllocated
                    ? 0
                    : allocatedBytes - previousAllocated;

