                $"sampled_mb={_v7407SampledGuestImageBytes / (1024 * 1024)} " +
                $"guest_image_total_mb={guestImageBytesV74056 / (1024 * 1024)} " +
                $"guest_image_deferred_mb={deferredGuestImageBytesV74056 / (1024 * 1024)} " +
