            {
                return;
            }

            image.SampledCacheOnly = false;
            _v7407SampledGuestImageBytes =
                image.V7407ResidentBytes >= _v7407SampledGuestImageBytes
                    ? 0
                    : _v7407SampledGuestImageBytes - image.V7407ResidentBytes;

            var trace = Interlocked.Increment(
                ref _v7407SampledGuestImageTraceCount);
            if (trace <= 64 || (trace & (trace - 1)) == 0)
            {
                Console.Error.WriteLine(
                    $"[V74.0.7][GIMG_CACHE] promote addr=0x{image.Address:X16} " +
                    $"bytes={image.V7407ResidentBytes} reason={reason} " +
